window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[12]={"1200":{"example:1200:exzh":"Please sign here.","example:1200:exzh2":"He got a celebrity's autograph.","example:1200:exzh3":"The sign is in a conspicuous place.","example:1200:exzh4":"I want a book with an autograph in it.","example:1200:exzh5":"This sign is important.","grammar:1200:ex:trans":"Please sign here.","grammar:1200:ex:structure":"〜にサインしてください","grammar:1200:ex:explain":"The pattern is 「〜にサインする」: 「に」 marks the place where you sign, so 「ここにサインする」 means to sign here. 「サインする」 is a verb made from the loanword sign plus 「する」 (to sign). The ending 「サインしてください」 is a polite request: \"please sign.\" The whole sentence 「ここにサインしてください」 means \"please sign here,\" a phrase you often hear when doing paperwork.","grammar:1200:ex:words:0:zh":"here","grammar:1200:ex:words:0:pos":"pronoun","grammar:1200:ex:words:1:zh":"(place)","grammar:1200:ex:words:1:pos":"particle","grammar:1200:ex:words:2:zh":"to sign","grammar:1200:ex:words:2:pos":"verb","grammar:1200:ex:words:3:zh":"please","grammar:1200:ex:words:3:pos":"auxiliary verb","grammar:1200:ex:points:0":"❗サインする：to sign; 〜にサインする = to sign at …","grammar:1200:ex:points:1":"サインする：to sign.","grammar:1200:ex2:trans":"He got a celebrity's autograph.","grammar:1200:ex2:structure":"〜のサインをもらった","grammar:1200:ex2:words:0:zh":"he","grammar:1200:ex2:words:0:note":"かれ","grammar:1200:ex2:words:0:pos":"pronoun","grammar:1200:ex2:words:1:zh":"(topic)","grammar:1200:ex2:words:1:pos":"particle","grammar:1200:ex2:words:2:zh":"celebrity","grammar:1200:ex2:words:2:note":"ゆうめいじん","grammar:1200:ex2:words:2:pos":"noun","grammar:1200:ex2:words:3:zh":"'s","grammar:1200:ex2:words:3:pos":"particle","grammar:1200:ex2:words:4:zh":"to sign","grammar:1200:ex2:words:4:note":"loanword","grammar:1200:ex2:words:4:pos":"noun","grammar:1200:ex2:words:5:zh":"(object marker)","grammar:1200:ex2:words:5:pos":"particle","grammar:1200:ex2:words:6:zh":"got","grammar:1200:ex2:words:6:pos":"verb","grammar:1200:ex2:points:0":"❗サインをもらう：to get an autograph; 有名人 = celebrity.","grammar:1200:ex2:points:1":"もらう：to receive.","grammar:1200:ex3:trans":"The sign is in an eye-catching spot.","grammar:1200:ex3:structure":"〜は〜場所にあります","grammar:1200:ex3:words:0:zh":"emblem","grammar:1200:ex3:words:0:note":"loanword","grammar:1200:ex3:words:0:pos":"noun","grammar:1200:ex3:words:1:zh":"(topic)","grammar:1200:ex3:words:1:pos":"particle","grammar:1200:ex3:words:2:zh":"to stand out","grammar:1200:ex3:words:2:note":"めだつ","grammar:1200:ex3:words:2:pos":"verb","grammar:1200:ex3:words:3:zh":"place","grammar:1200:ex3:words:3:note":"ばしょ","grammar:1200:ex3:words:3:pos":"noun","grammar:1200:ex3:words:4:zh":"(location of existence)","grammar:1200:ex3:words:4:pos":"particle","grammar:1200:ex3:words:5:zh":"there is / are","grammar:1200:ex3:words:5:pos":"verb","grammar:1200:ex3:points:0":"❗サイン：sign, signage (not a signature here); 目立つ = to stand out.","grammar:1200:ex3:points:1":"目立つ場所：a conspicuous spot.","grammar:1200:ex4:trans":"I want a signed book.","grammar:1200:ex4:structure":"〜入りの〜が欲しいです","grammar:1200:ex4:words:0:zh":"with a signature","grammar:1200:ex4:words:0:note":"サインいり","grammar:1200:ex4:words:0:pos":"noun","grammar:1200:ex4:words:1:zh":"'s","grammar:1200:ex4:words:1:pos":"particle","grammar:1200:ex4:words:2:zh":"book","grammar:1200:ex4:words:2:note":"ほん","grammar:1200:ex4:words:2:pos":"noun","grammar:1200:ex4:words:3:zh":"(object)","grammar:1200:ex4:words:3:pos":"particle","grammar:1200:ex4:words:4:zh":"to want to","grammar:1200:ex4:words:4:note":"ほしい","grammar:1200:ex4:words:4:pos":"adjective","grammar:1200:ex4:words:5:zh":"(polite form)","grammar:1200:ex4:words:5:pos":"copula","grammar:1200:ex4:points:0":"❗サイン入り：signed, with a signature (サイン + 入り); 〜が欲しい = to want …","grammar:1200:ex4:points:1":"サイン入りの本：a signed book.","grammar:1200:ex5:trans":"This sign is important.","grammar:1200:ex5:structure":"〜は重要です","grammar:1200:ex5:words:0:zh":"this","grammar:1200:ex5:words:0:pos":"pre-noun adjectival","grammar:1200:ex5:words:1:zh":"emblem","grammar:1200:ex5:words:1:note":"loanword","grammar:1200:ex5:words:1:pos":"noun","grammar:1200:ex5:words:2:zh":"(topic)","grammar:1200:ex5:words:2:pos":"particle","grammar:1200:ex5:words:3:zh":"important","grammar:1200:ex5:words:3:note":"じゅうよう","grammar:1200:ex5:words:3:pos":"na-adjective","grammar:1200:ex5:words:4:zh":"(polite form)","grammar:1200:ex5:words:4:pos":"copula","grammar:1200:ex5:points:0":"このサイン：this sign / signal.","grammar:1200:ex5:points:1":"重要: important."},"1201":{"example:1201:exzh":"He didn't come after all.","example:1201:exzh2":"This is delicious after all.","example:1201:exzh3":"I do love Japan after all.","example:1201:exzh4":"Exercise really is necessary after all.","example:1201:exzh5":"That's difficult after all."},"1202":{"example:1202:exzh":"He went through painful feelings.","example:1202:exzh2":"This situation is hard.","example:1202:exzh3":"Her heart aches.","example:1202:exzh4":"When things are hard, please ask for help.","example:1202:exzh5":"It's hard, but I'll do my best."},"1203":{"example:1203:exzh":"He believes in liberalism.","example:1203:exzh2":"This country is a social democracy.","example:1203:exzh3":"There are more and more pacifists.","example:1203:exzh4":"She values egalitarianism.","example:1203:exzh5":"There are various kinds of ideologies."},"1204":{"example:1204:exzh":"My stomach hurts.","example:1204:exzh2":"His belly is big.","example:1204:exzh3":"He came home hungry.","example:1204:exzh4":"She is carrying a baby in her belly.","example:1204:exzh5":"I'm hungry, so I want to eat."},"1206":{"example:1206:exzh":"We met for the first time in a while.","example:1206:exzh2":"She is talking in a cheerful manner.","example:1206:exzh3":"It has the manner of a long-awaited reunion.","example:1206:exzh4":"This manner is quite big, isn't it.","example:1206:exzh5":"It had been a long time since we'd met, and it was fun."},"1207":{"example:1207:exzh":"This bag is super light.","example:1207:exzh2":"His speed is super fast.","example:1207:exzh3":"That flower is super beautiful.","example:1207:exzh4":"This is a super interesting movie.","example:1207:exzh5":"This game is super fun."},"1208":{"example:1208:exzh":"Has the package arrived already?","example:1208:exzh2":"That letter hasn't arrived yet.","example:1208:exzh3":"The present finally arrived.","example:1208:exzh4":"It took a while for the email to arrive.","example:1208:exzh5":"I'll do my best so that his voice gets through."},"1209":{"example:1209:exzh":"I'm leaving on a trip tomorrow.","example:1209:exzh2":"This trip was a lot of fun.","example:1209:exzh3":"Let's make a plan for the trip.","example:1209:exzh4":"She is traveling around the world.","example:1209:exzh5":"Traveling is my hobby."},"1210":{"example:1210:exzh":"Chinese food is delicious.","example:1210:exzh2":"I want to go to China.","example:1210:exzh3":"I'm studying Chinese.","example:1210:exzh4":"Chinese culture is interesting.","example:1210:exzh5":"Chinese history is long.","grammar:1210:ex:trans":"Chinese food is delicious.","grammar:1210:ex:structure":"〜の料理は美味しいです","grammar:1210:ex:explain":"This sentence demonstrates AのBは〜です, using の to link two nouns and show possession or origin; 中国の料理 means Chinese cuisine. は marks the topic, 美味しい is an i-adjective meaning delicious, and です makes the tone polite. Note that Japanese adjective sentences need no separate word for is — 美味しいです is already complete. です only adds politeness; it does not play the role of English is.","grammar:1210:ex:words:0:zh":"China","grammar:1210:ex:words:0:note":"ちゅうごく","grammar:1210:ex:words:0:pos":"noun","grammar:1210:ex:words:1:zh":"'s","grammar:1210:ex:words:1:pos":"particle","grammar:1210:ex:words:2:zh":"dish / cuisine","grammar:1210:ex:words:2:note":"りょうり","grammar:1210:ex:words:2:pos":"noun","grammar:1210:ex:words:3:zh":"(topic)","grammar:1210:ex:words:3:pos":"particle","grammar:1210:ex:words:4:zh":"delicious","grammar:1210:ex:words:4:note":"おいしい","grammar:1210:ex:words:4:pos":"adjective","grammar:1210:ex:words:5:zh":"(polite form)","grammar:1210:ex:words:5:pos":"copula","grammar:1210:ex:points:0":"❗中国 (ちゅうごく): China.","grammar:1210:ex:points:1":"中国の料理: Chinese food.","grammar:1210:ex2:trans":"I want to go to China.","grammar:1210:ex2:structure":"〜に行きたいです","grammar:1210:ex2:words:0:zh":"I","grammar:1210:ex2:words:0:note":"わたし","grammar:1210:ex2:words:0:pos":"pronoun","grammar:1210:ex2:words:1:zh":"(topic)","grammar:1210:ex2:words:1:pos":"particle","grammar:1210:ex2:words:2:zh":"China","grammar:1210:ex2:words:2:note":"ちゅうごく","grammar:1210:ex2:words:2:pos":"noun","grammar:1210:ex2:words:3:zh":"(destination)","grammar:1210:ex2:words:3:pos":"particle","grammar:1210:ex2:words:4:zh":"want to go","grammar:1210:ex2:words:4:note":"いきたい","grammar:1210:ex2:words:4:pos":"verb","grammar:1210:ex2:words:5:zh":"(polite form)","grammar:1210:ex2:words:5:pos":"copula","grammar:1210:ex2:points:0":"❗〜に行きたい: want to go to …; 〜たい = want to …","grammar:1210:ex2:points:1":"中国に行く: go to China.","grammar:1210:ex3:trans":"I'm studying Chinese.","grammar:1210:ex3:structure":"〜を勉強しています","grammar:1210:ex3:words:0:zh":"Chinese","grammar:1210:ex3:words:0:note":"ちゅうごくご","grammar:1210:ex3:words:0:pos":"noun","grammar:1210:ex3:words:1:zh":"(object marker)","grammar:1210:ex3:words:1:pos":"particle","grammar:1210:ex3:words:2:zh":"has been studying","grammar:1210:ex3:words:2:note":"べんきょうしています","grammar:1210:ex3:words:2:pos":"verb","grammar:1210:ex3:points:0":"❗中国語: Chinese (中国 + 語).","grammar:1210:ex3:points:1":"勉強する: to study.","grammar:1210:ex4:trans":"Chinese culture is interesting.","grammar:1210:ex4:structure":"〜の文化は面白いです","grammar:1210:ex4:words:0:zh":"China","grammar:1210:ex4:words:0:note":"ちゅうごく","grammar:1210:ex4:words:0:pos":"noun","grammar:1210:ex4:words:1:zh":"'s","grammar:1210:ex4:words:1:pos":"particle","grammar:1210:ex4:words:2:zh":"culture","grammar:1210:ex4:words:2:note":"ぶんか","grammar:1210:ex4:words:2:pos":"noun","grammar:1210:ex4:words:3:zh":"(topic)","grammar:1210:ex4:words:3:pos":"particle","grammar:1210:ex4:words:4:zh":"interesting","grammar:1210:ex4:words:4:note":"おもしろい","grammar:1210:ex4:words:4:pos":"adjective","grammar:1210:ex4:words:5:zh":"(polite form)","grammar:1210:ex4:words:5:pos":"copula","grammar:1210:ex4:points:0":"中国の文化: Chinese culture.","grammar:1210:ex4:points:1":"面白い: interesting, fun.","grammar:1210:ex5:trans":"China has a long history.","grammar:1210:ex5:structure":"〜の歴史は古いです","grammar:1210:ex5:words:0:zh":"China","grammar:1210:ex5:words:0:note":"ちゅうごく","grammar:1210:ex5:words:0:pos":"noun","grammar:1210:ex5:words:1:zh":"'s","grammar:1210:ex5:words:1:pos":"particle","grammar:1210:ex5:words:2:zh":"history","grammar:1210:ex5:words:2:note":"れきし","grammar:1210:ex5:words:2:pos":"noun","grammar:1210:ex5:words:3:zh":"(topic)","grammar:1210:ex5:words:3:pos":"particle","grammar:1210:ex5:words:4:zh":"long-standing","grammar:1210:ex5:words:4:note":"ふるい","grammar:1210:ex5:words:4:pos":"adjective","grammar:1210:ex5:words:5:zh":"(polite form)","grammar:1210:ex5:words:5:pos":"copula","grammar:1210:ex5:points:0":"中国の歴史: Chinese history.","grammar:1210:ex5:points:1":"古い: old, long-standing."},"1211":{"example:1211:exzh":"The exam date has been set.","example:1211:exzh2":"The project details will be decided.","example:1211:exzh3":"The trip plans have been decided.","example:1211:exzh4":"The results will be decided next week.","example:1211:exzh5":"Please let me know once your course in life is decided.","grammar:1211:ex:trans":"The exam date has been set.","grammar:1211:ex:structure":"〜が決まった","grammar:1211:ex:explain":"The key is the intransitive 「決まる」, meaning a matter gets decided, is settled; the subject is the thing decided (日), marked with 「が」, and no doer appears. Contrast it with the transitive 「決める」 (someone decides), which takes 「を」. Here 「試験の日が決まった」 emphasizes the result — the date got settled on its own, a very Japanese way of putting it, without stressing who made the call. 「決まった」 is the past form.","grammar:1211:ex:words:0:zh":"test","grammar:1211:ex:words:0:note":"しけん","grammar:1211:ex:words:0:pos":"noun","grammar:1211:ex:words:1:zh":"'s","grammar:1211:ex:words:1:pos":"particle","grammar:1211:ex:words:2:zh":"day","grammar:1211:ex:words:2:note":"ひ","grammar:1211:ex:words:2:pos":"noun","grammar:1211:ex:words:3:zh":"(nominative)","grammar:1211:ex:words:3:pos":"particle","grammar:1211:ex:words:4:zh":"decided","grammar:1211:ex:words:4:note":"きまった","grammar:1211:ex:words:4:pos":"verb","grammar:1211:ex:points:0":"❗決まる（きまる）: (for a matter) to be decided, to be settled (intransitive) + が; vs 決める (transitive, to decide) + を; 日が決まる = the date is set.","grammar:1211:ex:points:1":"決まる: to be settled.","grammar:1211:ex2:trans":"The project details will be finalized.","grammar:1211:ex2:structure":"〜が決まります","grammar:1211:ex2:words:0:zh":"project","grammar:1211:ex2:words:0:note":"loanword","grammar:1211:ex2:words:0:pos":"noun","grammar:1211:ex2:words:1:zh":"'s","grammar:1211:ex2:words:1:pos":"particle","grammar:1211:ex2:words:2:zh":"details","grammar:1211:ex2:words:2:note":"しょうさい","grammar:1211:ex2:words:2:pos":"noun","grammar:1211:ex2:words:3:zh":"(nominative)","grammar:1211:ex2:words:3:pos":"particle","grammar:1211:ex2:words:4:zh":"Certain","grammar:1211:ex2:words:4:note":"きまります","grammar:1211:ex2:words:4:pos":"verb","grammar:1211:ex2:points:0":"❗詳細が決まる: the details are settled; 詳細 = details.","grammar:1211:ex2:points:1":"詳細が決まる: the details are finalized.","grammar:1211:ex3:trans":"The travel plans have been decided.","grammar:1211:ex3:structure":"〜が決まりました","grammar:1211:ex3:words:0:zh":"travel / trip","grammar:1211:ex3:words:0:note":"りょこう","grammar:1211:ex3:words:0:pos":"noun","grammar:1211:ex3:words:1:zh":"'s","grammar:1211:ex3:words:1:pos":"particle","grammar:1211:ex3:words:2:zh":"plan","grammar:1211:ex3:words:2:note":"よてい","grammar:1211:ex3:words:2:pos":"noun","grammar:1211:ex3:words:3:zh":"(nominative)","grammar:1211:ex3:words:3:pos":"particle","grammar:1211:ex3:words:4:zh":"was decided","grammar:1211:ex3:words:4:note":"きまりました","grammar:1211:ex3:words:4:pos":"verb","grammar:1211:ex3:points:0":"❗予定が決まる: the schedule is set; 予定 = plan.","grammar:1211:ex3:points:1":"予定が決まる: the schedule is set.","grammar:1211:ex4:trans":"The results will be decided next week.","grammar:1211:ex4:structure":"〜は来週に決まります","grammar:1211:ex4:words:0:zh":"result","grammar:1211:ex4:words:0:note":"けっか","grammar:1211:ex4:words:0:pos":"noun","grammar:1211:ex4:words:1:zh":"(topic)","grammar:1211:ex4:words:1:pos":"particle","grammar:1211:ex4:words:2:zh":"next week","grammar:1211:ex4:words:2:note":"らいしゅう","grammar:1211:ex4:words:2:pos":"noun","grammar:1211:ex4:words:3:zh":"(point in time)","grammar:1211:ex4:words:3:pos":"particle","grammar:1211:ex4:words:4:zh":"decide","grammar:1211:ex4:words:4:note":"きまります","grammar:1211:ex4:words:4:pos":"verb","grammar:1211:ex4:points:0":"❗結果が決まる: the result is settled; 来週に = next week.","grammar:1211:ex4:points:1":"結果が決まる: the result is decided.","grammar:1211:ex5:trans":"Please tell me once your career path is decided.","grammar:1211:ex5:structure":"〜が決まったら教えてください","grammar:1211:ex5:words:0:zh":"you","grammar:1211:ex5:words:0:pos":"pronoun","grammar:1211:ex5:words:1:zh":"'s","grammar:1211:ex5:words:1:pos":"particle","grammar:1211:ex5:words:2:zh":"career path","grammar:1211:ex5:words:2:note":"しんろ","grammar:1211:ex5:words:2:pos":"noun","grammar:1211:ex5:words:3:zh":"(nominative)","grammar:1211:ex5:words:3:pos":"particle","grammar:1211:ex5:words:4:zh":"once decided","grammar:1211:ex5:words:4:note":"きまったら","grammar:1211:ex5:words:4:pos":"verb","grammar:1211:ex5:words:5:zh":"tell","grammar:1211:ex5:words:5:note":"おしえて","grammar:1211:ex5:words:5:pos":"verb","grammar:1211:ex5:words:6:zh":"please","grammar:1211:ex5:words:6:pos":"auxiliary verb","grammar:1211:ex5:points:0":"❗〜たら: after …, if …; 進路が決まる = one's path is decided.","grammar:1211:ex5:points:1":"進路が決まる: one's path is set."},"1212":{"example:1212:exzh":"Lisbon is the capital of Portugal.","example:1212:exzh2":"My friend lives in Lisbon.","example:1212:exzh3":"I did some sightseeing in Lisbon.","example:1212:exzh4":"The food in Lisbon is delicious.","example:1212:exzh5":"Lisbon is a very beautiful city."},"1213":{"example:1213:exzh":"This luggage is heavy.","example:1213:exzh2":"He is suffering from a serious illness.","example:1213:exzh3":"This chair is too heavy.","example:1213:exzh4":"Lifting heavy things is tough.","example:1213:exzh5":"They are carrying a heavy heart.","grammar:1213:ex:trans":"This luggage is heavy.","grammar:1213:ex:structure":"〜は重いです","grammar:1213:ex:explain":"This is a basic Aは〜です adjective sentence: は marks the topic この荷物, 重い is an i-adjective meaning heavy, and です makes the sentence polite. この is a pre-noun adjectival that directly modifies the noun 荷物. It is worth remembering the opposite word 軽い (light), since the two often appear as a pair. Japanese adjective sentences can end on their own — 重いです is already complete, and です is only for politeness, not a word for is.","grammar:1213:ex:words:0:zh":"this","grammar:1213:ex:words:0:pos":"pre-noun adjectival","grammar:1213:ex:words:1:zh":"luggage","grammar:1213:ex:words:1:note":"にもつ","grammar:1213:ex:words:1:pos":"noun","grammar:1213:ex:words:2:zh":"(topic)","grammar:1213:ex:words:2:pos":"particle","grammar:1213:ex:words:3:zh":"heavy","grammar:1213:ex:words:3:note":"おもい","grammar:1213:ex:words:3:pos":"adjective","grammar:1213:ex:words:4:zh":"(polite form)","grammar:1213:ex:words:4:pos":"copula","grammar:1213:ex:points:0":"❗重い (おもい): heavy; vs 軽い (light).","grammar:1213:ex:points:1":"荷物が重い: the luggage is heavy.","grammar:1213:ex2:trans":"He has a serious illness.","grammar:1213:ex2:structure":"〜を抱えています","grammar:1213:ex2:words:0:zh":"he","grammar:1213:ex2:words:0:note":"かれ","grammar:1213:ex2:words:0:pos":"pronoun","grammar:1213:ex2:words:1:zh":"(topic)","grammar:1213:ex2:words:1:pos":"particle","grammar:1213:ex2:words:2:zh":"serious","grammar:1213:ex2:words:2:note":"おもい","grammar:1213:ex2:words:2:pos":"adjective","grammar:1213:ex2:words:3:zh":"disease","grammar:1213:ex2:words:3:note":"びょうき","grammar:1213:ex2:words:3:pos":"noun","grammar:1213:ex2:words:4:zh":"(object marker)","grammar:1213:ex2:words:4:pos":"particle","grammar:1213:ex2:words:5:zh":"suffering from","grammar:1213:ex2:words:5:note":"かかえています","grammar:1213:ex2:words:5:pos":"verb","grammar:1213:ex2:points:0":"❗重い病気: a serious illness (重い = serious); 病気を抱える = to have an illness.","grammar:1213:ex2:points:1":"抱える: to carry, to bear.","grammar:1213:ex3:trans":"This chair is too heavy.","grammar:1213:ex3:structure":"〜は重すぎる","grammar:1213:ex3:words:0:zh":"this","grammar:1213:ex3:words:0:pos":"pre-noun adjectival","grammar:1213:ex3:words:1:zh":"chair","grammar:1213:ex3:words:1:note":"いす","grammar:1213:ex3:words:1:pos":"noun","grammar:1213:ex3:words:2:zh":"(topic)","grammar:1213:ex3:words:2:pos":"particle","grammar:1213:ex3:words:3:zh":"too heavy","grammar:1213:ex3:words:3:note":"おもすぎる","grammar:1213:ex3:words:3:pos":"adjective","grammar:1213:ex3:points:0":"❗〜すぎる: too … (重い→重すぎる).","grammar:1213:ex3:points:1":"椅子: chair.","grammar:1213:ex4:trans":"Carrying heavy things is hard work.","grammar:1213:ex4:structure":"〜を持つのは大変です","grammar:1213:ex4:words:0:zh":"heavy","grammar:1213:ex4:words:0:note":"おもい","grammar:1213:ex4:words:0:pos":"adjective","grammar:1213:ex4:words:1:zh":"things","grammar:1213:ex4:words:1:note":"もの","grammar:1213:ex4:words:1:pos":"noun","grammar:1213:ex4:words:2:zh":"(object marker)","grammar:1213:ex4:words:2:pos":"particle","grammar:1213:ex4:words:3:zh":"pick up","grammar:1213:ex4:words:3:note":"もつ","grammar:1213:ex4:words:3:pos":"verb","grammar:1213:ex4:words:4:zh":"(nominalizer)","grammar:1213:ex4:words:4:pos":"particle","grammar:1213:ex4:words:5:zh":"(topic)","grammar:1213:ex4:words:5:pos":"particle","grammar:1213:ex4:words:6:zh":"tough","grammar:1213:ex4:words:6:note":"たいへん","grammar:1213:ex4:words:6:pos":"na-adjective","grammar:1213:ex4:words:7:zh":"(polite form)","grammar:1213:ex4:words:7:pos":"copula","grammar:1213:ex4:points:0":"重い物: a heavy thing.","grammar:1213:ex4:points:1":"〜のは大変: doing … is tough.","grammar:1213:ex5:trans":"Holding a heavy feeling in one's heart.","grammar:1213:ex5:structure":"〜を抱えている","grammar:1213:ex5:words:0:zh":"heavy","grammar:1213:ex5:words:0:note":"おもい","grammar:1213:ex5:words:0:pos":"adjective","grammar:1213:ex5:words:1:zh":"feeling","grammar:1213:ex5:words:1:note":"きもち","grammar:1213:ex5:words:1:pos":"noun","grammar:1213:ex5:words:2:zh":"(object marker)","grammar:1213:ex5:words:2:pos":"particle","grammar:1213:ex5:words:3:zh":"carrying","grammar:1213:ex5:words:3:note":"かかえている","grammar:1213:ex5:words:3:pos":"verb","grammar:1213:ex5:points:0":"❗重い気持ち: a heavy heart (figurative); 気持ちを抱える = to hold a feeling.","grammar:1213:ex5:points:1":"重い気持ち: a heavy heart.","exam:1213:zh":"This box has a lot of books in it and is heavy, so one person can't carry it.","exam:1213:why":"Not being able to carry it because it's full of books means the box is 「重い」. 「軽い」 means light, the opposite of the clue that it can't be carried."},"1214":{"example:1214:exzh":"The delivery of the products is delayed.","example:1214:exzh2":"He is providing a service.","example:1214:exzh3":"Providing new technology is important.","example:1214:exzh4":"Could you provide some information?","example:1214:exzh5":"I'm waiting for you to share your opinion."},"1215":{"example:1215:exzh":"What time is tomorrow's meeting?","example:1215:exzh2":"Let's get ready before the meeting starts.","example:1215:exzh3":"He can't attend the meeting.","example:1215:exzh4":"It's necessary to decide the meeting's agenda.","example:1215:exzh5":"The meeting will be held online.","grammar:1215:ex:trans":"What time is tomorrow's meeting?","grammar:1215:ex:structure":"〜は何時ですか","grammar:1215:ex:explain":"This is a question built with the interrogative 何時; 〜は何時ですか asks what time something is. は marks the topic 明日の会議, and の links tomorrow with meeting. The ending ですか is the polite copula plus the question particle, forming a courteous question. Note that 何時 is read なんじ and asks for a clock time; do not confuse it with いつ (when, asking about a date or time period) — the two ask at different levels of precision.","grammar:1215:ex:words:0:zh":"tomorrow","grammar:1215:ex:words:0:note":"あした","grammar:1215:ex:words:0:pos":"noun","grammar:1215:ex:words:1:zh":"'s","grammar:1215:ex:words:1:pos":"particle","grammar:1215:ex:words:2:zh":"meeting","grammar:1215:ex:words:2:note":"かいぎ","grammar:1215:ex:words:2:pos":"noun","grammar:1215:ex:words:3:zh":"(topic)","grammar:1215:ex:words:3:pos":"particle","grammar:1215:ex:words:4:zh":"what time","grammar:1215:ex:words:4:note":"なんじ","grammar:1215:ex:words:4:pos":"pronoun","grammar:1215:ex:words:5:zh":"is","grammar:1215:ex:words:5:pos":"copula","grammar:1215:ex:words:6:zh":"(question)","grammar:1215:ex:words:6:pos":"particle","grammar:1215:ex:points:0":"❗会議 (かいぎ): meeting; 何時 = what time.","grammar:1215:ex:points:1":"明日の会議: tomorrow's meeting.","grammar:1215:ex2:trans":"Let's get ready before the meeting starts.","grammar:1215:ex2:structure":"〜が始まる前に〜しましょう","grammar:1215:ex2:words:0:zh":"meeting","grammar:1215:ex2:words:0:note":"かいぎ","grammar:1215:ex2:words:0:pos":"noun","grammar:1215:ex2:words:1:zh":"(nominative)","grammar:1215:ex2:words:1:pos":"particle","grammar:1215:ex2:words:2:zh":"begins","grammar:1215:ex2:words:2:note":"はじまる","grammar:1215:ex2:words:2:pos":"verb","grammar:1215:ex2:words:3:zh":"before","grammar:1215:ex2:words:3:note":"まえに","grammar:1215:ex2:words:3:pos":"particle","grammar:1215:ex2:words:4:zh":"let's prepare","grammar:1215:ex2:words:4:note":"じゅんびしましょう","grammar:1215:ex2:words:4:pos":"verb","grammar:1215:ex2:points:0":"❗〜前に: before …; 会議が始まる = the meeting starts.","grammar:1215:ex2:points:1":"準備しましょう: let's prepare.","grammar:1215:ex3:trans":"He can't attend the meeting.","grammar:1215:ex3:structure":"〜に参加できません","grammar:1215:ex3:words:0:zh":"he","grammar:1215:ex3:words:0:note":"かれ","grammar:1215:ex3:words:0:pos":"pronoun","grammar:1215:ex3:words:1:zh":"(topic)","grammar:1215:ex3:words:1:pos":"particle","grammar:1215:ex3:words:2:zh":"meeting","grammar:1215:ex3:words:2:note":"かいぎ","grammar:1215:ex3:words:2:pos":"noun","grammar:1215:ex3:words:3:zh":"(object)","grammar:1215:ex3:words:3:pos":"particle","grammar:1215:ex3:words:4:zh":"cannot attend","grammar:1215:ex3:words:4:note":"さんかできません","grammar:1215:ex3:words:4:pos":"verb","grammar:1215:ex3:points:0":"❗〜に参加できない: cannot attend … (potential negative of 参加する).","grammar:1215:ex3:points:1":"会議に参加: attend a meeting.","grammar:1215:ex4:trans":"We need to decide the meeting's agenda.","grammar:1215:ex4:structure":"〜を決める必要があります","grammar:1215:ex4:words:0:zh":"meeting","grammar:1215:ex4:words:0:note":"かいぎ","grammar:1215:ex4:words:0:pos":"noun","grammar:1215:ex4:words:1:zh":"'s","grammar:1215:ex4:words:1:pos":"particle","grammar:1215:ex4:words:2:zh":"agenda topic","grammar:1215:ex4:words:2:note":"ぎだい","grammar:1215:ex4:words:2:pos":"noun","grammar:1215:ex4:words:3:zh":"(object marker)","grammar:1215:ex4:words:3:pos":"particle","grammar:1215:ex4:words:4:zh":"decide","grammar:1215:ex4:words:4:note":"きめる","grammar:1215:ex4:words:4:pos":"verb","grammar:1215:ex4:words:5:zh":"necessary","grammar:1215:ex4:words:5:note":"ひつよう","grammar:1215:ex4:words:5:pos":"noun","grammar:1215:ex4:words:6:zh":"(nominative)","grammar:1215:ex4:words:6:pos":"particle","grammar:1215:ex4:words:7:zh":"there is / are","grammar:1215:ex4:words:7:pos":"verb","grammar:1215:ex4:points:0":"❗議題: agenda topic; 〜必要があります = it is necessary to …","grammar:1215:ex4:points:1":"議題を決める: decide the agenda.","grammar:1215:ex5:trans":"The meeting will be held online.","grammar:1215:ex5:structure":"〜で行われます","grammar:1215:ex5:words:0:zh":"meeting","grammar:1215:ex5:words:0:note":"かいぎ","grammar:1215:ex5:words:0:pos":"noun","grammar:1215:ex5:words:1:zh":"(topic)","grammar:1215:ex5:words:1:pos":"particle","grammar:1215:ex5:words:2:zh":"online","grammar:1215:ex5:words:2:note":"loanword","grammar:1215:ex5:words:2:pos":"noun","grammar:1215:ex5:words:3:zh":"(means)","grammar:1215:ex5:words:3:pos":"particle","grammar:1215:ex5:words:4:zh":"is held","grammar:1215:ex5:words:4:note":"おこなわれます","grammar:1215:ex5:words:4:pos":"verb","grammar:1215:ex5:points:0":"❗行われる: be held (passive form of 行う); オンラインで = online (で marks the means).","grammar:1215:ex5:points:1":"会議が行われる: a meeting is held."},"1216":{"example:1216:exzh":"His death made many people sad.","example:1216:exzh2":"The death rate is rising.","example:1216:exzh3":"It's important to investigate the cause of death.","example:1216:exzh4":"She finds it hard to accept the death.","example:1216:exzh5":"This figure is a statistic about deaths."},"1217":{"example:1217:exzh":"That chair is broken.","example:1217:exzh2":"This game breaks easily.","example:1217:exzh3":"He repaired the broken clock.","example:1217:exzh4":"This toy has broken.","example:1217:exzh5":"I found a broken car.","grammar:1217:ex:trans":"That chair is broken.","grammar:1217:ex:structure":"〜は壊れています","grammar:1217:ex:explain":"The core is the intransitive verb 壊れる, meaning something breaks or stops working; the subject is the broken item itself, and there is no agent. Contrast it with the transitive 壊す (someone breaks something). 壊れています uses 〜ている to express the continuing state after breaking — it is broken now — not progressive action. は marks the topic その椅子. This intransitive verb + ている pattern for a resulting state is very common, for example 開いている (is open).","grammar:1217:ex:words:0:zh":"that","grammar:1217:ex:words:0:pos":"pre-noun adjectival","grammar:1217:ex:words:1:zh":"chair","grammar:1217:ex:words:1:note":"いす","grammar:1217:ex:words:1:pos":"noun","grammar:1217:ex:words:2:zh":"(topic)","grammar:1217:ex:words:2:pos":"particle","grammar:1217:ex:words:3:zh":"is broken","grammar:1217:ex:words:3:note":"こわれています","grammar:1217:ex:words:3:pos":"verb","grammar:1217:ex:points:0":"❗壊れる (intransitive verb, to break) + が/は; vs 壊す (transitive verb, to break something).","grammar:1217:ex:points:1":"椅子が壊れる: the chair breaks.","grammar:1217:ex2:trans":"This game breaks easily.","grammar:1217:ex2:structure":"〜は壊れやすいです","grammar:1217:ex2:words:0:zh":"this","grammar:1217:ex2:words:0:pos":"pre-noun adjectival","grammar:1217:ex2:words:1:zh":"game","grammar:1217:ex2:words:1:note":"loanword","grammar:1217:ex2:words:1:pos":"noun","grammar:1217:ex2:words:2:zh":"(topic)","grammar:1217:ex2:words:2:pos":"particle","grammar:1217:ex2:words:3:zh":"breaks easily","grammar:1217:ex2:words:3:note":"こわれやすい","grammar:1217:ex2:words:3:pos":"adjective","grammar:1217:ex2:words:4:zh":"(polite form)","grammar:1217:ex2:words:4:pos":"copula","grammar:1217:ex2:points:0":"❗〜やすい: easy to … (壊れる→壊れやすい).","grammar:1217:ex2:points:1":"壊れやすい: breakable.","grammar:1217:ex3:trans":"He repaired the broken clock.","grammar:1217:ex3:structure":"壊れた〜を修理した","grammar:1217:ex3:words:0:zh":"he","grammar:1217:ex3:words:0:note":"かれ","grammar:1217:ex3:words:0:pos":"pronoun","grammar:1217:ex3:words:1:zh":"(topic)","grammar:1217:ex3:words:1:pos":"particle","grammar:1217:ex3:words:2:zh":"broken","grammar:1217:ex3:words:2:note":"こわれた","grammar:1217:ex3:words:2:pos":"verb","grammar:1217:ex3:words:3:zh":"watch","grammar:1217:ex3:words:3:note":"とけい","grammar:1217:ex3:words:3:pos":"noun","grammar:1217:ex3:words:4:zh":"(object marker)","grammar:1217:ex3:words:4:pos":"particle","grammar:1217:ex3:words:5:zh":"repaired","grammar:1217:ex3:words:5:note":"しゅうりした","grammar:1217:ex3:words:5:pos":"verb","grammar:1217:ex3:points:0":"❗壊れた時計: a broken watch (attributive); 修理する = repair.","grammar:1217:ex3:points:1":"時計: clock, watch.","grammar:1217:ex4:trans":"This toy broke.","grammar:1217:ex4:structure":"〜は壊れてしまった","grammar:1217:ex4:words:0:zh":"this","grammar:1217:ex4:words:0:pos":"pre-noun adjectival","grammar:1217:ex4:words:1:zh":"toy","grammar:1217:ex4:words:1:pos":"noun","grammar:1217:ex4:words:2:zh":"(topic)","grammar:1217:ex4:words:2:pos":"particle","grammar:1217:ex4:words:3:zh":"broke","grammar:1217:ex4:words:3:note":"こわれてしまった","grammar:1217:ex4:words:3:pos":"verb","grammar:1217:ex4:points:0":"❗〜てしまう: (accidentally / regrettably) ended up …","grammar:1217:ex4:points:1":"壊れてしまう: ended up broken.","grammar:1217:ex5:trans":"I found a broken car.","grammar:1217:ex5:structure":"壊れた〜を見つけました","grammar:1217:ex5:words:0:zh":"broken","grammar:1217:ex5:words:0:note":"こわれた","grammar:1217:ex5:words:0:pos":"verb","grammar:1217:ex5:words:1:zh":"car","grammar:1217:ex5:words:1:note":"くるま","grammar:1217:ex5:words:1:pos":"noun","grammar:1217:ex5:words:2:zh":"(object marker)","grammar:1217:ex5:words:2:pos":"particle","grammar:1217:ex5:words:3:zh":"discovered","grammar:1217:ex5:words:3:note":"みつけました","grammar:1217:ex5:words:3:pos":"verb","grammar:1217:ex5:points:0":"壊れた車: a broken car.","grammar:1217:ex5:points:1":"見つける：to find."},"1218":{"example:1218:exzh":"When are you going to France?","example:1218:exzh2":"I like French food.","example:1218:exzh3":"She lives in France.","example:1218:exzh4":"I want to learn about French culture.","example:1218:exzh5":"France's sightseeing spots are wonderful.","grammar:1218:ex:trans":"When are you going to France?","grammar:1218:ex:structure":"〜にはいつ行きますか","grammar:1218:ex:explain":"This sentence uses the interrogative いつ to ask about a point in time; いつ行きますか means when are you going. Note には: に marks the destination フランス, and は is added after it for contrast and emphasis, suggesting as for France, when do you plan to go? — it singles France out as the topic. 行きます is the polite form and か makes it a question. This stacked には is very common in casual speech.","grammar:1218:ex:words:0:zh":"France","grammar:1218:ex:words:0:note":"loanword","grammar:1218:ex:words:0:pos":"noun","grammar:1218:ex:words:1:zh":"(destination)","grammar:1218:ex:words:1:pos":"particle","grammar:1218:ex:words:2:zh":"(contrast)","grammar:1218:ex:words:2:pos":"particle","grammar:1218:ex:words:3:zh":"when","grammar:1218:ex:words:3:pos":"pronoun","grammar:1218:ex:words:4:zh":"go","grammar:1218:ex:words:4:pos":"verb","grammar:1218:ex:words:5:zh":"(question)","grammar:1218:ex:words:5:pos":"particle","grammar:1218:ex:points:0":"❗フランス: France; いつ = when.","grammar:1218:ex:points:1":"フランスに行く: go to France.","grammar:1218:ex2:trans":"I like French food.","grammar:1218:ex2:structure":"〜が好きです","grammar:1218:ex2:words:0:zh":"French cuisine","grammar:1218:ex2:words:0:note":"フランスりょうり","grammar:1218:ex2:words:0:pos":"noun","grammar:1218:ex2:words:1:zh":"(object)","grammar:1218:ex2:words:1:pos":"particle","grammar:1218:ex2:words:2:zh":"to like","grammar:1218:ex2:words:2:note":"すき","grammar:1218:ex2:words:2:pos":"na-adjective","grammar:1218:ex2:words:3:zh":"(polite form)","grammar:1218:ex2:words:3:pos":"copula","grammar:1218:ex2:points:0":"❗フランス料理: French cuisine.","grammar:1218:ex2:points:1":"〜が好き: to like …","grammar:1218:ex3:trans":"She lives in France.","grammar:1218:ex3:structure":"〜に住んでいます","grammar:1218:ex3:words:0:zh":"she","grammar:1218:ex3:words:0:note":"かのじょ","grammar:1218:ex3:words:0:pos":"pronoun","grammar:1218:ex3:words:1:zh":"(topic)","grammar:1218:ex3:words:1:pos":"particle","grammar:1218:ex3:words:2:zh":"France","grammar:1218:ex3:words:2:note":"loanword","grammar:1218:ex3:words:2:pos":"noun","grammar:1218:ex3:words:3:zh":"(place of residence)","grammar:1218:ex3:words:3:pos":"particle","grammar:1218:ex3:words:4:zh":"are living","grammar:1218:ex3:words:4:note":"すんでいます","grammar:1218:ex3:words:4:pos":"verb","grammar:1218:ex3:points:0":"❗〜に住む: to live in…","grammar:1218:ex3:points:1":"フランスに住む: live in France.","grammar:1218:ex4:trans":"I want to learn about French culture.","grammar:1218:ex4:structure":"〜について学びたい","grammar:1218:ex4:words:0:zh":"France","grammar:1218:ex4:words:0:note":"loanword","grammar:1218:ex4:words:0:pos":"noun","grammar:1218:ex4:words:1:zh":"'s","grammar:1218:ex4:words:1:pos":"particle","grammar:1218:ex4:words:2:zh":"culture","grammar:1218:ex4:words:2:note":"ぶんか","grammar:1218:ex4:words:2:pos":"noun","grammar:1218:ex4:words:3:zh":"about","grammar:1218:ex4:words:3:pos":"set phrase","grammar:1218:ex4:words:4:zh":"want to learn","grammar:1218:ex4:words:4:note":"まなびたい","grammar:1218:ex4:words:4:pos":"verb","grammar:1218:ex4:points:0":"❗〜について学ぶ: learn about …; 〜たい = want to …","grammar:1218:ex4:points:1":"フランスの文化: French culture.","grammar:1218:ex5:trans":"France's sightseeing spots are wonderful.","grammar:1218:ex5:structure":"〜は素晴らしいです","grammar:1218:ex5:words:0:zh":"France","grammar:1218:ex5:words:0:note":"loanword","grammar:1218:ex5:words:0:pos":"noun","grammar:1218:ex5:words:1:zh":"'s","grammar:1218:ex5:words:1:pos":"particle","grammar:1218:ex5:words:2:zh":"tourist attractions","grammar:1218:ex5:words:2:note":"かんこうち","grammar:1218:ex5:words:2:pos":"noun","grammar:1218:ex5:words:3:zh":"(topic)","grammar:1218:ex5:words:3:pos":"particle","grammar:1218:ex5:words:4:zh":"great","grammar:1218:ex5:words:4:note":"すばらしい","grammar:1218:ex5:words:4:pos":"adjective","grammar:1218:ex5:words:5:zh":"(polite form)","grammar:1218:ex5:words:5:pos":"copula","grammar:1218:ex5:points:0":"❗観光地: tourist spot; 素晴らしい = wonderful.","grammar:1218:ex5:points:1":"観光地: sightseeing spot."},"1220":{"example:1220:exzh":"He had conviction in his own ideas.","example:1220:exzh2":"With conviction, you can act.","example:1220:exzh3":"She is confident about the result.","example:1220:exzh4":"Conviction is an important element.","example:1220:exzh5":"I'm confident that I'll succeed."},"1221":{"example:1221:exzh":"We're developing a new program.","example:1221:exzh2":"Did you copy the program?","example:1221:exzh3":"This program is easy to use.","example:1221:exzh4":"The program needs to be updated.","example:1221:exzh5":"He started learning programming."},"1222":{"example:1222:exzh":"I'll take my luggage and go to the station.","example:1222:exzh2":"This luggage is heavy.","example:1222:exzh3":"Where do I leave my luggage?","example:1222:exzh4":"Has the luggage arrived?","example:1222:exzh5":"Carry-on baggage can be brought into the cabin.","grammar:1222:ex:trans":"I'll take the luggage to the station.","grammar:1222:ex:structure":"〜を持って〜に行きます","grammar:1222:ex:explain":"This sentence links two actions, and the key pattern is 「〜を持って〜に行く」. 「持って」 is the te-form of 「持つ」, joining the two actions: carrying the luggage and then going to the station — in other words, doing the next thing while holding a certain state. The object 「荷物」 takes 「を」, and the destination 「駅」 takes 「に」. The te-form is the main way Japanese strings actions together, and this “take A and go to B” phrasing is very everyday.","grammar:1222:ex:words:0:zh":"luggage","grammar:1222:ex:words:0:note":"にもつ","grammar:1222:ex:words:0:pos":"noun","grammar:1222:ex:words:1:zh":"(object marker)","grammar:1222:ex:words:1:pos":"particle","grammar:1222:ex:words:2:zh":"pick up","grammar:1222:ex:words:2:note":"もって","grammar:1222:ex:words:2:pos":"verb","grammar:1222:ex:words:3:zh":"station","grammar:1222:ex:words:3:note":"えき","grammar:1222:ex:words:3:pos":"noun","grammar:1222:ex:words:4:zh":"(destination)","grammar:1222:ex:words:4:pos":"particle","grammar:1222:ex:words:5:zh":"go","grammar:1222:ex:words:5:pos":"verb","grammar:1222:ex:points:0":"❗「荷物（にもつ）」: luggage, baggage; 「〜を持って行く」＝ to take… with you.","grammar:1222:ex:points:1":"「荷物を持つ」: to carry luggage.","grammar:1222:ex2:trans":"This luggage is heavy.","grammar:1222:ex2:structure":"〜は重いです","grammar:1222:ex2:words:0:zh":"this","grammar:1222:ex2:words:0:pos":"pre-noun adjectival","grammar:1222:ex2:words:1:zh":"luggage","grammar:1222:ex2:words:1:note":"にもつ","grammar:1222:ex2:words:1:pos":"noun","grammar:1222:ex2:words:2:zh":"(topic)","grammar:1222:ex2:words:2:pos":"particle","grammar:1222:ex2:words:3:zh":"heavy","grammar:1222:ex2:words:3:note":"おもい","grammar:1222:ex2:words:3:pos":"adjective","grammar:1222:ex2:words:4:zh":"(polite form)","grammar:1222:ex2:words:4:pos":"copula","grammar:1222:ex2:points:0":"荷物が重い: the luggage is heavy.","grammar:1222:ex2:points:1":"重い: heavy.","grammar:1222:ex3:trans":"Where is the place to leave luggage?","grammar:1222:ex3:structure":"〜を預ける場所はどこですか","grammar:1222:ex3:words:0:zh":"luggage","grammar:1222:ex3:words:0:note":"にもつ","grammar:1222:ex3:words:0:pos":"noun","grammar:1222:ex3:words:1:zh":"(object marker)","grammar:1222:ex3:words:1:pos":"particle","grammar:1222:ex3:words:2:zh":"leave in safekeeping","grammar:1222:ex3:words:2:note":"あずける","grammar:1222:ex3:words:2:pos":"verb","grammar:1222:ex3:words:3:zh":"place","grammar:1222:ex3:words:3:note":"ばしょ","grammar:1222:ex3:words:3:pos":"noun","grammar:1222:ex3:words:4:zh":"(topic)","grammar:1222:ex3:words:4:pos":"particle","grammar:1222:ex3:words:5:zh":"where","grammar:1222:ex3:words:5:pos":"pronoun","grammar:1222:ex3:words:6:zh":"is","grammar:1222:ex3:words:6:pos":"copula","grammar:1222:ex3:words:7:zh":"(question)","grammar:1222:ex3:words:7:pos":"particle","grammar:1222:ex3:points:0":"❗「荷物を預ける」: to leave luggage (「預ける」＝ to check, to leave in someone's care).","grammar:1222:ex3:points:1":"「預ける場所」: a place to leave things.","grammar:1222:ex4:trans":"Has the luggage arrived?","grammar:1222:ex4:structure":"〜が届きましたか","grammar:1222:ex4:words:0:zh":"luggage","grammar:1222:ex4:words:0:note":"にもつ","grammar:1222:ex4:words:0:pos":"noun","grammar:1222:ex4:words:1:zh":"(nominative)","grammar:1222:ex4:words:1:pos":"particle","grammar:1222:ex4:words:2:zh":"arrived","grammar:1222:ex4:words:2:note":"とどきました","grammar:1222:ex4:words:2:pos":"verb","grammar:1222:ex4:words:3:zh":"(question)","grammar:1222:ex4:words:3:pos":"particle","grammar:1222:ex4:points:0":"❗「届く」: to arrive, to be delivered (intransitive verb).","grammar:1222:ex4:points:1":"「荷物が届く」: the luggage arrives.","grammar:1222:ex5:trans":"Carry-on baggage can be brought into the cabin.","grammar:1222:ex5:structure":"〜に持ち込みできます","grammar:1222:ex5:words:0:zh":"carry-on baggage","grammar:1222:ex5:words:0:note":"てにもつ","grammar:1222:ex5:words:0:pos":"noun","grammar:1222:ex5:words:1:zh":"(topic)","grammar:1222:ex5:words:1:pos":"particle","grammar:1222:ex5:words:2:zh":"cabin","grammar:1222:ex5:words:2:note":"きない","grammar:1222:ex5:words:2:pos":"noun","grammar:1222:ex5:words:3:zh":"(the destination point)","grammar:1222:ex5:words:3:pos":"particle","grammar:1222:ex5:words:4:zh":"can be brought in","grammar:1222:ex5:words:4:note":"もちこみできます","grammar:1222:ex5:words:4:pos":"verb","grammar:1222:ex5:points:0":"❗「手荷物」: carry-on baggage; 「持ち込む」＝ to bring in (「持つ」＋「込む」).","grammar:1222:ex5:points:1":"「機内に持ち込む」: to bring into the cabin."},"1223":{"example:1223:exzh":"It's important to avoid danger.","example:1223:exzh2":"I avoid that place and go around it.","example:1223:exzh3":"He is trying to avoid stress.","example:1223:exzh4":"It's an unavoidable problem.","example:1223:exzh5":"You need to avoid food allergies."},"1224":{"example:1224:exzh":"Patient people succeed.","example:1224:exzh2":"Sometimes patience is needed.","example:1224:exzh3":"I'm grateful for her patience.","example:1224:exzh4":"When you are patient, you grow as a person.","example:1224:exzh5":"Learning patience is important."},"1225":{"example:1225:exzh":"That road is dangerous.","example:1225:exzh2":"Please don't do dangerous things.","example:1225:exzh3":"That place is dangerous, so you can't go there.","example:1225:exzh4":"It's dangerous to get close to fire.","example:1225:exzh5":"Don't drive dangerously.","grammar:1225:ex:trans":"That road is dangerous.","grammar:1225:ex:structure":"〜は危ないです","grammar:1225:ex:explain":"This is a basic 「Aは〜です」 adjective sentence, where 「危ない」 is an i-adjective meaning dangerous. 「は」 marks the topic 「あの道」, and 「あの」 is a pre-noun adjectival pointing to a “that” further away. 「です」 makes the sentence polite, though the adjective can end a sentence on its own, so 「危ないです」 is complete. Remember that besides describing real danger, 「危ない」 also works in casual speech as a warning shout — “Watch out! That's dangerous!” — so it comes up in many situations.","grammar:1225:ex:words:0:zh":"that","grammar:1225:ex:words:0:pos":"pre-noun adjectival","grammar:1225:ex:words:1:zh":"road","grammar:1225:ex:words:1:note":"みち","grammar:1225:ex:words:1:pos":"noun","grammar:1225:ex:words:2:zh":"(topic)","grammar:1225:ex:words:2:pos":"particle","grammar:1225:ex:words:3:zh":"dangerous","grammar:1225:ex:words:3:note":"あぶない","grammar:1225:ex:words:3:pos":"adjective","grammar:1225:ex:words:4:zh":"(polite form)","grammar:1225:ex:words:4:pos":"copula","grammar:1225:ex:points:0":"❗「危ない（あぶない）」: dangerous (i-adjective).","grammar:1225:ex:points:1":"「危ない道」: a dangerous road.","grammar:1225:ex2:trans":"Please don't do anything dangerous.","grammar:1225:ex2:structure":"危ないことをしないでください","grammar:1225:ex2:words:0:zh":"dangerous","grammar:1225:ex2:words:0:note":"あぶない","grammar:1225:ex2:words:0:pos":"adjective","grammar:1225:ex2:words:1:zh":"thing / matter","grammar:1225:ex2:words:1:pos":"noun","grammar:1225:ex2:words:2:zh":"(object marker)","grammar:1225:ex2:words:2:pos":"particle","grammar:1225:ex2:words:3:zh":"don't do (it)","grammar:1225:ex2:words:3:pos":"verb","grammar:1225:ex2:words:4:zh":"please","grammar:1225:ex2:words:4:pos":"auxiliary verb","grammar:1225:ex2:points:0":"❗「〜ないでください」: please don't…; 「危ないこと」＝ something dangerous.","grammar:1225:ex2:points:1":"「危ないこと」: something dangerous.","grammar:1225:ex3:trans":"That place is dangerous, so you can't go there.","grammar:1225:ex3:structure":"〜は危なくて〜ません","grammar:1225:ex3:words:0:zh":"that","grammar:1225:ex3:words:0:pos":"pre-noun adjectival","grammar:1225:ex3:words:1:zh":"place","grammar:1225:ex3:words:1:note":"ばしょ","grammar:1225:ex3:words:1:pos":"noun","grammar:1225:ex3:words:2:zh":"(topic)","grammar:1225:ex3:words:2:pos":"particle","grammar:1225:ex3:words:3:zh":"dangerous and so","grammar:1225:ex3:words:3:note":"あぶなくて","grammar:1225:ex3:words:3:pos":"adjective","grammar:1225:ex3:words:4:zh":"can't go","grammar:1225:ex3:words:4:note":"いけません","grammar:1225:ex3:words:4:pos":"verb","grammar:1225:ex3:points:0":"❗「〜くて」: because… (the conjunctive form of an i-adjective); 「行けない」＝ can't go (negative potential).","grammar:1225:ex3:points:1":"「危なくて行けない」: it's dangerous, so I can't go.","grammar:1225:ex4:trans":"It's dangerous to get close to fire.","grammar:1225:ex4:structure":"〜に近づくと危ないです","grammar:1225:ex4:words:0:zh":"fire","grammar:1225:ex4:words:0:note":"ひ","grammar:1225:ex4:words:0:pos":"noun","grammar:1225:ex4:words:1:zh":"(object)","grammar:1225:ex4:words:1:pos":"particle","grammar:1225:ex4:words:2:zh":"get near","grammar:1225:ex4:words:2:note":"ちかづく","grammar:1225:ex4:words:2:pos":"verb","grammar:1225:ex4:words:3:zh":"(as soon as…)","grammar:1225:ex4:words:3:pos":"particle","grammar:1225:ex4:words:4:zh":"dangerous","grammar:1225:ex4:words:4:note":"あぶない","grammar:1225:ex4:words:4:pos":"adjective","grammar:1225:ex4:words:5:zh":"(polite form)","grammar:1225:ex4:words:5:pos":"copula","grammar:1225:ex4:points:0":"❗「〜に近づく」: to get close to…; 「〜と危ない」＝ it's dangerous once you…","grammar:1225:ex4:points:1":"「火に近づく」: to get close to fire.","grammar:1225:ex5:trans":"Don't drive dangerously.","grammar:1225:ex5:structure":"〜をしないように","grammar:1225:ex5:words:0:zh":"dangerous","grammar:1225:ex5:words:0:note":"あぶない","grammar:1225:ex5:words:0:pos":"adjective","grammar:1225:ex5:words:1:zh":"driving","grammar:1225:ex5:words:1:note":"うんてん","grammar:1225:ex5:words:1:pos":"noun","grammar:1225:ex5:words:2:zh":"(object marker)","grammar:1225:ex5:words:2:pos":"particle","grammar:1225:ex5:words:3:zh":"not do","grammar:1225:ex5:words:3:pos":"verb","grammar:1225:ex5:words:4:zh":"(a reminder)","grammar:1225:ex5:words:4:pos":"set phrase","grammar:1225:ex5:points:0":"❗「〜ないように」: (a reminder) don't…, so as not to…; 「運転」＝ driving.","grammar:1225:ex5:points:1":"「危ない運転」: dangerous driving."},"1226":{"example:1226:exzh":"Please submit the documents.","example:1226:exzh2":"These documents are important.","example:1226:exzh3":"Organizing documents is a hassle.","example:1226:exzh4":"Please sign the documents.","example:1226:exzh5":"Did you copy the documents?"},"1227":{"example:1227:exzh":"Nature has many beautiful places.","example:1227:exzh2":"Let's treasure nature.","example:1227:exzh3":"Relax in nature.","example:1227:exzh4":"We take action to protect nature.","example:1227:exzh5":"I like nature."},"1228":{"example:1228:exzh":"Setting goals is important.","example:1228:exzh2":"His goal is to get into university.","example:1228:exzh3":"You need clear goals.","example:1228:exzh4":"I'll work hard toward my goal.","example:1228:exzh5":"To achieve your goal, you need a plan."},"1229":{"example:1229:exzh":"This medication is very effective.","example:1229:exzh2":"It's important to choose the right type of medication.","example:1229:exzh3":"A new medication comes onto the market.","example:1229:exzh4":"This medication is easy to swallow.","example:1229:exzh5":"Please use the medication properly."},"1230":{"example:1230:exzh":"We received a project request.","example:1230:exzh2":"I'll try asking him.","example:1230:exzh3":"I'll accept the request and start work.","example:1230:exzh4":"Please check the details of the request.","example:1230:exzh5":"Thank you for asking me."},"1231":{"example:1231:exzh":"You can rest easy.","example:1231:exzh2":"Seeing you all made me feel relieved.","example:1231:exzh3":"This place is safe and reassuring.","example:1231:exzh4":"Please sleep with peace of mind.","example:1231:exzh5":"You need an environment where you can feel at ease.","grammar:1231:ex:trans":"You can relax.","grammar:1231:ex:structure":"〜ていいですよ","grammar:1231:ex:explain":"The key is the 「〜ていい」 pattern, meaning it's okay or allowed to do something. 「安心して」 is the te-form of 「安心する」, and adding 「いい」 gives “you can relax.” The 「よ」 in sentence-final 「ですよ」 is a particle that offers information or a heads-up, with a tone that soothes the listener and gives reassurance. The sentence is often used to comfort someone and feels warm. Remember that 「〜てもいい」 is the core pattern for permission — here the 「も」 is dropped.","grammar:1231:ex:words:0:zh":"feel at ease","grammar:1231:ex:words:0:note":"あんしんして","grammar:1231:ex:words:0:pos":"verb","grammar:1231:ex:words:1:zh":"good","grammar:1231:ex:words:1:pos":"adjective","grammar:1231:ex:words:2:zh":"(polite form)","grammar:1231:ex:words:2:pos":"copula","grammar:1231:ex:words:3:zh":"(a heads-up)","grammar:1231:ex:words:3:pos":"particle","grammar:1231:ex:points:0":"❗「〜ていい」: it's okay to…; 「安心する」＝ to feel relieved.","grammar:1231:ex:points:1":"「安心していい」: you can relax.","grammar:1231:ex2:trans":"I felt relieved when I saw you all.","grammar:1231:ex2:structure":"〜を見て安心しました","grammar:1231:ex2:words:0:zh":"everyone","grammar:1231:ex2:words:0:note":"みなさん","grammar:1231:ex2:words:0:pos":"noun","grammar:1231:ex2:words:1:zh":"(object marker)","grammar:1231:ex2:words:1:pos":"particle","grammar:1231:ex2:words:2:zh":"look","grammar:1231:ex2:words:2:note":"みて","grammar:1231:ex2:words:2:pos":"verb","grammar:1231:ex2:words:3:zh":"felt relieved","grammar:1231:ex2:words:3:note":"あんしんしました","grammar:1231:ex2:words:3:pos":"verb","grammar:1231:ex2:points:0":"❗「〜を見て安心する」: to feel relieved at the sight of…","grammar:1231:ex2:points:1":"「皆さん」: everyone.","grammar:1231:ex3:trans":"This place is safe and reassuring.","grammar:1231:ex3:structure":"〜は〜で〜です","grammar:1231:ex3:words:0:zh":"this","grammar:1231:ex3:words:0:pos":"pre-noun adjectival","grammar:1231:ex3:words:1:zh":"place","grammar:1231:ex3:words:1:note":"ばしょ","grammar:1231:ex3:words:1:pos":"noun","grammar:1231:ex3:words:2:zh":"(topic)","grammar:1231:ex3:words:2:pos":"particle","grammar:1231:ex3:words:3:zh":"safe","grammar:1231:ex3:words:3:note":"あんぜん","grammar:1231:ex3:words:3:pos":"na-adjective","grammar:1231:ex3:words:4:zh":"(listing)","grammar:1231:ex3:words:4:pos":"particle","grammar:1231:ex3:words:5:zh":"feel at ease","grammar:1231:ex3:words:5:note":"あんしん","grammar:1231:ex3:words:5:pos":"na-adjective","grammar:1231:ex3:words:6:zh":"(polite form)","grammar:1231:ex3:words:6:pos":"copula","grammar:1231:ex3:points:0":"❗「〜で〜」: both… and… (linking na-adjectives); 「安全で安心」＝ safe and reassuring.","grammar:1231:ex3:points:1":"安全: safety.","grammar:1231:ex4:trans":"Please sleep with peace of mind.","grammar:1231:ex4:structure":"安心して〜てください","grammar:1231:ex4:words:0:zh":"feel at ease","grammar:1231:ex4:words:0:note":"あんしんして","grammar:1231:ex4:words:0:pos":"verb","grammar:1231:ex4:words:1:zh":"sleep","grammar:1231:ex4:words:1:note":"ねむって","grammar:1231:ex4:words:1:pos":"verb","grammar:1231:ex4:words:2:zh":"please","grammar:1231:ex4:words:2:pos":"auxiliary verb","grammar:1231:ex4:points:0":"❗「安心して〜」: …with peace of mind (「安心して」 works as an adverb); 「眠る」＝ to sleep.","grammar:1231:ex4:points:1":"「安心して眠る」: to sleep peacefully.","grammar:1231:ex5:trans":"You need an environment where you can feel at ease.","grammar:1231:ex5:structure":"安心できる〜が必要です","grammar:1231:ex5:words:0:zh":"can feel at ease","grammar:1231:ex5:words:0:note":"あんしんできる","grammar:1231:ex5:words:0:pos":"verb","grammar:1231:ex5:words:1:zh":"environment","grammar:1231:ex5:words:1:note":"かんきょう","grammar:1231:ex5:words:1:pos":"noun","grammar:1231:ex5:words:2:zh":"(nominative)","grammar:1231:ex5:words:2:pos":"particle","grammar:1231:ex5:words:3:zh":"necessary","grammar:1231:ex5:words:3:note":"ひつよう","grammar:1231:ex5:words:3:pos":"na-adjective","grammar:1231:ex5:words:4:zh":"(polite form)","grammar:1231:ex5:words:4:pos":"copula","grammar:1231:ex5:points:0":"❗「安心できる」: reassuring (the potential form used to modify a noun); 「環境」＝ environment.","grammar:1231:ex5:points:1":"「安心できる環境」: a reassuring environment."},"1232":{"example:1232:exzh":"Tokyo is in the north of Japan.","example:1232:exzh2":"As you go north, there's more snow.","example:1232:exzh3":"The north wind is cold.","example:1232:exzh4":"North America is a vast region.","example:1232:exzh5":"There is ice at the North Pole.","grammar:1232:ex:trans":"Tokyo is in the north of Japan.","grammar:1232:ex:structure":"〜の北にあります","grammar:1232:ex:explain":"This is the existence pattern 「〜の〜にあります」, used to state where something is located. In 「日本の北に」, 「に」 marks the location, and 「あります」 is the polite form of 「ある」, used for inanimate things and places. The direction word 「北」 is linked with 「の」, so 「日本の北」 means the north of Japan. 「は」 marks the topic 「東京」. This pattern for describing geographic location with direction words is very useful, as in 「駅の前にある」.","grammar:1232:ex:words:0:zh":"Tokyo","grammar:1232:ex:words:0:note":"とうきょう","grammar:1232:ex:words:0:pos":"noun","grammar:1232:ex:words:1:zh":"(topic)","grammar:1232:ex:words:1:pos":"particle","grammar:1232:ex:words:2:zh":"Japan","grammar:1232:ex:words:2:note":"にほん","grammar:1232:ex:words:2:pos":"noun","grammar:1232:ex:words:3:zh":"'s","grammar:1232:ex:words:3:pos":"particle","grammar:1232:ex:words:4:zh":"north","grammar:1232:ex:words:4:note":"きた","grammar:1232:ex:words:4:pos":"noun","grammar:1232:ex:words:5:zh":"(location of existence)","grammar:1232:ex:words:5:pos":"particle","grammar:1232:ex:words:6:zh":"there is / are","grammar:1232:ex:words:6:pos":"verb","grammar:1232:ex:points:0":"❗「北（きた）」: north; 「〜の北にある」＝ to be north of…","grammar:1232:ex:points:1":"「日本の北」: the north of Japan.","grammar:1232:ex2:trans":"If you go north, you'll see more snow.","grammar:1232:ex2:structure":"北へ行くと、〜くなります","grammar:1232:ex2:words:0:zh":"north","grammar:1232:ex2:words:0:note":"きた","grammar:1232:ex2:words:0:pos":"noun","grammar:1232:ex2:words:1:zh":"(direction)","grammar:1232:ex2:words:1:pos":"particle","grammar:1232:ex2:words:2:zh":"go","grammar:1232:ex2:words:2:note":"いく","grammar:1232:ex2:words:2:pos":"verb","grammar:1232:ex2:words:3:zh":"(as soon as…)","grammar:1232:ex2:words:3:pos":"particle","grammar:1232:ex2:words:4:zh":"snow","grammar:1232:ex2:words:4:note":"ゆき","grammar:1232:ex2:words:4:pos":"noun","grammar:1232:ex2:words:5:zh":"(nominative)","grammar:1232:ex2:words:5:pos":"particle","grammar:1232:ex2:words:6:zh":"become more","grammar:1232:ex2:words:6:note":"おおくなります","grammar:1232:ex2:words:6:pos":"verb","grammar:1232:ex2:points:0":"❗北へ行く: head north (へ marks direction); 〜と = as soon as…, then…","grammar:1232:ex2:points:1":"雪が多くなる: the snow increases.","grammar:1232:ex3:trans":"The north wind is cold.","grammar:1232:ex3:structure":"〜が冷たいです","grammar:1232:ex3:words:0:zh":"north wind","grammar:1232:ex3:words:0:note":"きたかぜ","grammar:1232:ex3:words:0:pos":"noun","grammar:1232:ex3:words:1:zh":"(nominative)","grammar:1232:ex3:words:1:pos":"particle","grammar:1232:ex3:words:2:zh":"cold","grammar:1232:ex3:words:2:note":"つめたい","grammar:1232:ex3:words:2:pos":"adjective","grammar:1232:ex3:words:3:zh":"(polite form)","grammar:1232:ex3:words:3:pos":"copula","grammar:1232:ex3:points:0":"❗北風: north wind (北 + 風); 冷たい = cold.","grammar:1232:ex3:points:1":"北風が冷たい: the north wind is cold.","grammar:1232:ex4:trans":"North America is a vast region.","grammar:1232:ex4:structure":"〜は広大な〜です","grammar:1232:ex4:words:0:zh":"North America","grammar:1232:ex4:words:0:note":"ほくべい","grammar:1232:ex4:words:0:pos":"noun","grammar:1232:ex4:words:1:zh":"(topic)","grammar:1232:ex4:words:1:pos":"particle","grammar:1232:ex4:words:2:zh":"vast","grammar:1232:ex4:words:2:note":"こうだい","grammar:1232:ex4:words:2:pos":"na-adjective","grammar:1232:ex4:words:3:zh":"(attributive form)","grammar:1232:ex4:words:3:pos":"auxiliary verb","grammar:1232:ex4:words:4:zh":"area","grammar:1232:ex4:words:4:note":"ちいき","grammar:1232:ex4:words:4:pos":"noun","grammar:1232:ex4:words:5:zh":"is","grammar:1232:ex4:words:5:pos":"copula","grammar:1232:ex4:points:0":"❗北米: North America (北 + 米 = America); 広大な = vast.","grammar:1232:ex4:points:1":"広大な地域: a vast region.","grammar:1232:ex5:trans":"There is ice at the North Pole.","grammar:1232:ex5:structure":"〜には〜があります (〜 has 〜)","grammar:1232:ex5:words:0:zh":"the North Pole","grammar:1232:ex5:words:0:note":"ほっきょく","grammar:1232:ex5:words:0:pos":"noun","grammar:1232:ex5:words:1:zh":"(location of existence)","grammar:1232:ex5:words:1:pos":"particle","grammar:1232:ex5:words:2:zh":"(contrast)","grammar:1232:ex5:words:2:pos":"particle","grammar:1232:ex5:words:3:zh":"ice","grammar:1232:ex5:words:3:note":"こおり","grammar:1232:ex5:words:3:pos":"noun","grammar:1232:ex5:words:4:zh":"(nominative)","grammar:1232:ex5:words:4:pos":"particle","grammar:1232:ex5:words:5:zh":"there is / are","grammar:1232:ex5:words:5:pos":"verb","grammar:1232:ex5:points:0":"❗北極: the North Pole (北 + 極); 氷 = ice.","grammar:1232:ex5:points:1":"北極には氷: there is ice at the North Pole.","exam:1232:zh":"If the top of the map is north, then the opposite of south is north.","exam:1232:why":"The opposite of south is 「北」. East and west are opposites of each other, and neither is the opposite of south."},"1233":{"example:1233:exzh":"He is enduring a difficult situation.","example:1233:exzh2":"You need the strength to endure anything.","example:1233:exzh3":"It's important to keep enduring.","example:1233:exzh4":"I can't stand this cold.","example:1233:exzh5":"You're expected to put up with all kinds of problems."},"1234":{"example:1234:exzh":"Let's think about social issues.","example:1234:exzh2":"He is interested in contributing to society.","example:1234:exzh3":"Society is always changing.","example:1234:exzh4":"Our society is full of diversity.","example:1234:exzh5":"To build a good society, everyone's cooperation is needed."},"1235":{"example:1235:exzh":"Please explain that issue in detail.","example:1235:exzh2":"He is very knowledgeable about history.","example:1235:exzh3":"I'll provide detailed information.","example:1235:exzh4":"This book goes into detail about all sorts of things.","example:1235:exzh5":"A detailed analysis is needed."},"1236":{"example:1236:exzh":"He lives in London.","example:1236:exzh2":"London has many tourist attractions.","example:1236:exzh3":"London's weather is changeable.","example:1236:exzh4":"Transportation in London is convenient.","example:1236:exzh5":"London has a rich culture.","grammar:1236:ex:trans":"He lives in London.","grammar:1236:ex:structure":"〜に住んでいます","grammar:1236:ex:explain":"The core is 「〜に住む」, meaning \"live in a place,\" with the place of residence marked by 「に」. 「住んでいます」 uses 「〜ている」 to express a continuing state — \"has been living there\" — and this is the standard way to talk about where someone lives; plain 「住みます」 is not used. 「は」 marks the topic 「彼」, and 「ロンドン」 is a loanword place name. Remember that when saying where someone lives, you almost always use the ている form 「〜に住んでいる」, which emphasizes the long-term state of living there.","grammar:1236:ex:words:0:zh":"he","grammar:1236:ex:words:0:note":"かれ","grammar:1236:ex:words:0:pos":"pronoun","grammar:1236:ex:words:1:zh":"(topic)","grammar:1236:ex:words:1:pos":"particle","grammar:1236:ex:words:2:zh":"London","grammar:1236:ex:words:2:note":"loanword","grammar:1236:ex:words:2:pos":"noun","grammar:1236:ex:words:3:zh":"(place of residence)","grammar:1236:ex:words:3:pos":"particle","grammar:1236:ex:words:4:zh":"are living","grammar:1236:ex:words:4:note":"すんでいます","grammar:1236:ex:words:4:pos":"verb","grammar:1236:ex:points:0":"❗ロンドン: London.","grammar:1236:ex:points:1":"ロンドンに住む: live in London.","grammar:1236:ex2:trans":"London has many tourist attractions.","grammar:1236:ex2:structure":"〜には〜があります (〜 has 〜)","grammar:1236:ex2:words:0:zh":"London","grammar:1236:ex2:words:0:note":"loanword","grammar:1236:ex2:words:0:pos":"noun","grammar:1236:ex2:words:1:zh":"(location of existence)","grammar:1236:ex2:words:1:pos":"particle","grammar:1236:ex2:words:2:zh":"(contrast)","grammar:1236:ex2:words:2:pos":"particle","grammar:1236:ex2:words:3:zh":"a lot","grammar:1236:ex2:words:3:note":"おおく","grammar:1236:ex2:words:3:pos":"noun","grammar:1236:ex2:words:4:zh":"'s","grammar:1236:ex2:words:4:pos":"particle","grammar:1236:ex2:words:5:zh":"tourist attractions","grammar:1236:ex2:words:5:note":"かんこうめいしょ","grammar:1236:ex2:words:5:pos":"noun","grammar:1236:ex2:words:6:zh":"(nominative)","grammar:1236:ex2:words:6:pos":"particle","grammar:1236:ex2:words:7:zh":"there is / are","grammar:1236:ex2:words:7:pos":"verb","grammar:1236:ex2:points:0":"❗観光名所: tourist attraction (観光 + 名所).","grammar:1236:ex2:points:1":"観光名所: a sightseeing spot.","grammar:1236:ex3:trans":"London's weather is changeable.","grammar:1236:ex3:structure":"〜は変わりやすいです","grammar:1236:ex3:words:0:zh":"London","grammar:1236:ex3:words:0:note":"loanword","grammar:1236:ex3:words:0:pos":"noun","grammar:1236:ex3:words:1:zh":"'s","grammar:1236:ex3:words:1:pos":"particle","grammar:1236:ex3:words:2:zh":"weather","grammar:1236:ex3:words:2:note":"てんき","grammar:1236:ex3:words:2:pos":"noun","grammar:1236:ex3:words:3:zh":"(topic)","grammar:1236:ex3:words:3:pos":"particle","grammar:1236:ex3:words:4:zh":"changeable","grammar:1236:ex3:words:4:note":"かわりやすい","grammar:1236:ex3:words:4:pos":"adjective","grammar:1236:ex3:words:5:zh":"(polite form)","grammar:1236:ex3:words:5:pos":"copula","grammar:1236:ex3:points:0":"❗〜やすい: easy to… (変わる → 変わりやすい); 天気 = weather.","grammar:1236:ex3:points:1":"変わりやすい: changeable.","grammar:1236:ex4:trans":"Transportation in London is convenient.","grammar:1236:ex4:structure":"〜は便利です","grammar:1236:ex4:words:0:zh":"London","grammar:1236:ex4:words:0:note":"loanword","grammar:1236:ex4:words:0:pos":"noun","grammar:1236:ex4:words:1:zh":"'s","grammar:1236:ex4:words:1:pos":"particle","grammar:1236:ex4:words:2:zh":"transportation","grammar:1236:ex4:words:2:note":"こうつう","grammar:1236:ex4:words:2:pos":"noun","grammar:1236:ex4:words:3:zh":"(topic)","grammar:1236:ex4:words:3:pos":"particle","grammar:1236:ex4:words:4:zh":"convenient","grammar:1236:ex4:words:4:note":"べんり","grammar:1236:ex4:words:4:pos":"na-adjective","grammar:1236:ex4:words:5:zh":"(polite form)","grammar:1236:ex4:words:5:pos":"copula","grammar:1236:ex4:points:0":"❗交通: transportation; 便利 = convenient.","grammar:1236:ex4:points:1":"交通が便利: the transportation is convenient.","grammar:1236:ex5:trans":"London's culture is rich.","grammar:1236:ex5:structure":"〜は〜が豊かです","grammar:1236:ex5:words:0:zh":"London","grammar:1236:ex5:words:0:note":"loanword","grammar:1236:ex5:words:0:pos":"noun","grammar:1236:ex5:words:1:zh":"(topic)","grammar:1236:ex5:words:1:pos":"particle","grammar:1236:ex5:words:2:zh":"culture","grammar:1236:ex5:words:2:note":"ぶんか","grammar:1236:ex5:words:2:pos":"noun","grammar:1236:ex5:words:3:zh":"(nominative)","grammar:1236:ex5:words:3:pos":"particle","grammar:1236:ex5:words:4:zh":"abundant","grammar:1236:ex5:words:4:note":"ゆたか","grammar:1236:ex5:words:4:pos":"na-adjective","grammar:1236:ex5:words:5:zh":"(polite form)","grammar:1236:ex5:words:5:pos":"copula","grammar:1236:ex5:points:0":"❗文化が豊か: rich in culture; 豊か = rich.","grammar:1236:ex5:points:1":"豊か: abundant."},"1238":{"example:1238:exzh":"He got injured in a soccer game.","example:1238:exzh2":"If you get injured, go to a doctor right away.","example:1238:exzh3":"She injured her arm.","example:1238:exzh4":"Please be careful to prevent injuries.","example:1238:exzh5":"There was a child who got injured at school.","grammar:1238:ex:trans":"He got injured in a soccer game.","grammar:1238:ex:structure":"〜で怪我をしました","grammar:1238:ex:explain":"The core is the set expression 「怪我をする」, meaning \"get injured\": 「怪我」 is a noun, and it takes 「を」 as its object together with 「する」. Pay special attention to the particle 「で」: in 「試合で」, 「で」 marks the occasion or place where the action happens — getting injured \"in the game.\" 「サッカーの試合」 is joined with 「の」. The sentence describes getting injured on a particular occasion, and 「で」 marking the occasion is the key nuance here.","grammar:1238:ex:words:0:zh":"he","grammar:1238:ex:words:0:note":"かれ","grammar:1238:ex:words:0:pos":"pronoun","grammar:1238:ex:words:1:zh":"(topic)","grammar:1238:ex:words:1:pos":"particle","grammar:1238:ex:words:2:zh":"soccer","grammar:1238:ex:words:2:note":"loanword","grammar:1238:ex:words:2:pos":"noun","grammar:1238:ex:words:3:zh":"'s","grammar:1238:ex:words:3:pos":"particle","grammar:1238:ex:words:4:zh":"competition","grammar:1238:ex:words:4:note":"しあい","grammar:1238:ex:words:4:pos":"noun","grammar:1238:ex:words:5:zh":"(the occasion)","grammar:1238:ex:words:5:pos":"particle","grammar:1238:ex:words:6:zh":"got injured","grammar:1238:ex:words:6:note":"けがをしました","grammar:1238:ex:words:6:pos":"verb","grammar:1238:ex:points:0":"❗怪我をする: get injured (set expression); ❓試合で = in the game (で = occasion).","grammar:1238:ex:points:1":"サッカーの試合: a soccer game.","grammar:1238:ex2:trans":"If you get injured, see a doctor right away.","grammar:1238:ex2:structure":"〜した場合は〜ましょう","grammar:1238:ex2:words:0:zh":"got injured","grammar:1238:ex2:words:0:note":"けがをした","grammar:1238:ex2:words:0:pos":"verb","grammar:1238:ex2:words:1:zh":"case","grammar:1238:ex2:words:1:note":"ばあい","grammar:1238:ex2:words:1:pos":"noun","grammar:1238:ex2:words:2:zh":"(topic)","grammar:1238:ex2:words:2:pos":"particle","grammar:1238:ex2:words:3:zh":"immediately","grammar:1238:ex2:words:3:pos":"adverb","grammar:1238:ex2:words:4:zh":"doctor","grammar:1238:ex2:words:4:note":"いしゃ","grammar:1238:ex2:words:4:pos":"noun","grammar:1238:ex2:words:5:zh":"(destination)","grammar:1238:ex2:words:5:pos":"particle","grammar:1238:ex2:words:6:zh":"let's go","grammar:1238:ex2:words:6:note":"いきましょう","grammar:1238:ex2:words:6:pos":"verb","grammar:1238:ex2:points:0":"❗〜た場合は: in the case that…; 医者に行く = see a doctor.","grammar:1238:ex2:points:1":"怪我をした場合: if you get injured.","grammar:1238:ex3:trans":"She injured her arm.","grammar:1238:ex3:structure":"〜に怪我をしました","grammar:1238:ex3:words:0:zh":"she","grammar:1238:ex3:words:0:note":"かのじょ","grammar:1238:ex3:words:0:pos":"pronoun","grammar:1238:ex3:words:1:zh":"(topic)","grammar:1238:ex3:words:1:pos":"particle","grammar:1238:ex3:words:2:zh":"arm","grammar:1238:ex3:words:2:note":"うで","grammar:1238:ex3:words:2:pos":"noun","grammar:1238:ex3:words:3:zh":"(body part)","grammar:1238:ex3:words:3:pos":"particle","grammar:1238:ex3:words:4:zh":"got injured","grammar:1238:ex3:words:4:note":"けがをしました","grammar:1238:ex3:words:4:pos":"verb","grammar:1238:ex3:points:0":"❗腕に怪我をする: injure one's arm (the body part takes に); 腕 = arm.","grammar:1238:ex3:points:1":"腕: arm.","grammar:1238:ex4:trans":"Please be careful so you don't get injured.","grammar:1238:ex4:structure":"〜を防ぐために気をつけてください","grammar:1238:ex4:words:0:zh":"scar","grammar:1238:ex4:words:0:note":"けが","grammar:1238:ex4:words:0:pos":"noun","grammar:1238:ex4:words:1:zh":"(object marker)","grammar:1238:ex4:words:1:pos":"particle","grammar:1238:ex4:words:2:zh":"prevent","grammar:1238:ex4:words:2:note":"ふせぐ","grammar:1238:ex4:words:2:pos":"verb","grammar:1238:ex4:words:3:zh":"for the sake of","grammar:1238:ex4:words:3:pos":"particle","grammar:1238:ex4:words:4:zh":"be careful of","grammar:1238:ex4:words:4:note":"きをつけて","grammar:1238:ex4:words:4:pos":"set phrase","grammar:1238:ex4:words:5:zh":"please","grammar:1238:ex4:words:5:pos":"auxiliary verb","grammar:1238:ex4:points:0":"❗怪我を防ぐ: prevent injury; 気をつける = be careful (set expression).","grammar:1238:ex4:points:1":"〜ために: in order to….","grammar:1238:ex5:trans":"A child got injured at school.","grammar:1238:ex5:structure":"〜で〜した子供がいました","grammar:1238:ex5:words:0:zh":"school","grammar:1238:ex5:words:0:note":"がっこう","grammar:1238:ex5:words:0:pos":"noun","grammar:1238:ex5:words:1:zh":"(place)","grammar:1238:ex5:words:1:pos":"particle","grammar:1238:ex5:words:2:zh":"injured","grammar:1238:ex5:words:2:note":"けがをした","grammar:1238:ex5:words:2:pos":"verb","grammar:1238:ex5:words:3:zh":"child","grammar:1238:ex5:words:3:note":"こども","grammar:1238:ex5:words:3:pos":"noun","grammar:1238:ex5:words:4:zh":"(nominative)","grammar:1238:ex5:words:4:pos":"particle","grammar:1238:ex5:words:5:zh":"there is / are","grammar:1238:ex5:words:5:pos":"verb","grammar:1238:ex5:points:0":"❗怪我をした子供: a child who got injured (modifies a noun).","grammar:1238:ex5:points:1":"❓学校で: at school (で = place)."},"1240":{"example:1240:exzh":"This plant is poisonous.","example:1240:exzh2":"Some creatures are poisonous too.","example:1240:exzh3":"Poison is bad for your body.","example:1240:exzh4":"It's important to avoid poison.","example:1240:exzh5":"He ingested poison."},"1241":{"example:1241:exzh":"Please submit it within one week.","example:1241:exzh2":"This package will arrive within three days.","example:1241:exzh3":"He is scheduled to arrive within an hour.","example:1241:exzh4":"Let's keep our shopping within 50,000 yen.","example:1241:exzh5":"This task will be completed within one month."},"1242":{"example:1242:exzh":"How were the results of the experiment?","example:1242:exzh2":"We did an experiment in science class.","example:1242:exzh3":"This experiment was very interesting.","example:1242:exzh4":"We're trying a new experimental method.","example:1242:exzh5":"I like working in the lab."},"1243":{"example:1243:exzh":"What on earth happened?","example:1243:exzh2":"Where on earth did he go?","example:1243:exzh3":"Who on earth is going to do that?","example:1243:exzh4":"What on earth is this?","example:1243:exzh5":"What on earth are you thinking?"},"1244":{"example:1244:exzh":"The monster in the movie was scary.","example:1244:exzh2":"He drew a monster in his work.","example:1244:exzh3":"I like stories that feature monsters.","example:1244:exzh4":"The children drew pictures of monsters.","example:1244:exzh5":"That monster is very big."},"1245":{"example:1245:exzh":"I need to apologize to him.","example:1245:exzh2":"Some things can't be forgiven even if you apologize.","example:1245:exzh3":"Please apologize immediately.","example:1245:exzh4":"Apologizing is important.","example:1245:exzh5":"She apologized right away."},"1246":{"example:1246:exzh":"I live in Tokyo.","example:1246:exzh2":"I want to live a relaxed life in the countryside.","example:1246:exzh3":"He lives as a university student.","example:1246:exzh4":"I've lived here for a long time.","example:1246:exzh5":"It's important to live happily."},"1248":{"example:1248:exzh":"The last meeting was very worthwhile.","example:1248:exzh2":"It was raining last time.","example:1248:exzh3":"The last trip was fun.","example:1248:exzh4":"The last test was hard.","example:1248:exzh5":"I took part in the last event."},"1249":{"example:1249:exzh":"Construction of the base is underway.","example:1249:exzh2":"Many people live on this base.","example:1249:exzh3":"Military bases play an important role.","example:1249:exzh4":"This is a base for protecting the safety of the region.","example:1249:exzh5":"There is a fence around the base."},"1250":{"example:1250:exzh":"He's my boyfriend.","example:1250:exzh2":"She bought a gift for her partner.","example:1250:exzh3":"I watched a movie with my partner.","example:1250:exzh4":"Dates with your partner are fun.","example:1250:exzh5":"They've been a couple for a long time.","grammar:1250:ex:trans":"He's my romantic partner.","grammar:1250:ex:structure":"〜は〜の恋人です","grammar:1250:ex:explain":"This is an identifying sentence of the form 「Aは〜の〜です」, with 「の」 showing belonging. 「私の恋人」 means my romantic partner, 「は」 marks the topic 「彼」, and 「です」 is the polite copula. 「恋人」 is made of 「恋」 (romance) plus 「人」 and refers to a boyfriend or girlfriend — a partner in a romantic relationship, not just a friend. The whole sentence is a common way to introduce the person you're dating, and it has the same structure as the earlier relationship sentences, so you can swap in other nouns.","grammar:1250:ex:words:0:zh":"he","grammar:1250:ex:words:0:note":"かれ","grammar:1250:ex:words:0:pos":"pronoun","grammar:1250:ex:words:1:zh":"(topic)","grammar:1250:ex:words:1:pos":"particle","grammar:1250:ex:words:2:zh":"I","grammar:1250:ex:words:2:note":"わたし","grammar:1250:ex:words:2:pos":"pronoun","grammar:1250:ex:words:3:zh":"'s","grammar:1250:ex:words:3:pos":"particle","grammar:1250:ex:words:4:zh":"romantic partner","grammar:1250:ex:words:4:note":"こいびと","grammar:1250:ex:words:4:pos":"noun","grammar:1250:ex:words:5:zh":"is","grammar:1250:ex:words:5:pos":"copula","grammar:1250:ex:points:0":"❗恋人（こいびと）: romantic partner, lover (恋＋人).","grammar:1250:ex:points:1":"私の恋人: my romantic partner.","grammar:1250:ex2:trans":"She bought a present for her romantic partner.","grammar:1250:ex2:structure":"〜に〜を買いました","grammar:1250:ex2:words:0:zh":"she","grammar:1250:ex2:words:0:note":"かのじょ","grammar:1250:ex2:words:0:pos":"pronoun","grammar:1250:ex2:words:1:zh":"(topic)","grammar:1250:ex2:words:1:pos":"particle","grammar:1250:ex2:words:2:zh":"romantic partner","grammar:1250:ex2:words:2:note":"こいびと","grammar:1250:ex2:words:2:pos":"noun","grammar:1250:ex2:words:3:zh":"(beneficiary)","grammar:1250:ex2:words:3:pos":"particle","grammar:1250:ex2:words:4:zh":"present","grammar:1250:ex2:words:4:note":"loanword","grammar:1250:ex2:words:4:pos":"noun","grammar:1250:ex2:words:5:zh":"(object marker)","grammar:1250:ex2:words:5:pos":"particle","grammar:1250:ex2:words:6:zh":"bought","grammar:1250:ex2:words:6:note":"かいました","grammar:1250:ex2:words:6:pos":"verb","grammar:1250:ex2:points:0":"❗〜にプレゼントを買う: to buy a present for … (the recipient takes に).","grammar:1250:ex2:points:1":"恋人に: for one's partner.","grammar:1250:ex3:trans":"I watched a movie together with my partner.","grammar:1250:ex3:structure":"〜と一緒に〜を見ました","grammar:1250:ex3:words:0:zh":"romantic partner","grammar:1250:ex3:words:0:note":"こいびと","grammar:1250:ex3:words:0:pos":"noun","grammar:1250:ex3:words:1:zh":"with","grammar:1250:ex3:words:1:pos":"particle","grammar:1250:ex3:words:2:zh":"together","grammar:1250:ex3:words:2:note":"いっしょに","grammar:1250:ex3:words:2:pos":"adverb","grammar:1250:ex3:words:3:zh":"movie","grammar:1250:ex3:words:3:note":"えいが","grammar:1250:ex3:words:3:pos":"noun","grammar:1250:ex3:words:4:zh":"(object marker)","grammar:1250:ex3:words:4:pos":"particle","grammar:1250:ex3:words:5:zh":"watched","grammar:1250:ex3:words:5:note":"みました","grammar:1250:ex3:words:5:pos":"verb","grammar:1250:ex3:points:0":"恋人と一緒に: together with one's partner.","grammar:1250:ex3:points:1":"映画を見る: to watch a movie.","grammar:1250:ex4:trans":"Dates with my partner are fun.","grammar:1250:ex4:structure":"〜とのデートは楽しいです","grammar:1250:ex4:words:0:zh":"romantic partner","grammar:1250:ex4:words:0:note":"こいびと","grammar:1250:ex4:words:0:pos":"noun","grammar:1250:ex4:words:1:zh":"with","grammar:1250:ex4:words:1:pos":"particle","grammar:1250:ex4:words:2:zh":"'s","grammar:1250:ex4:words:2:pos":"particle","grammar:1250:ex4:words:3:zh":"date","grammar:1250:ex4:words:3:note":"loanword","grammar:1250:ex4:words:3:pos":"noun","grammar:1250:ex4:words:4:zh":"(topic)","grammar:1250:ex4:words:4:pos":"particle","grammar:1250:ex4:words:5:zh":"interesting","grammar:1250:ex4:words:5:note":"たのしい","grammar:1250:ex4:words:5:pos":"adjective","grammar:1250:ex4:words:6:zh":"(polite form)","grammar:1250:ex4:words:6:pos":"copula","grammar:1250:ex4:points:0":"❗〜とのデート: a date with…","grammar:1250:ex4:points:1":"恋人とのデート: a date with one's partner.","grammar:1250:ex5:trans":"They've been a couple for a long time.","grammar:1250:ex5:structure":"〜は長い間〜です","grammar:1250:ex5:words:0:zh":"they","grammar:1250:ex5:words:0:note":"かれら","grammar:1250:ex5:words:0:pos":"pronoun","grammar:1250:ex5:words:1:zh":"(topic)","grammar:1250:ex5:words:1:pos":"particle","grammar:1250:ex5:words:2:zh":"a long time","grammar:1250:ex5:words:2:note":"ながいあいだ","grammar:1250:ex5:words:2:pos":"noun","grammar:1250:ex5:words:3:zh":"romantic partner","grammar:1250:ex5:words:3:note":"こいびと","grammar:1250:ex5:words:3:pos":"noun","grammar:1250:ex5:words:4:zh":"is","grammar:1250:ex5:words:4:pos":"copula","grammar:1250:ex5:points:0":"❗長い間: a long time; 彼ら＝they.","grammar:1250:ex5:points:1":"長い間恋人: partners for a long time."},"1251":{"example:1251:exzh":"The room is dirty, isn't it.","example:1251:exzh2":"This river is dirty.","example:1251:exzh3":"Please don't touch it with dirty hands.","example:1251:exzh4":"I'll wash the dirty clothes.","example:1251:exzh5":"That food is dirty.","grammar:1251:ex:trans":"The room is so dirty.","grammar:1251:ex:structure":"〜が汚いですね","grammar:1251:ex:explain":"This is an adjective sentence of the form 「Aが〜ですね」, and 「汚い」 is an i-adjective meaning dirty. Note that it uses 「が」 rather than 「は」: the speaker sees the messy room right now and comments directly on what's in front of them, presenting 「部屋」 as new information. The 「ね」 at the end is a particle that seeks agreement or expresses dismay, with a tone like right? or honestly. The sentence sounds like a reaction that slips out when you walk in and see the mess.","grammar:1251:ex:words:0:zh":"room","grammar:1251:ex:words:0:note":"へや","grammar:1251:ex:words:0:pos":"noun","grammar:1251:ex:words:1:zh":"(nominative)","grammar:1251:ex:words:1:pos":"particle","grammar:1251:ex:words:2:zh":"dirty","grammar:1251:ex:words:2:note":"きたない","grammar:1251:ex:words:2:pos":"adjective","grammar:1251:ex:words:3:zh":"(polite form)","grammar:1251:ex:words:3:pos":"copula","grammar:1251:ex:words:4:zh":"Ah","grammar:1251:ex:words:4:pos":"particle","grammar:1251:ex:points:0":"❗汚い（きたない）: dirty (i-adjective).","grammar:1251:ex:points:1":"部屋が汚い: the room is dirty.","grammar:1251:ex2:trans":"This river is dirty.","grammar:1251:ex2:structure":"〜は汚いです","grammar:1251:ex2:words:0:zh":"this","grammar:1251:ex2:words:0:pos":"pre-noun adjectival","grammar:1251:ex2:words:1:zh":"river","grammar:1251:ex2:words:1:note":"かわ","grammar:1251:ex2:words:1:pos":"noun","grammar:1251:ex2:words:2:zh":"(topic)","grammar:1251:ex2:words:2:pos":"particle","grammar:1251:ex2:words:3:zh":"dirty","grammar:1251:ex2:words:3:note":"きたない","grammar:1251:ex2:words:3:pos":"adjective","grammar:1251:ex2:words:4:zh":"(polite form)","grammar:1251:ex2:words:4:pos":"copula","grammar:1251:ex2:points:0":"この川: this river.","grammar:1251:ex2:points:1":"汚い: dirty.","grammar:1251:ex3:trans":"Please don't touch it with dirty hands.","grammar:1251:ex3:structure":"汚い手で触らないでください","grammar:1251:ex3:words:0:zh":"dirty","grammar:1251:ex3:words:0:note":"きたない","grammar:1251:ex3:words:0:pos":"adjective","grammar:1251:ex3:words:1:zh":"hand","grammar:1251:ex3:words:1:note":"て","grammar:1251:ex3:words:1:pos":"noun","grammar:1251:ex3:words:2:zh":"(means)","grammar:1251:ex3:words:2:pos":"particle","grammar:1251:ex3:words:3:zh":"don't touch","grammar:1251:ex3:words:3:note":"さわらないで","grammar:1251:ex3:words:3:pos":"verb","grammar:1251:ex3:words:4:zh":"please","grammar:1251:ex3:words:4:pos":"auxiliary verb","grammar:1251:ex3:points:0":"❗汚い手で: with dirty hands (で marks the means); 〜ないで＝don't …","grammar:1251:ex3:points:1":"触る: to touch.","grammar:1251:ex4:trans":"I'll wash the dirty clothes.","grammar:1251:ex4:structure":"汚い〜を洗います","grammar:1251:ex4:explain":"「汚い服」 means dirty clothes, and 「を」 marks what gets washed. 「洗います」 is the polite non-past form of 「洗う」; depending on context it can mean that you usually wash them or that you're going to wash them next. The subject I is left out, and no potential form expressing ability is used here.","grammar:1251:ex4:words:0:zh":"dirty","grammar:1251:ex4:words:0:note":"きたない","grammar:1251:ex4:words:0:pos":"i-adjective","grammar:1251:ex4:words:1:zh":"clothes","grammar:1251:ex4:words:1:note":"ふく","grammar:1251:ex4:words:1:pos":"noun","grammar:1251:ex4:words:2:zh":"(object)","grammar:1251:ex4:words:2:pos":"particle","grammar:1251:ex4:words:3:zh":"wash","grammar:1251:ex4:words:3:note":"あらい","grammar:1251:ex4:words:3:pos":"verb","grammar:1251:ex4:words:4:zh":"(polite tone)","grammar:1251:ex4:words:4:pos":"auxiliary verb","grammar:1251:ex4:points:0":"「汚い」 is an i-adjective, so it modifies a noun directly, with no 「な」 added.","grammar:1251:ex4:points:1":"「洗う」 is a transitive verb, so the thing being washed is marked with 「を」.","grammar:1251:ex4:points:2":"The masu-form of 「洗う」 is 「洗います」: the ending 「う」 changes to 「い」 and 「ます」 is added.","grammar:1251:ex5:trans":"That food is dirty.","grammar:1251:ex5:structure":"〜は汚いです","grammar:1251:ex5:words:0:zh":"that","grammar:1251:ex5:words:0:pos":"pre-noun adjectival","grammar:1251:ex5:words:1:zh":"food","grammar:1251:ex5:words:1:note":"たべもの","grammar:1251:ex5:words:1:pos":"noun","grammar:1251:ex5:words:2:zh":"(topic)","grammar:1251:ex5:words:2:pos":"particle","grammar:1251:ex5:words:3:zh":"dirty","grammar:1251:ex5:words:3:note":"きたない","grammar:1251:ex5:words:3:pos":"adjective","grammar:1251:ex5:words:4:zh":"(polite form)","grammar:1251:ex5:words:4:pos":"copula","grammar:1251:ex5:points:0":"その食べ物: that food.","grammar:1251:ex5:points:1":"汚い: dirty, unclean."},"1252":{"example:1252:exzh":"I'm practicing conversation.","example:1252:exzh2":"Conversations with him are fun.","example:1252:exzh3":"This class emphasizes conversation.","example:1252:exzh4":"My Japanese conversation has improved.","example:1252:exzh5":"The conversation is really lively.","grammar:1252:ex:trans":"I'm practicing conversation.","grammar:1252:ex:structure":"〜を練習しています","grammar:1252:ex:explain":"This is the transitive pattern 「〜を練習する」, with the object marked by 「を」. 「練習しています」 uses 「〜ている」 for an action in progress, i.e. is practicing. 「会話」 means conversation or dialogue practice. The suru-verb 「練習する」 is built from the noun 「練習」 plus 「する」, so it's easy to conjugate. The whole sentence is a common way to describe a study activity. Remember that many suru-verbs of the form noun＋する can be used the same way as 〜を＋noun＋する.","grammar:1252:ex:words:0:zh":"conversation","grammar:1252:ex:words:0:note":"かいわ","grammar:1252:ex:words:0:pos":"noun","grammar:1252:ex:words:1:zh":"(object marker)","grammar:1252:ex:words:1:pos":"particle","grammar:1252:ex:words:2:zh":"practicing","grammar:1252:ex:words:2:note":"れんしゅうしています","grammar:1252:ex:words:2:pos":"verb","grammar:1252:ex:points:0":"❗会話（かいわ）: conversation, dialogue; 練習する＝to practice.","grammar:1252:ex:points:1":"会話を練習: practice conversation.","grammar:1252:ex2:trans":"Talking with him is fun.","grammar:1252:ex2:structure":"〜との会話は楽しいです","grammar:1252:ex2:words:0:zh":"he","grammar:1252:ex2:words:0:note":"かれ","grammar:1252:ex2:words:0:pos":"pronoun","grammar:1252:ex2:words:1:zh":"with","grammar:1252:ex2:words:1:pos":"particle","grammar:1252:ex2:words:2:zh":"'s","grammar:1252:ex2:words:2:pos":"particle","grammar:1252:ex2:words:3:zh":"conversation","grammar:1252:ex2:words:3:note":"かいわ","grammar:1252:ex2:words:3:pos":"noun","grammar:1252:ex2:words:4:zh":"(topic)","grammar:1252:ex2:words:4:pos":"particle","grammar:1252:ex2:words:5:zh":"interesting","grammar:1252:ex2:words:5:note":"たのしい","grammar:1252:ex2:words:5:pos":"adjective","grammar:1252:ex2:words:6:zh":"(polite form)","grammar:1252:ex2:words:6:pos":"copula","grammar:1252:ex2:points:0":"❗〜との会話: conversation with …","grammar:1252:ex2:points:1":"彼との会話: talking with him.","grammar:1252:ex3:trans":"This class puts emphasis on conversation.","grammar:1252:ex3:structure":"〜では〜を重視します","grammar:1252:ex3:words:0:zh":"this","grammar:1252:ex3:words:0:pos":"pre-noun adjectival","grammar:1252:ex3:words:1:zh":"class","grammar:1252:ex3:words:1:note":"loanword","grammar:1252:ex3:words:1:pos":"noun","grammar:1252:ex3:words:2:zh":"(the occasion)","grammar:1252:ex3:words:2:pos":"particle","grammar:1252:ex3:words:3:zh":"(contrast)","grammar:1252:ex3:words:3:pos":"particle","grammar:1252:ex3:words:4:zh":"conversation","grammar:1252:ex3:words:4:note":"かいわ","grammar:1252:ex3:words:4:pos":"noun","grammar:1252:ex3:words:5:zh":"(object marker)","grammar:1252:ex3:words:5:pos":"particle","grammar:1252:ex3:words:6:zh":"to value","grammar:1252:ex3:words:6:note":"じゅうしします","grammar:1252:ex3:words:6:pos":"verb","grammar:1252:ex3:points:0":"❗〜を重視する: to place importance on …; クラス＝class, course.","grammar:1252:ex3:points:1":"会話を重視: value speaking.","grammar:1252:ex4:trans":"My Japanese conversation skills have improved.","grammar:1252:ex4:structure":"〜が上達しました","grammar:1252:ex4:words:0:zh":"Japanese","grammar:1252:ex4:words:0:note":"にほんご","grammar:1252:ex4:words:0:pos":"noun","grammar:1252:ex4:words:1:zh":"'s","grammar:1252:ex4:words:1:pos":"particle","grammar:1252:ex4:words:2:zh":"conversation","grammar:1252:ex4:words:2:note":"かいわ","grammar:1252:ex4:words:2:pos":"noun","grammar:1252:ex4:words:3:zh":"(nominative)","grammar:1252:ex4:words:3:pos":"particle","grammar:1252:ex4:words:4:zh":"improved","grammar:1252:ex4:words:4:note":"じょうたつしました","grammar:1252:ex4:words:4:pos":"verb","grammar:1252:ex4:points:0":"❗上達する: to improve, to advance; 日本語の会話＝Japanese conversation.","grammar:1252:ex4:points:1":"会話が上達: conversation improves.","grammar:1252:ex5:trans":"The conversation is really lively.","grammar:1252:ex5:structure":"〜が弾んでいます","grammar:1252:ex5:words:0:zh":"conversation","grammar:1252:ex5:words:0:note":"かいわ","grammar:1252:ex5:words:0:pos":"noun","grammar:1252:ex5:words:1:zh":"(nominative)","grammar:1252:ex5:words:1:pos":"particle","grammar:1252:ex5:words:2:zh":"getting lively","grammar:1252:ex5:words:2:note":"はずんでいます","grammar:1252:ex5:words:2:pos":"verb","grammar:1252:ex5:points:0":"❗会話が弾む: the conversation gets lively and animated (set phrase); 弾む＝to bounce, to be in high spirits.","grammar:1252:ex5:points:1":"会話が弾む: to have a lively conversation."},"1253":{"example:1253:exzh":"He supported me.","example:1253:exzh2":"I need support.","example:1253:exzh3":"This project is receiving support.","example:1253:exzh4":"Applications for support are pouring in.","example:1253:exzh5":"I took part in support activities."},"1254":{"example:1254:exzh":"I love traveling.","example:1254:exzh2":"I'm looking forward to the next trip.","example:1254:exzh3":"I made a travel plan.","example:1254:exzh4":"I'm going on a trip with her.","example:1254:exzh5":"Traveling brings new discoveries.","grammar:1254:ex:trans":"I love traveling.","grammar:1254:ex:structure":"〜が大好きです","grammar:1254:ex:explain":"At the core is 「〜が大好きです」, meaning to love something deeply. Note that the thing you like is marked with 「が」, not 「を」 — this is the fixed pattern for Japanese adjectives of feeling and ability such as 「好き／嫌い／上手／下手」. 「大好き」 is a stronger version of 「好き」, i.e. really love. 「は」 marks the topic (here the feeling of 「私は」 is left out), and 「旅行」 is what's liked. The whole sentence is an all-purpose way to express a strong liking.","grammar:1254:ex:words:0:zh":"travel / trip","grammar:1254:ex:words:0:note":"りょこう","grammar:1254:ex:words:0:pos":"noun","grammar:1254:ex:words:1:zh":"(object)","grammar:1254:ex:words:1:pos":"particle","grammar:1254:ex:words:2:zh":"Love","grammar:1254:ex:words:2:note":"だいすき","grammar:1254:ex:words:2:pos":"na-adjective","grammar:1254:ex:words:3:zh":"(polite form)","grammar:1254:ex:words:3:pos":"copula","grammar:1254:ex:points:0":"❗旅行（りょこう）: travel, trip; 〜が大好き＝love … deeply.","grammar:1254:ex:points:1":"旅行が大好き: really loves traveling.","grammar:1254:ex2:trans":"I'm looking forward to the next trip.","grammar:1254:ex2:structure":"〜の旅行は楽しみです","grammar:1254:ex2:words:0:zh":"next time","grammar:1254:ex2:words:0:note":"こんど","grammar:1254:ex2:words:0:pos":"noun","grammar:1254:ex2:words:1:zh":"'s","grammar:1254:ex2:words:1:pos":"particle","grammar:1254:ex2:words:2:zh":"travel / trip","grammar:1254:ex2:words:2:note":"りょこう","grammar:1254:ex2:words:2:pos":"noun","grammar:1254:ex2:words:3:zh":"(topic)","grammar:1254:ex2:words:3:pos":"particle","grammar:1254:ex2:words:4:zh":"look forward to","grammar:1254:ex2:words:4:note":"たのしみ","grammar:1254:ex2:words:4:pos":"noun","grammar:1254:ex2:words:5:zh":"(polite form)","grammar:1254:ex2:words:5:pos":"copula","grammar:1254:ex2:points:0":"❗今度: next time, this time; 〜が楽しみ＝looking forward to …","grammar:1254:ex2:points:1":"今度の旅行: the upcoming trip.","grammar:1254:ex3:trans":"I made a travel plan.","grammar:1254:ex3:structure":"〜の計画を立てました","grammar:1254:ex3:words:0:zh":"travel / trip","grammar:1254:ex3:words:0:note":"りょこう","grammar:1254:ex3:words:0:pos":"noun","grammar:1254:ex3:words:1:zh":"'s","grammar:1254:ex3:words:1:pos":"particle","grammar:1254:ex3:words:2:zh":"plan","grammar:1254:ex3:words:2:note":"けいかく","grammar:1254:ex3:words:2:pos":"noun","grammar:1254:ex3:words:3:zh":"(object marker)","grammar:1254:ex3:words:3:pos":"particle","grammar:1254:ex3:words:4:zh":"made (a plan)","grammar:1254:ex3:words:4:note":"たてました","grammar:1254:ex3:words:4:pos":"verb","grammar:1254:ex3:points:0":"❗計画を立てる: to make a plan.","grammar:1254:ex3:points:1":"旅行の計画: travel plan.","grammar:1254:ex4:trans":"I'm going on a trip with her.","grammar:1254:ex4:structure":"〜と旅行に行きます","grammar:1254:ex4:words:0:zh":"she","grammar:1254:ex4:words:0:note":"かのじょ","grammar:1254:ex4:words:0:pos":"pronoun","grammar:1254:ex4:words:1:zh":"with","grammar:1254:ex4:words:1:pos":"particle","grammar:1254:ex4:words:2:zh":"travel / trip","grammar:1254:ex4:words:2:note":"りょこう","grammar:1254:ex4:words:2:pos":"noun","grammar:1254:ex4:words:3:zh":"(purpose)","grammar:1254:ex4:words:3:pos":"particle","grammar:1254:ex4:words:4:zh":"go","grammar:1254:ex4:words:4:pos":"verb","grammar:1254:ex4:points:0":"❗旅行に行く: to go on a trip; 〜と＝with …","grammar:1254:ex4:points:1":"彼女と: with her.","grammar:1254:ex5:trans":"Traveling brings new discoveries.","grammar:1254:ex5:structure":"〜すると〜があります","grammar:1254:ex5:words:0:zh":"travel / trip","grammar:1254:ex5:words:0:note":"りょこうする","grammar:1254:ex5:words:0:pos":"verb","grammar:1254:ex5:words:1:zh":"(as soon as…)","grammar:1254:ex5:words:1:pos":"particle","grammar:1254:ex5:words:2:zh":"new","grammar:1254:ex5:words:2:note":"あたらしい","grammar:1254:ex5:words:2:pos":"adjective","grammar:1254:ex5:words:3:zh":"found","grammar:1254:ex5:words:3:note":"はっけん","grammar:1254:ex5:words:3:pos":"noun","grammar:1254:ex5:words:4:zh":"(nominative)","grammar:1254:ex5:words:4:pos":"particle","grammar:1254:ex5:words:5:zh":"there is / are","grammar:1254:ex5:words:5:pos":"verb","grammar:1254:ex5:points:0":"❗旅行する: to travel (also used as a verb); 〜と＝whenever …, …","grammar:1254:ex5:points:1":"新しい発見: a new discovery.","exam:1254:zh":"During summer vacation, I plan to take a three-day trip with my family and tour temples in Kyoto.","exam:1254:why":"Leaving home for three days and sightseeing in Kyoto fits 「旅行」. 「散歩」 usually means a relaxing walk, and isn't used for a multi-day trip away from home."},"1256":{"example:1256:exzh":"He deceived me.","example:1256:exzh2":"I can't forgive someone for deceiving people.","example:1256:exzh3":"Deceiving a friend is wrong.","example:1256:exzh4":"She is careful not to be deceived.","example:1256:exzh5":"Don't lie to me—please tell me the truth."},"1257":{"example:1257:exzh":"I've already gone home.","example:1257:exzh2":"He has already left.","example:1257:exzh3":"It's already over.","example:1257:exzh4":"Reservations are already full.","example:1257:exzh5":"The event has already started."},"1258":{"example:1258:exzh":"Meeting him was a coincidence.","example:1258:exzh2":"Many encounters make life richer.","example:1258:exzh3":"She met a good person.","example:1258:exzh4":"Meeting at this place is fate.","example:1258:exzh5":"I met a friend in high school."},"1259":{"example:1259:exzh":"I saw a stop sign.","example:1259:exzh2":"The car stopped.","example:1259:exzh3":"It is necessary to stop.","example:1259:exzh4":"The bus stops at the next stop.","example:1259:exzh5":"Please stop at this point."},"1260":{"example:1260:exzh":"I need guidance.","example:1260:exzh2":"He is a good guide.","example:1260:exzh3":"I found the airport information desk.","example:1260:exzh4":"Please read this guide.","example:1260:exzh5":"I acted according to the guidance.","grammar:1260:ex:trans":"I need guidance.","grammar:1260:ex:structure":"〜が必要です","grammar:1260:ex:explain":"This is the pattern 「〜が必要です」, meaning something is needed. Note that the thing needed takes 「が」; 「必要」 is a na-adjective, and 「です」 is added directly at the end. 「案内」 means guidance, a guide, or a guidebook, and here it's a noun marked as the subject with 「が」. The whole sentence 「案内が必要です」 means guidance is needed. This 「〜が必要です」 is an all-purpose way to express a need — just put what you need before 「が」.","grammar:1260:ex:words:0:zh":"lead","grammar:1260:ex:words:0:note":"あんない","grammar:1260:ex:words:0:pos":"noun","grammar:1260:ex:words:1:zh":"(nominative)","grammar:1260:ex:words:1:pos":"particle","grammar:1260:ex:words:2:zh":"necessary","grammar:1260:ex:words:2:note":"ひつよう","grammar:1260:ex:words:2:pos":"na-adjective","grammar:1260:ex:words:3:zh":"(polite form)","grammar:1260:ex:words:3:pos":"copula","grammar:1260:ex:points:0":"❗案内（あんない）: guidance, guide, guidebook.","grammar:1260:ex:points:1":"案内が必要: guidance is needed.","grammar:1260:ex2:trans":"He's a good guide.","grammar:1260:ex2:structure":"〜は良い〜です","grammar:1260:ex2:words:0:zh":"he","grammar:1260:ex2:words:0:note":"かれ","grammar:1260:ex2:words:0:pos":"pronoun","grammar:1260:ex2:words:1:zh":"(topic)","grammar:1260:ex2:words:1:pos":"particle","grammar:1260:ex2:words:2:zh":"good","grammar:1260:ex2:words:2:note":"いい","grammar:1260:ex2:words:2:pos":"adjective","grammar:1260:ex2:words:3:zh":"guide","grammar:1260:ex2:words:3:note":"あんないにん","grammar:1260:ex2:words:3:pos":"noun","grammar:1260:ex2:words:4:zh":"is","grammar:1260:ex2:words:4:pos":"copula","grammar:1260:ex2:points:0":"❗案内人: guide, tour guide (案内＋人).","grammar:1260:ex2:points:1":"良い案内人: a good guide.","grammar:1260:ex3:trans":"I found the airport guide.","grammar:1260:ex3:structure":"〜の案内を見つけました","grammar:1260:ex3:words:0:zh":"airport","grammar:1260:ex3:words:0:note":"くうこう","grammar:1260:ex3:words:0:pos":"noun","grammar:1260:ex3:words:1:zh":"'s","grammar:1260:ex3:words:1:pos":"particle","grammar:1260:ex3:words:2:zh":"guidance","grammar:1260:ex3:words:2:note":"あんない","grammar:1260:ex3:words:2:pos":"noun","grammar:1260:ex3:words:3:zh":"(object marker)","grammar:1260:ex3:words:3:pos":"particle","grammar:1260:ex3:words:4:zh":"found","grammar:1260:ex3:words:4:note":"みつけました","grammar:1260:ex3:words:4:pos":"verb","grammar:1260:ex3:points:0":"❗空港の案内: airport signs / information desk.","grammar:1260:ex3:points:1":"見つける: to find.","grammar:1260:ex4:trans":"Please read this guide.","grammar:1260:ex4:structure":"〜を読んでください","grammar:1260:ex4:words:0:zh":"this","grammar:1260:ex4:words:0:pos":"pre-noun adjectival","grammar:1260:ex4:words:1:zh":"guide","grammar:1260:ex4:words:1:note":"あんない","grammar:1260:ex4:words:1:pos":"noun","grammar:1260:ex4:words:2:zh":"(object marker)","grammar:1260:ex4:words:2:pos":"particle","grammar:1260:ex4:words:3:zh":"read","grammar:1260:ex4:words:3:note":"よんで","grammar:1260:ex4:words:3:pos":"verb","grammar:1260:ex4:words:4:zh":"please","grammar:1260:ex4:words:4:pos":"auxiliary verb","grammar:1260:ex4:points:0":"この案内: this guide.","grammar:1260:ex4:points:1":"読んでください: please read.","grammar:1260:ex5:trans":"I acted according to the guidance.","grammar:1260:ex5:structure":"〜に従って〜しました","grammar:1260:ex5:words:0:zh":"guidance","grammar:1260:ex5:words:0:note":"あんない","grammar:1260:ex5:words:0:pos":"noun","grammar:1260:ex5:words:1:zh":"(object)","grammar:1260:ex5:words:1:pos":"particle","grammar:1260:ex5:words:2:zh":"in accordance with","grammar:1260:ex5:words:2:note":"したがって","grammar:1260:ex5:words:2:pos":"verb","grammar:1260:ex5:words:3:zh":"took action","grammar:1260:ex5:words:3:note":"こうどうしました","grammar:1260:ex5:words:3:pos":"verb","grammar:1260:ex5:points:0":"❗〜に従う: to follow, to obey …; 案内に従う＝to follow the instructions.","grammar:1260:ex5:points:1":"従う: to follow."},"1261":{"example:1261:exzh":"His fingerprints were found.","example:1261:exzh2":"We'll collect fingerprints.","example:1261:exzh3":"Fingerprints are used to identify individuals.","example:1261:exzh4":"I don't have fingerprints.","example:1261:exzh5":"The police are examining the fingerprints."},"1262":{"example:1262:exzh":"She behaved like a queen.","example:1262:exzh2":"The queen rules the country.","example:1262:exzh3":"We celebrate the queen's birthday.","example:1262:exzh4":"This jewel was made for the queen.","example:1262:exzh5":"We learned about queens in history."},"1263":{"example:1263:exzh":"She is wearing a red dress.","example:1263:exzh2":"When the color changes, your mood changes too.","example:1263:exzh3":"My favorite color is blue.","example:1263:exzh4":"The colors in this painting are very vivid.","example:1263:exzh5":"I drew a picture with colored pencils.","grammar:1263:ex:trans":"She is wearing a red dress.","grammar:1263:ex:structure":"〜の〜を着ています","grammar:1263:ex:explain":"The core is pre-noun modification plus 「〜を着ている」. 「赤い色のドレス」 is built up layer by layer: 「赤い」 (red) modifies 「色」, and then 「の」 links it to 「ドレス」, giving \"a red-colored dress\". With the verb 「着る」, 「着ています」 uses 「〜ている」 to express the ongoing state of \"wearing\"; this is the fixed way to talk about wearing clothes, not 「着ます」. The object 「ドレス」 takes 「を」. The whole sentence describes the clothes someone has on right now.","grammar:1263:ex:words:0:zh":"she","grammar:1263:ex:words:0:note":"かのじょ","grammar:1263:ex:words:0:pos":"pronoun","grammar:1263:ex:words:1:zh":"(topic)","grammar:1263:ex:words:1:pos":"particle","grammar:1263:ex:words:2:zh":"red","grammar:1263:ex:words:2:note":"あかい","grammar:1263:ex:words:2:pos":"adjective","grammar:1263:ex:words:3:zh":"color","grammar:1263:ex:words:3:note":"いろ","grammar:1263:ex:words:3:pos":"noun","grammar:1263:ex:words:4:zh":"'s","grammar:1263:ex:words:4:pos":"particle","grammar:1263:ex:words:5:zh":"dress","grammar:1263:ex:words:5:note":"loanword","grammar:1263:ex:words:5:pos":"noun","grammar:1263:ex:words:6:zh":"(object marker)","grammar:1263:ex:words:6:pos":"particle","grammar:1263:ex:words:7:zh":"Wearing","grammar:1263:ex:words:7:note":"きています","grammar:1263:ex:words:7:pos":"verb","grammar:1263:ex:points:0":"❗色 (いろ): color; 赤い色 = red","grammar:1263:ex:points:1":"ドレス: dress, gown","grammar:1263:ex2:trans":"When the color changes, your mood changes too.","grammar:1263:ex2:structure":"〜が変わると〜も変わります","grammar:1263:ex2:words:0:zh":"color","grammar:1263:ex2:words:0:note":"いろ","grammar:1263:ex2:words:0:pos":"noun","grammar:1263:ex2:words:1:zh":"(nominative)","grammar:1263:ex2:words:1:pos":"particle","grammar:1263:ex2:words:2:zh":"change","grammar:1263:ex2:words:2:note":"かわる","grammar:1263:ex2:words:2:pos":"verb","grammar:1263:ex2:words:3:zh":"(as soon as…)","grammar:1263:ex2:words:3:pos":"particle","grammar:1263:ex2:words:4:zh":"feeling","grammar:1263:ex2:words:4:note":"きぶん","grammar:1263:ex2:words:4:pos":"noun","grammar:1263:ex2:words:5:zh":"also, too","grammar:1263:ex2:words:5:pos":"particle","grammar:1263:ex2:words:6:zh":"change","grammar:1263:ex2:words:6:note":"かわります","grammar:1263:ex2:words:6:pos":"verb","grammar:1263:ex2:points:0":"❗〜と: as soon as…, whenever…; 気分も変わる = your mood changes too","grammar:1263:ex2:points:1":"色が変わる: to change color","grammar:1263:ex3:trans":"My favorite color is blue.","grammar:1263:ex3:structure":"好きな色は〜です","grammar:1263:ex3:words:0:zh":"to like","grammar:1263:ex3:words:0:note":"すき","grammar:1263:ex3:words:0:pos":"na-adjective","grammar:1263:ex3:words:1:zh":"(attributive form)","grammar:1263:ex3:words:1:pos":"auxiliary verb","grammar:1263:ex3:words:2:zh":"color","grammar:1263:ex3:words:2:note":"いろ","grammar:1263:ex3:words:2:pos":"noun","grammar:1263:ex3:words:3:zh":"(topic)","grammar:1263:ex3:words:3:pos":"particle","grammar:1263:ex3:words:4:zh":"blue","grammar:1263:ex3:words:4:note":"あお","grammar:1263:ex3:words:4:pos":"noun","grammar:1263:ex3:words:5:zh":"is","grammar:1263:ex3:words:5:pos":"copula","grammar:1263:ex3:points:0":"❗好きな色: favorite color; 青 = blue","grammar:1263:ex3:points:1":"青: blue","grammar:1263:ex4:trans":"The colors in this painting are very vivid.","grammar:1263:ex4:structure":"〜は色が鮮やかです","grammar:1263:ex4:words:0:zh":"this","grammar:1263:ex4:words:0:pos":"pre-noun adjectival","grammar:1263:ex4:words:1:zh":"picture","grammar:1263:ex4:words:1:note":"え","grammar:1263:ex4:words:1:pos":"noun","grammar:1263:ex4:words:2:zh":"(topic)","grammar:1263:ex4:words:2:pos":"particle","grammar:1263:ex4:words:3:zh":"color","grammar:1263:ex4:words:3:note":"いろ","grammar:1263:ex4:words:3:pos":"noun","grammar:1263:ex4:words:4:zh":"(nominative)","grammar:1263:ex4:words:4:pos":"particle","grammar:1263:ex4:words:5:zh":"extremely","grammar:1263:ex4:words:5:pos":"adverb","grammar:1263:ex4:words:6:zh":"vivid","grammar:1263:ex4:words:6:note":"あざやか","grammar:1263:ex4:words:6:pos":"na-adjective","grammar:1263:ex4:words:7:zh":"(polite form)","grammar:1263:ex4:words:7:pos":"copula","grammar:1263:ex4:points:0":"❗鮮やか: vivid, bright","grammar:1263:ex4:points:1":"色が鮮やか: vivid colors","grammar:1263:ex5:trans":"I drew a picture with colored pencils.","grammar:1263:ex5:structure":"〜で〜を描きました","grammar:1263:ex5:words:0:zh":"colored pencils","grammar:1263:ex5:words:0:note":"いろえんぴつ","grammar:1263:ex5:words:0:pos":"noun","grammar:1263:ex5:words:1:zh":"(means)","grammar:1263:ex5:words:1:pos":"particle","grammar:1263:ex5:words:2:zh":"picture","grammar:1263:ex5:words:2:note":"え","grammar:1263:ex5:words:2:pos":"noun","grammar:1263:ex5:words:3:zh":"(object marker)","grammar:1263:ex5:words:3:pos":"particle","grammar:1263:ex5:words:4:zh":"drew","grammar:1263:ex5:words:4:note":"えがきました","grammar:1263:ex5:words:4:pos":"verb","grammar:1263:ex5:points:0":"❗色鉛筆: colored pencils (色 + 鉛筆); 〜で描く = to draw with…","grammar:1263:ex5:points:1":"色鉛筆で: with colored pencils","exam:1263:zh":"This shirt comes in red and blue, so which color do you like?","exam:1263:why":"The difference between 赤 and 青 is 「色」. 「形」 means shape and can't cover the difference between red and blue."},"1264":{"example:1264:exzh":"Before using this device, read the manual first.","example:1264:exzh2":"The use of computers is increasing.","example:1264:exzh3":"Let's make sure we use it legally.","example:1264:exzh4":"Using the meeting room requires a reservation.","example:1264:exzh5":"I ran a test before using it.","grammar:1264:ex:trans":"Read the manual before using this device.","grammar:1264:ex:structure":"〜する前に、〜ましょう","grammar:1264:ex:explain":"The core is 「〜する前に」, meaning \"before doing something\"; it follows the dictionary form of a verb. Here 「使用する前に」 means \"before use\". The ending 「読みましょう」 is the polite volitional form, and 「〜ましょう」 makes a suggestion — \"let's do it\" — with an inviting tone. Both objects, 「装置」 and 「説明書」, take 「を」. The sentence is typical of manuals and guides: it first states the prerequisite action, then gives the recommendation. 「dictionary form + 前に」 is the key pattern for expressing the order of events in time.","grammar:1264:ex:words:0:zh":"this","grammar:1264:ex:words:0:pos":"pre-noun adjectival","grammar:1264:ex:words:1:zh":"device","grammar:1264:ex:words:1:note":"そうち","grammar:1264:ex:words:1:pos":"noun","grammar:1264:ex:words:2:zh":"(object marker)","grammar:1264:ex:words:2:pos":"particle","grammar:1264:ex:words:3:zh":"use","grammar:1264:ex:words:3:note":"しようする","grammar:1264:ex:words:3:pos":"verb","grammar:1264:ex:words:4:zh":"before","grammar:1264:ex:words:4:note":"まえに","grammar:1264:ex:words:4:pos":"particle","grammar:1264:ex:words:5:zh":"manual","grammar:1264:ex:words:5:note":"せつめいしょ","grammar:1264:ex:words:5:pos":"noun","grammar:1264:ex:words:6:zh":"(object marker)","grammar:1264:ex:words:6:pos":"particle","grammar:1264:ex:words:7:zh":"let's read","grammar:1264:ex:words:7:note":"よみましょう","grammar:1264:ex:words:7:pos":"verb","grammar:1264:ex:points:0":"❗〜する前に: before…; 使用する = to use; 説明書 = manual","grammar:1264:ex:points:1":"装置を使用: to use the device","grammar:1264:ex2:trans":"The use of computers is increasing.","grammar:1264:ex2:structure":"〜の使用が増えている","grammar:1264:ex2:words:0:zh":"computer","grammar:1264:ex2:words:0:note":"loanword","grammar:1264:ex2:words:0:pos":"noun","grammar:1264:ex2:words:1:zh":"'s","grammar:1264:ex2:words:1:pos":"particle","grammar:1264:ex2:words:2:zh":"use","grammar:1264:ex2:words:2:note":"しよう","grammar:1264:ex2:words:2:pos":"noun","grammar:1264:ex2:words:3:zh":"(nominative)","grammar:1264:ex2:words:3:pos":"particle","grammar:1264:ex2:words:4:zh":"increasing","grammar:1264:ex2:words:4:note":"ふえている","grammar:1264:ex2:words:4:pos":"verb","grammar:1264:ex2:points:0":"❗パソコン: personal computer; 使用が増える = usage increases","grammar:1264:ex2:points:1":"増える: to increase (intransitive verb).","grammar:1264:ex3:trans":"We should make a point of using things lawfully.","grammar:1264:ex3:structure":"〜を心がけよう","grammar:1264:ex3:words:0:zh":"lawful","grammar:1264:ex3:words:0:note":"ごうほう","grammar:1264:ex3:words:0:pos":"na-adjective","grammar:1264:ex3:words:1:zh":"(attributive form)","grammar:1264:ex3:words:1:pos":"auxiliary verb","grammar:1264:ex3:words:2:zh":"use","grammar:1264:ex3:words:2:note":"しよう","grammar:1264:ex3:words:2:pos":"noun","grammar:1264:ex3:words:3:zh":"(object marker)","grammar:1264:ex3:words:3:pos":"particle","grammar:1264:ex3:words:4:zh":"to be mindful of doing","grammar:1264:ex3:words:4:note":"こころがけよう","grammar:1264:ex3:words:4:pos":"verb","grammar:1264:ex3:points:0":"❗〜を心がける: to be mindful of doing…, to make a point of…; 合法な = lawful","grammar:1264:ex3:points:1":"心がける: to keep in mind","grammar:1264:ex4:trans":"Using the meeting room requires a reservation.","grammar:1264:ex4:structure":"〜の使用には〜が必要です","grammar:1264:ex4:words:0:zh":"meeting room","grammar:1264:ex4:words:0:note":"かいぎしつ","grammar:1264:ex4:words:0:pos":"noun","grammar:1264:ex4:words:1:zh":"'s","grammar:1264:ex4:words:1:pos":"particle","grammar:1264:ex4:words:2:zh":"use","grammar:1264:ex4:words:2:note":"しよう","grammar:1264:ex4:words:2:pos":"noun","grammar:1264:ex4:words:3:zh":"(as for)","grammar:1264:ex4:words:3:pos":"particle","grammar:1264:ex4:words:4:zh":"(topic)","grammar:1264:ex4:words:4:pos":"particle","grammar:1264:ex4:words:5:zh":"reservation","grammar:1264:ex4:words:5:note":"よやく","grammar:1264:ex4:words:5:pos":"noun","grammar:1264:ex4:words:6:zh":"(subject)","grammar:1264:ex4:words:6:pos":"particle","grammar:1264:ex4:words:7:zh":"need","grammar:1264:ex4:words:7:note":"ひつよう","grammar:1264:ex4:words:7:pos":"na-adjective","grammar:1264:ex4:words:8:zh":"(polite form)","grammar:1264:ex4:words:8:pos":"copula","grammar:1264:ex4:points:0":"「会議室の使用」: 「使用」 is a noun that attaches with 「の」 after a place or thing; it is more formal than 「使うこと」 and common in notices and regulations.","grammar:1264:ex4:points:1":"「〜には〜が必要です」 = if you want to do something, you need…; adding 「は」 after 「に」 emphasizes the condition.","grammar:1264:ex5:trans":"I ran a test before using it.","grammar:1264:ex5:structure":"〜する前にテストしました","grammar:1264:ex5:words:0:zh":"use","grammar:1264:ex5:words:0:note":"しようする","grammar:1264:ex5:words:0:pos":"verb","grammar:1264:ex5:words:1:zh":"before","grammar:1264:ex5:words:1:note":"まえに","grammar:1264:ex5:words:1:pos":"particle","grammar:1264:ex5:words:2:zh":"tested","grammar:1264:ex5:words:2:pos":"verb","grammar:1264:ex5:points:0":"❗〜する前に: before…; テストする = to test","grammar:1264:ex5:points:1":"使用する前に: before use"},"1265":{"example:1265:exzh":"The people around me helped me.","example:1265:exzh2":"Please watch your surroundings.","example:1265:exzh3":"He is sensitive to his surroundings.","example:1265:exzh4":"The scenery around here is beautiful.","example:1265:exzh5":"Do the sounds around you bother you?","grammar:1265:ex:trans":"The people around me helped me.","grammar:1265:ex:structure":"〜の人々が〜てくれた","grammar:1265:ex:explain":"The core is the auxiliary verb of giving and receiving 「〜てくれる」, which means someone does something for me, with a nuance of receiving a favor and of gratitude. 「助けてくれた」 means \"(they) helped me\": the doer is the people around the speaker, the beneficiary is the speaker, and the sentence is in the past tense. The subject 「人々」 takes 「が」. 「周りの」 modifies with 「の」 and means \"surrounding\". Remember that 「〜てくれる」 takes the beneficiary's point of view; it is the key pattern for saying that someone helped you.","grammar:1265:ex:words:0:zh":"surroundings","grammar:1265:ex:words:0:note":"まわり","grammar:1265:ex:words:0:pos":"noun","grammar:1265:ex:words:1:zh":"'s","grammar:1265:ex:words:1:pos":"particle","grammar:1265:ex:words:2:zh":"people","grammar:1265:ex:words:2:note":"ひとびと","grammar:1265:ex:words:2:pos":"noun","grammar:1265:ex:words:3:zh":"(nominative)","grammar:1265:ex:words:3:pos":"particle","grammar:1265:ex:words:4:zh":"help","grammar:1265:ex:words:4:note":"たすけて","grammar:1265:ex:words:4:pos":"verb","grammar:1265:ex:words:5:zh":"did (for me)","grammar:1265:ex:words:5:pos":"auxiliary verb","grammar:1265:ex:points:0":"❗周り (まわり): surroundings, around; 〜てくれる = to do… (for me)","grammar:1265:ex:points:1":"周りの人々: the people around you","grammar:1265:ex2:trans":"Please watch out for your surroundings.","grammar:1265:ex2:structure":"〜に気を付けてください","grammar:1265:ex2:words:0:zh":"surroundings","grammar:1265:ex2:words:0:note":"まわり","grammar:1265:ex2:words:0:pos":"noun","grammar:1265:ex2:words:1:zh":"(object)","grammar:1265:ex2:words:1:pos":"particle","grammar:1265:ex2:words:2:zh":"be mindful of","grammar:1265:ex2:words:2:note":"きをつけて","grammar:1265:ex2:words:2:pos":"set phrase","grammar:1265:ex2:words:3:zh":"please","grammar:1265:ex2:words:3:pos":"auxiliary verb","grammar:1265:ex2:points:0":"❗気を付ける: to be careful, to watch out (set phrase); 周りに = toward your surroundings","grammar:1265:ex2:points:1":"気を付ける: to watch out","grammar:1265:ex3:trans":"He is sensitive to the environment around him.","grammar:1265:ex3:structure":"〜に敏感だ","grammar:1265:ex3:words:0:zh":"he","grammar:1265:ex3:words:0:note":"かれ","grammar:1265:ex3:words:0:pos":"pronoun","grammar:1265:ex3:words:1:zh":"(topic)","grammar:1265:ex3:words:1:pos":"particle","grammar:1265:ex3:words:2:zh":"surroundings","grammar:1265:ex3:words:2:note":"まわり","grammar:1265:ex3:words:2:pos":"noun","grammar:1265:ex3:words:3:zh":"'s","grammar:1265:ex3:words:3:pos":"particle","grammar:1265:ex3:words:4:zh":"environment","grammar:1265:ex3:words:4:note":"かんきょう","grammar:1265:ex3:words:4:pos":"noun","grammar:1265:ex3:words:5:zh":"(object)","grammar:1265:ex3:words:5:pos":"particle","grammar:1265:ex3:words:6:zh":"sensitive","grammar:1265:ex3:words:6:note":"びんかん","grammar:1265:ex3:words:6:pos":"na-adjective","grammar:1265:ex3:words:7:zh":"is","grammar:1265:ex3:words:7:pos":"copula","grammar:1265:ex3:points:0":"❗〜に敏感: sensitive to… (the target takes に); 周りの環境 = the surrounding environment","grammar:1265:ex3:points:1":"敏感: sensitive","grammar:1265:ex4:trans":"The scenery around is beautiful.","grammar:1265:ex4:structure":"〜の景色が美しいです","grammar:1265:ex4:words:0:zh":"surroundings","grammar:1265:ex4:words:0:note":"まわり","grammar:1265:ex4:words:0:pos":"noun","grammar:1265:ex4:words:1:zh":"'s","grammar:1265:ex4:words:1:pos":"particle","grammar:1265:ex4:words:2:zh":"scenery","grammar:1265:ex4:words:2:note":"けしき","grammar:1265:ex4:words:2:pos":"noun","grammar:1265:ex4:words:3:zh":"(nominative)","grammar:1265:ex4:words:3:pos":"particle","grammar:1265:ex4:words:4:zh":"beautiful","grammar:1265:ex4:words:4:note":"うつくしい","grammar:1265:ex4:words:4:pos":"adjective","grammar:1265:ex4:words:5:zh":"(polite form)","grammar:1265:ex4:words:5:pos":"copula","grammar:1265:ex4:points:0":"周りの景色: the surrounding scenery","grammar:1265:ex4:points:1":"美しい: beautiful.","grammar:1265:ex5:trans":"Do the sounds around you bother you?","grammar:1265:ex5:structure":"〜が気になりますか","grammar:1265:ex5:words:0:zh":"surroundings","grammar:1265:ex5:words:0:note":"まわり","grammar:1265:ex5:words:0:pos":"noun","grammar:1265:ex5:words:1:zh":"'s","grammar:1265:ex5:words:1:pos":"particle","grammar:1265:ex5:words:2:zh":"voice","grammar:1265:ex5:words:2:note":"おと","grammar:1265:ex5:words:2:pos":"noun","grammar:1265:ex5:words:3:zh":"(nominative)","grammar:1265:ex5:words:3:pos":"particle","grammar:1265:ex5:words:4:zh":"be on one's mind","grammar:1265:ex5:words:4:note":"きになります","grammar:1265:ex5:words:4:pos":"verb","grammar:1265:ex5:words:5:zh":"(question)","grammar:1265:ex5:words:5:pos":"particle","grammar:1265:ex5:points:0":"❗気になる: to weigh on your mind, to bother you (set phrase); 周りの音 = the sounds around you","grammar:1265:ex5:points:1":"気になる: to be on your mind"},"1266":{"example:1266:exzh":"I ran into an old friend by chance.","example:1266:exzh2":"Accidental discoveries are important.","example:1266:exzh3":"That chance encounter changed my life.","example:1266:exzh4":"Coincidental events sometimes happen.","example:1266:exzh5":"I found the book at the library by chance."},"1267":{"example:1267:exzh":"We decided to sign a lease agreement.","example:1267:exzh2":"This car is leased.","example:1267:exzh3":"Please check the lease terms.","example:1267:exzh4":"A long-term lease is more economical.","example:1267:exzh5":"We plan to use a leasing company."},"1268":{"example:1268:exzh":"Data processing is slow.","example:1268:exzh2":"Processing that is difficult.","example:1268:exzh3":"You need the ability to handle problems.","example:1268:exzh4":"This software processes things quickly.","example:1268:exzh5":"I'll report once the processing is finished."},"1270":{"example:1270:exzh":"This rule is very important.","example:1270:exzh2":"Every game has its own rules.","example:1270:exzh3":"You must follow the rules.","example:1270:exzh4":"Let's teach the children the rules.","example:1270:exzh5":"The new rules have been decided.","grammar:1270:ex:trans":"This rule is very important.","grammar:1270:ex:structure":"〜はとても重要です","grammar:1270:ex:explain":"This is an 「Aは〜です」 adjective sentence; 「重要」 is a na-adjective, so 「です」 attaches directly at the end. 「は」 marks the topic 「このルール」, and the adverb 「とても」 modifies 「重要」 to strengthen the degree. 「ルール」 is a loanword meaning rule or regulation. The structure is simple: this is the basic way to say that something is important. Remember that when a na-adjective is the sentence-final predicate, it takes 「です」 directly, without 「な」.","grammar:1270:ex:words:0:zh":"this","grammar:1270:ex:words:0:pos":"pre-noun adjectival","grammar:1270:ex:words:1:zh":"rule","grammar:1270:ex:words:1:note":"loanword","grammar:1270:ex:words:1:pos":"noun","grammar:1270:ex:words:2:zh":"(topic)","grammar:1270:ex:words:2:pos":"particle","grammar:1270:ex:words:3:zh":"extremely","grammar:1270:ex:words:3:pos":"adverb","grammar:1270:ex:words:4:zh":"important","grammar:1270:ex:words:4:note":"じゅうよう","grammar:1270:ex:words:4:pos":"na-adjective","grammar:1270:ex:words:5:zh":"(polite form)","grammar:1270:ex:words:5:pos":"copula","grammar:1270:ex:points:0":"❗ルール: rule, regulation","grammar:1270:ex:points:1":"このルール: this rule","grammar:1270:ex2:trans":"Every game has its own rules.","grammar:1270:ex2:structure":"〜にはそれぞれの〜があります","grammar:1270:ex2:words:0:zh":"game","grammar:1270:ex2:words:0:note":"loanword","grammar:1270:ex2:words:0:pos":"noun","grammar:1270:ex2:words:1:zh":"(object)","grammar:1270:ex2:words:1:pos":"particle","grammar:1270:ex2:words:2:zh":"(contrast)","grammar:1270:ex2:words:2:pos":"particle","grammar:1270:ex2:words:3:zh":"each","grammar:1270:ex2:words:3:pos":"noun","grammar:1270:ex2:words:4:zh":"'s","grammar:1270:ex2:words:4:pos":"particle","grammar:1270:ex2:words:5:zh":"rule","grammar:1270:ex2:words:5:note":"loanword","grammar:1270:ex2:words:5:pos":"noun","grammar:1270:ex2:words:6:zh":"(nominative)","grammar:1270:ex2:words:6:pos":"particle","grammar:1270:ex2:words:7:zh":"there is / are","grammar:1270:ex2:words:7:pos":"verb","grammar:1270:ex2:points:0":"❗それぞれの: each one's, respective","grammar:1270:ex2:points:1":"ゲームにはルール: games have rules","grammar:1270:ex3:trans":"You must follow the rules.","grammar:1270:ex3:structure":"〜を守らなければなりません","grammar:1270:ex3:words:0:zh":"rule","grammar:1270:ex3:words:0:note":"loanword","grammar:1270:ex3:words:0:pos":"noun","grammar:1270:ex3:words:1:zh":"(object marker)","grammar:1270:ex3:words:1:pos":"particle","grammar:1270:ex3:words:2:zh":"must follow","grammar:1270:ex3:words:2:note":"まもらなければなりません","grammar:1270:ex3:words:2:pos":"verb","grammar:1270:ex3:points:0":"❗〜なければなりません: must…; ルールを守る = to follow the rules","grammar:1270:ex3:points:1":"守る: to follow, to obey","grammar:1270:ex4:trans":"Let's teach children the rules.","grammar:1270:ex4:structure":"〜に〜を教えましょう","grammar:1270:ex4:words:0:zh":"child","grammar:1270:ex4:words:0:note":"こども","grammar:1270:ex4:words:0:pos":"noun","grammar:1270:ex4:words:1:zh":"(object)","grammar:1270:ex4:words:1:pos":"particle","grammar:1270:ex4:words:2:zh":"rule","grammar:1270:ex4:words:2:note":"loanword","grammar:1270:ex4:words:2:pos":"noun","grammar:1270:ex4:words:3:zh":"(object marker)","grammar:1270:ex4:words:3:pos":"particle","grammar:1270:ex4:words:4:zh":"let's teach","grammar:1270:ex4:words:4:note":"おしえましょう","grammar:1270:ex4:words:4:pos":"verb","grammar:1270:ex4:points:0":"❗〜に〜を教える: to teach (someone) (something); 〜ましょう = a suggestion","grammar:1270:ex4:points:1":"子供に教える: to teach children","grammar:1270:ex5:trans":"The new rules have been decided.","grammar:1270:ex5:structure":"〜が決まりました","grammar:1270:ex5:words:0:zh":"new","grammar:1270:ex5:words:0:note":"あたらしい","grammar:1270:ex5:words:0:pos":"adjective","grammar:1270:ex5:words:1:zh":"rule","grammar:1270:ex5:words:1:note":"loanword","grammar:1270:ex5:words:1:pos":"noun","grammar:1270:ex5:words:2:zh":"(nominative)","grammar:1270:ex5:words:2:pos":"particle","grammar:1270:ex5:words:3:zh":"was decided","grammar:1270:ex5:words:3:note":"きまりました","grammar:1270:ex5:words:3:pos":"verb","grammar:1270:ex5:points:0":"❗決まる: to be settled, to be decided (intransitive verb); vs 決める (transitive verb)","grammar:1270:ex5:points:1":"ルールが決まる: the rules are settled"},"1271":{"example:1271:exzh":"This song is very popular.","example:1271:exzh2":"He is composing his own songs.","example:1271:exzh3":"Have you listened to the new song?","example:1271:exzh4":"This song touches the heart.","example:1271:exzh5":"The music is playing, so let's enjoy the song.","grammar:1271:ex:trans":"This song is very popular.","grammar:1271:ex:structure":"〜は人気があります","grammar:1271:ex:explain":"The core is the set expression 「人気がある」, literally \"has popularity\" — the fixed way to say \"is popular\", with 「人気」 marked as the subject by 「が」. 「あります」 is the polite form of 「ある」. 「は」 marks the topic 「この曲」, and the adverb 「とても」 strengthens the degree. Remember that 「人気がある／人気だ」 is the usual pairing for talking about popularity — don't mistakenly say 「人気をする」. The sentence says that a song is a big hit.","grammar:1271:ex:words:0:zh":"this","grammar:1271:ex:words:0:pos":"pre-noun adjectival","grammar:1271:ex:words:1:zh":"song","grammar:1271:ex:words:1:note":"きょく","grammar:1271:ex:words:1:pos":"noun","grammar:1271:ex:words:2:zh":"(topic)","grammar:1271:ex:words:2:pos":"particle","grammar:1271:ex:words:3:zh":"extremely","grammar:1271:ex:words:3:pos":"adverb","grammar:1271:ex:words:4:zh":"popularity","grammar:1271:ex:words:4:note":"にんき","grammar:1271:ex:words:4:pos":"noun","grammar:1271:ex:words:5:zh":"(nominative)","grammar:1271:ex:words:5:pos":"particle","grammar:1271:ex:words:6:zh":"there is / are","grammar:1271:ex:words:6:pos":"verb","grammar:1271:ex:points:0":"❗曲 (きょく): song, tune; 人気がある = to be popular","grammar:1271:ex:points:1":"この曲: this song","grammar:1271:ex2:trans":"He is writing his own songs.","grammar:1271:ex2:structure":"〜を作っています","grammar:1271:ex2:words:0:zh":"he","grammar:1271:ex2:words:0:note":"かれ","grammar:1271:ex2:words:0:pos":"pronoun","grammar:1271:ex2:words:1:zh":"(topic)","grammar:1271:ex2:words:1:pos":"particle","grammar:1271:ex2:words:2:zh":"oneself","grammar:1271:ex2:words:2:note":"じぶん","grammar:1271:ex2:words:2:pos":"noun","grammar:1271:ex2:words:3:zh":"'s","grammar:1271:ex2:words:3:pos":"particle","grammar:1271:ex2:words:4:zh":"song","grammar:1271:ex2:words:4:note":"きょく","grammar:1271:ex2:words:4:pos":"noun","grammar:1271:ex2:words:5:zh":"(object marker)","grammar:1271:ex2:words:5:pos":"particle","grammar:1271:ex2:words:6:zh":"is creating","grammar:1271:ex2:words:6:note":"つくっています","grammar:1271:ex2:words:6:pos":"verb","grammar:1271:ex2:points:0":"❗曲を作る: to write a song; 自分の曲 = one's own song","grammar:1271:ex2:points:1":"作る: to create","grammar:1271:ex3:trans":"Have you listened to the new song?","grammar:1271:ex3:structure":"〜を聴いてみましたか","grammar:1271:ex3:words:0:zh":"new","grammar:1271:ex3:words:0:note":"あたらしい","grammar:1271:ex3:words:0:pos":"adjective","grammar:1271:ex3:words:1:zh":"song","grammar:1271:ex3:words:1:note":"きょく","grammar:1271:ex3:words:1:pos":"noun","grammar:1271:ex3:words:2:zh":"(object marker)","grammar:1271:ex3:words:2:pos":"particle","grammar:1271:ex3:words:3:zh":"listen","grammar:1271:ex3:words:3:note":"きいて","grammar:1271:ex3:words:3:pos":"verb","grammar:1271:ex3:words:4:zh":"try","grammar:1271:ex3:words:4:pos":"auxiliary verb","grammar:1271:ex3:words:5:zh":"(question)","grammar:1271:ex3:words:5:pos":"particle","grammar:1271:ex3:points:0":"❗〜てみる: to try… (and see); 曲を聴く = to listen to a song","grammar:1271:ex3:points:1":"聴いてみる: to give it a listen","grammar:1271:ex4:trans":"This song touches the heart.","grammar:1271:ex4:structure":"〜は心に響きます","grammar:1271:ex4:words:0:zh":"this","grammar:1271:ex4:words:0:pos":"pre-noun adjectival","grammar:1271:ex4:words:1:zh":"song","grammar:1271:ex4:words:1:note":"きょく","grammar:1271:ex4:words:1:pos":"noun","grammar:1271:ex4:words:2:zh":"(topic)","grammar:1271:ex4:words:2:pos":"particle","grammar:1271:ex4:words:3:zh":"heart","grammar:1271:ex4:words:3:note":"こころ","grammar:1271:ex4:words:3:pos":"noun","grammar:1271:ex4:words:4:zh":"(object)","grammar:1271:ex4:words:4:pos":"particle","grammar:1271:ex4:words:5:zh":"resonated","grammar:1271:ex4:words:5:note":"ひびきます","grammar:1271:ex4:words:5:pos":"verb","grammar:1271:ex4:points:0":"❗心に響く: to touch the heart, to resonate (set phrase); 響く = to echo","grammar:1271:ex4:points:1":"心に響く: to strike a chord","grammar:1271:ex5:trans":"The music is playing, so let's enjoy the song.","grammar:1271:ex5:structure":"〜ので、〜を楽しみましょう","grammar:1271:ex5:words:0:zh":"music","grammar:1271:ex5:words:0:note":"おんがく","grammar:1271:ex5:words:0:pos":"noun","grammar:1271:ex5:words:1:zh":"(nominative)","grammar:1271:ex5:words:1:pos":"particle","grammar:1271:ex5:words:2:zh":"is playing","grammar:1271:ex5:words:2:note":"ながれている","grammar:1271:ex5:words:2:pos":"verb","grammar:1271:ex5:words:3:zh":"because","grammar:1271:ex5:words:3:pos":"particle","grammar:1271:ex5:words:4:zh":"song","grammar:1271:ex5:words:4:note":"きょく","grammar:1271:ex5:words:4:pos":"noun","grammar:1271:ex5:words:5:zh":"(object marker)","grammar:1271:ex5:words:5:pos":"particle","grammar:1271:ex5:words:6:zh":"let's enjoy","grammar:1271:ex5:words:6:note":"たのしみましょう","grammar:1271:ex5:words:6:pos":"verb","grammar:1271:ex5:points:0":"❗音楽が流れる: music plays (流れる is an intransitive verb); 〜ので = because…","grammar:1271:ex5:points:1":"曲を楽しむ: to enjoy the song"},"1272":{"example:1272:exzh":"It is important for citizens to take part in elections.","example:1272:exzh2":"The citizens of this city are kind.","example:1272:exzh3":"Let's express our opinions through civic activities.","example:1272:exzh4":"Having citizenship is important.","example:1272:exzh5":"We need to listen to the voices of the citizens."},"1275":{"example:1275:exzh":"Where is the restroom?","example:1275:exzh2":"I cleaned the restroom.","example:1275:exzh3":"The restroom is crowded.","example:1275:exzh4":"The restroom has a place to wash your hands.","example:1275:exzh5":"That restroom is clean.","grammar:1275:ex:trans":"Where is the restroom?","grammar:1275:ex:structure":"〜はどこですか","grammar:1275:ex:explain":"The core is the question word 「どこ」 plus 「〜はどこですか」, used to ask where something is — the most practical pattern for asking directions. 「は」 marks the topic 「トイレ」, 「です」 is the polite copula, and 「か」 makes it a question. 「トイレ」 is a loanword meaning toilet or restroom. The sentence 「トイレはどこですか」 is essential when traveling or out and about. Remember that to ask about a place you use 「〜はどこですか」, putting the thing you're looking for before 「は」.","grammar:1275:ex:words:0:zh":"restroom","grammar:1275:ex:words:0:note":"loanword","grammar:1275:ex:words:0:pos":"noun","grammar:1275:ex:words:1:zh":"(topic)","grammar:1275:ex:words:1:pos":"particle","grammar:1275:ex:words:2:zh":"where","grammar:1275:ex:words:2:pos":"pronoun","grammar:1275:ex:words:3:zh":"is","grammar:1275:ex:words:3:pos":"copula","grammar:1275:ex:words:4:zh":"(question)","grammar:1275:ex:words:4:pos":"particle","grammar:1275:ex:points:0":"❗トイレ: toilet, restroom","grammar:1275:ex:points:1":"どこですか: where is it.","grammar:1275:ex2:trans":"I cleaned the restroom.","grammar:1275:ex2:structure":"〜を掃除しました","grammar:1275:ex2:words:0:zh":"restroom","grammar:1275:ex2:words:0:note":"loanword","grammar:1275:ex2:words:0:pos":"noun","grammar:1275:ex2:words:1:zh":"(object marker)","grammar:1275:ex2:words:1:pos":"particle","grammar:1275:ex2:words:2:zh":"cleaned","grammar:1275:ex2:words:2:note":"そうじしました","grammar:1275:ex2:words:2:pos":"verb","grammar:1275:ex2:points:0":"❗トイレを掃除: to clean the restroom; 掃除する = to clean","grammar:1275:ex2:points:1":"掃除する: to clean","grammar:1275:ex3:trans":"The restroom is crowded.","grammar:1275:ex3:structure":"〜が混んでいます","grammar:1275:ex3:words:0:zh":"restroom","grammar:1275:ex3:words:0:note":"loanword","grammar:1275:ex3:words:0:pos":"noun","grammar:1275:ex3:words:1:zh":"(nominative)","grammar:1275:ex3:words:1:pos":"particle","grammar:1275:ex3:words:2:zh":"crowded","grammar:1275:ex3:words:2:note":"こんでいます","grammar:1275:ex3:words:2:pos":"verb","grammar:1275:ex3:points:0":"❗混む: be crowded (intransitive verb).","grammar:1275:ex3:points:1":"トイレが混む: the restroom is crowded (there's a line)","grammar:1275:ex4:trans":"There is a place to wash your hands in the restroom.","grammar:1275:ex4:structure":"〜には〜場所があります","grammar:1275:ex4:words:0:zh":"restroom","grammar:1275:ex4:words:0:note":"loanword","grammar:1275:ex4:words:0:pos":"noun","grammar:1275:ex4:words:1:zh":"(location of existence)","grammar:1275:ex4:words:1:pos":"particle","grammar:1275:ex4:words:2:zh":"(contrast)","grammar:1275:ex4:words:2:pos":"particle","grammar:1275:ex4:words:3:zh":"hand","grammar:1275:ex4:words:3:note":"て","grammar:1275:ex4:words:3:pos":"noun","grammar:1275:ex4:words:4:zh":"(object marker)","grammar:1275:ex4:words:4:pos":"particle","grammar:1275:ex4:words:5:zh":"wash","grammar:1275:ex4:words:5:note":"あらう","grammar:1275:ex4:words:5:pos":"verb","grammar:1275:ex4:words:6:zh":"place","grammar:1275:ex4:words:6:note":"ばしょ","grammar:1275:ex4:words:6:pos":"noun","grammar:1275:ex4:words:7:zh":"(nominative)","grammar:1275:ex4:words:7:pos":"particle","grammar:1275:ex4:words:8:zh":"there is / are","grammar:1275:ex4:words:8:pos":"verb","grammar:1275:ex4:points:0":"❗手を洗う場所: a place to wash your hands (attributive form)","grammar:1275:ex4:points:1":"手を洗う: to wash your hands","grammar:1275:ex5:trans":"That restroom is clean.","grammar:1275:ex5:structure":"〜はきれいです","grammar:1275:ex5:words:0:zh":"that","grammar:1275:ex5:words:0:pos":"pre-noun adjectival","grammar:1275:ex5:words:1:zh":"restroom","grammar:1275:ex5:words:1:note":"loanword","grammar:1275:ex5:words:1:pos":"noun","grammar:1275:ex5:words:2:zh":"(topic)","grammar:1275:ex5:words:2:pos":"particle","grammar:1275:ex5:words:3:zh":"clean","grammar:1275:ex5:words:3:pos":"na-adjective","grammar:1275:ex5:words:4:zh":"(polite form)","grammar:1275:ex5:words:4:pos":"copula","grammar:1275:ex5:points:0":"❗きれい: clean, pretty (na-adjective)","grammar:1275:ex5:points:1":"トイレがきれい: the restroom is clean","exam:1275:zh":"After washing my hands, I also cleaned the toilet bowl in the bathroom.","exam:1275:why":"「便器」 is a toilet bowl, and the place it's in is the 「トイレ」. 「台所」 is a kitchen; you can wash your hands there, but it's not where a toilet bowl is installed."},"1276":{"example:1276:exzh":"He caught the flu.","example:1276:exzh2":"Let's wash our hands to prevent infection.","example:1276:exzh3":"A new infectious disease is spreading.","example:1276:exzh4":"It's rough when you come down with an infectious disease.","example:1276:exzh5":"A test is needed to confirm the infection."},"1277":{"example:1277:exzh":"I'm glad to see you.","example:1277:exzh2":"She looks happy that she passed.","example:1277:exzh3":"There was some happy news.","example:1277:exzh4":"Celebrating a birthday is always a joy.","example:1277:exzh5":"He was happy to receive a present.","grammar:1277:ex:trans":"I'm happy to see you.","grammar:1277:ex:structure":"〜に会えて嬉しいです","grammar:1277:ex:explain":"The core is 「〜に会えて嬉しい」, which expresses being happy that you could meet someone. 「会えて」 is the te-form of the potential verb 「会える」 (to be able to meet); the te-form here shows cause, namely because I could meet you, I'm happy. The person you meet, 「あなた」, is marked with 「に」. 「嬉しい」 is an i-adjective expressing joy. The whole sentence is a very appropriate greeting when meeting someone for the first time or reuniting after a long time; 「〜て嬉しい」 uses the te-form to give the reason for the feeling, which sounds very natural.","grammar:1277:ex:words:0:zh":"I","grammar:1277:ex:words:0:note":"わたし","grammar:1277:ex:words:0:pos":"pronoun","grammar:1277:ex:words:1:zh":"(topic)","grammar:1277:ex:words:1:pos":"particle","grammar:1277:ex:words:2:zh":"you","grammar:1277:ex:words:2:pos":"pronoun","grammar:1277:ex:words:3:zh":"(object)","grammar:1277:ex:words:3:pos":"particle","grammar:1277:ex:words:4:zh":"being able to meet","grammar:1277:ex:words:4:note":"あえて","grammar:1277:ex:words:4:pos":"verb","grammar:1277:ex:words:5:zh":"be happy","grammar:1277:ex:words:5:note":"うれしい","grammar:1277:ex:words:5:pos":"adjective","grammar:1277:ex:words:6:zh":"(polite form)","grammar:1277:ex:words:6:pos":"copula","grammar:1277:ex:points:0":"❗〜に会えて嬉しい: happy to meet … (the potential form 会える + て).","grammar:1277:ex:points:1":"嬉しい: happy, glad.","grammar:1277:ex2:trans":"She looks happy that she passed.","grammar:1277:ex2:structure":"〜して嬉しそうです","grammar:1277:ex2:words:0:zh":"she","grammar:1277:ex2:words:0:note":"かのじょ","grammar:1277:ex2:words:0:pos":"pronoun","grammar:1277:ex2:words:1:zh":"(topic)","grammar:1277:ex2:words:1:pos":"particle","grammar:1277:ex2:words:2:zh":"passing","grammar:1277:ex2:words:2:note":"ごうかくして","grammar:1277:ex2:words:2:pos":"verb","grammar:1277:ex2:words:3:zh":"looks happy","grammar:1277:ex2:words:3:note":"うれしそう","grammar:1277:ex2:words:3:pos":"set phrase","grammar:1277:ex2:words:4:zh":"(polite form)","grammar:1277:ex2:words:4:pos":"copula","grammar:1277:ex2:points:0":"❗嬉しそう: looks happy (嬉しい→嬉しそう, appearance form).","grammar:1277:ex2:points:1":"合格する: to pass (an exam).","grammar:1277:ex3:trans":"There was some happy news.","grammar:1277:ex3:structure":"〜がありました","grammar:1277:ex3:words:0:zh":"happy","grammar:1277:ex3:words:0:note":"うれしい","grammar:1277:ex3:words:0:pos":"adjective","grammar:1277:ex3:words:1:zh":"news","grammar:1277:ex3:words:1:note":"loanword","grammar:1277:ex3:words:1:pos":"noun","grammar:1277:ex3:words:2:zh":"(nominative)","grammar:1277:ex3:words:2:pos":"particle","grammar:1277:ex3:words:3:zh":"there is / are","grammar:1277:ex3:words:3:pos":"verb","grammar:1277:ex3:points:0":"嬉しいニュース: good news.","grammar:1277:ex3:points:1":"〜がありました: there was …","grammar:1277:ex4:trans":"Celebrating a birthday always makes people happy.","grammar:1277:ex4:structure":"〜のは嬉しいです","grammar:1277:ex4:words:0:zh":"birthday","grammar:1277:ex4:words:0:note":"たんじょうび","grammar:1277:ex4:words:0:pos":"noun","grammar:1277:ex4:words:1:zh":"(object marker)","grammar:1277:ex4:words:1:pos":"particle","grammar:1277:ex4:words:2:zh":"celebrating","grammar:1277:ex4:words:2:note":"いわう","grammar:1277:ex4:words:2:pos":"verb","grammar:1277:ex4:words:3:zh":"(nominalizer)","grammar:1277:ex4:words:3:pos":"particle","grammar:1277:ex4:words:4:zh":"(topic)","grammar:1277:ex4:words:4:pos":"particle","grammar:1277:ex4:words:5:zh":"be happy","grammar:1277:ex4:words:5:note":"うれしい","grammar:1277:ex4:words:5:pos":"adjective","grammar:1277:ex4:words:6:zh":"(polite form)","grammar:1277:ex4:words:6:pos":"copula","grammar:1277:ex4:points:0":"誕生日を祝う: to celebrate a birthday.","grammar:1277:ex4:points:1":"〜のは嬉しい: doing … makes one happy.","grammar:1277:ex5:trans":"He was happy to receive a present.","grammar:1277:ex5:structure":"〜をもらって嬉しかった","grammar:1277:ex5:words:0:zh":"he","grammar:1277:ex5:words:0:note":"かれ","grammar:1277:ex5:words:0:pos":"pronoun","grammar:1277:ex5:words:1:zh":"(topic)","grammar:1277:ex5:words:1:pos":"particle","grammar:1277:ex5:words:2:zh":"present","grammar:1277:ex5:words:2:note":"loanword","grammar:1277:ex5:words:2:pos":"noun","grammar:1277:ex5:words:3:zh":"(object marker)","grammar:1277:ex5:words:3:pos":"particle","grammar:1277:ex5:words:4:zh":"receiving","grammar:1277:ex5:words:4:pos":"verb","grammar:1277:ex5:words:5:zh":"(past) was happy","grammar:1277:ex5:words:5:note":"うれしかった","grammar:1277:ex5:words:5:pos":"adjective","grammar:1277:ex5:points:0":"❗プレゼントをもらう: to receive a present (もらう, the receiving verb).","grammar:1277:ex5:points:1":"〜て嬉しかった: was happy because of …"},"1278":{"example:1278:exzh":"The surgery was successful.","example:1278:exzh2":"He needs to have surgery.","example:1278:exzh3":"There are several tests before the surgery.","example:1278:exzh4":"He recovered quickly after the surgery.","example:1278:exzh5":"How long does the surgery take?"},"1279":{"example:1279:exzh":"I love my parents very much.","example:1279:exzh2":"Parents have love for their children.","example:1279:exzh3":"My parents are busy every day.","example:1279:exzh4":"I went on a trip with my parents.","example:1279:exzh5":"My parents always support me.","grammar:1279:ex:trans":"I love my parents very much.","grammar:1279:ex:structure":"〜が大好きです","grammar:1279:ex:explain":"The core is 「〜が大好きです」; the thing you like is marked with 「が」, not 「を」— this is a fixed rule in Japanese for liking and disliking something and for ability. 「大好き」 is the stronger version of 「好き」, meaning to love something. 「は」 marks the topic 「私」, and 「親」 means parents. The whole sentence simply means I love my parents. Remember that 「〜が好き／大好き」 takes 「が」— this is where beginners most often write 「を」 by mistake.","grammar:1279:ex:words:0:zh":"I","grammar:1279:ex:words:0:note":"わたし","grammar:1279:ex:words:0:pos":"pronoun","grammar:1279:ex:words:1:zh":"(topic)","grammar:1279:ex:words:1:pos":"particle","grammar:1279:ex:words:2:zh":"parents","grammar:1279:ex:words:2:note":"おや","grammar:1279:ex:words:2:pos":"noun","grammar:1279:ex:words:3:zh":"(object)","grammar:1279:ex:words:3:pos":"particle","grammar:1279:ex:words:4:zh":"love","grammar:1279:ex:words:4:note":"だいすき","grammar:1279:ex:words:4:pos":"na-adjective","grammar:1279:ex:words:5:zh":"(polite form)","grammar:1279:ex:words:5:pos":"copula","grammar:1279:ex:points:0":"❗親（おや）: parents; 〜が大好き = to love…","grammar:1279:ex:points:1":"親が大好き: to love one's parents.","grammar:1279:ex2:trans":"Parents have love for their children.","grammar:1279:ex2:structure":"〜に〜を持っています","grammar:1279:ex2:words:0:zh":"parents","grammar:1279:ex2:words:0:note":"おや","grammar:1279:ex2:words:0:pos":"noun","grammar:1279:ex2:words:1:zh":"(topic)","grammar:1279:ex2:words:1:pos":"particle","grammar:1279:ex2:words:2:zh":"child","grammar:1279:ex2:words:2:note":"こども","grammar:1279:ex2:words:2:pos":"noun","grammar:1279:ex2:words:3:zh":"(object)","grammar:1279:ex2:words:3:pos":"particle","grammar:1279:ex2:words:4:zh":"love","grammar:1279:ex2:words:4:note":"あいじょう","grammar:1279:ex2:words:4:pos":"noun","grammar:1279:ex2:words:5:zh":"(object marker)","grammar:1279:ex2:words:5:pos":"particle","grammar:1279:ex2:words:6:zh":"to hold","grammar:1279:ex2:words:6:note":"もっています","grammar:1279:ex2:words:6:pos":"verb","grammar:1279:ex2:points:0":"❗〜に愛情を持つ: to feel love for… (the target takes に); 愛情 = love.","grammar:1279:ex2:points:1":"愛情を持つ: to hold affection.","grammar:1279:ex3:trans":"My parents are busy every day.","grammar:1279:ex3:structure":"〜の親は忙しいです","grammar:1279:ex3:words:0:zh":"I","grammar:1279:ex3:words:0:note":"わたし","grammar:1279:ex3:words:0:pos":"pronoun","grammar:1279:ex3:words:1:zh":"'s","grammar:1279:ex3:words:1:pos":"particle","grammar:1279:ex3:words:2:zh":"parents","grammar:1279:ex3:words:2:note":"おや","grammar:1279:ex3:words:2:pos":"noun","grammar:1279:ex3:words:3:zh":"(topic)","grammar:1279:ex3:words:3:pos":"particle","grammar:1279:ex3:words:4:zh":"every day","grammar:1279:ex3:words:4:note":"まいにち","grammar:1279:ex3:words:4:pos":"adverb","grammar:1279:ex3:words:5:zh":"busy","grammar:1279:ex3:words:5:note":"いそがしい","grammar:1279:ex3:words:5:pos":"adjective","grammar:1279:ex3:words:6:zh":"(polite form)","grammar:1279:ex3:words:6:pos":"copula","grammar:1279:ex3:points:0":"私の親: my parents.","grammar:1279:ex3:points:1":"毎日忙しい: busy every day.","grammar:1279:ex4:trans":"I went on a trip with my parents.","grammar:1279:ex4:structure":"〜と一緒に旅行に行きました","grammar:1279:ex4:words:0:zh":"parents","grammar:1279:ex4:words:0:note":"おや","grammar:1279:ex4:words:0:pos":"noun","grammar:1279:ex4:words:1:zh":"with","grammar:1279:ex4:words:1:pos":"particle","grammar:1279:ex4:words:2:zh":"together","grammar:1279:ex4:words:2:note":"いっしょに","grammar:1279:ex4:words:2:pos":"adverb","grammar:1279:ex4:words:3:zh":"travel / trip","grammar:1279:ex4:words:3:note":"りょこう","grammar:1279:ex4:words:3:pos":"noun","grammar:1279:ex4:words:4:zh":"(purpose)","grammar:1279:ex4:words:4:pos":"particle","grammar:1279:ex4:words:5:zh":"went","grammar:1279:ex4:words:5:note":"いきました","grammar:1279:ex4:words:5:pos":"verb","grammar:1279:ex4:points:0":"親と一緒に: together with my parents.","grammar:1279:ex4:points:1":"旅行に行く: to go on a trip.","grammar:1279:ex5:trans":"My parents always support me.","grammar:1279:ex5:structure":"〜を〜支えてくれます","grammar:1279:ex5:words:0:zh":"parents","grammar:1279:ex5:words:0:note":"おや","grammar:1279:ex5:words:0:pos":"noun","grammar:1279:ex5:words:1:zh":"(topic)","grammar:1279:ex5:words:1:pos":"particle","grammar:1279:ex5:words:2:zh":"I","grammar:1279:ex5:words:2:note":"わたし","grammar:1279:ex5:words:2:pos":"pronoun","grammar:1279:ex5:words:3:zh":"(object marker)","grammar:1279:ex5:words:3:pos":"particle","grammar:1279:ex5:words:4:zh":"always","grammar:1279:ex5:words:4:pos":"adverb","grammar:1279:ex5:words:5:zh":"support","grammar:1279:ex5:words:5:note":"ささえて","grammar:1279:ex5:words:5:pos":"verb","grammar:1279:ex5:words:6:zh":"makes (for me)","grammar:1279:ex5:words:6:pos":"auxiliary verb","grammar:1279:ex5:points:0":"❗〜てくれる: to do… (for me); 支える = to support.","grammar:1279:ex5:points:1":"私を支える: to support me."},"1280":{"example:1280:exzh":"A dragon appears in the movie.","example:1280:exzh2":"He is drawing a picture of a dragon.","example:1280:exzh3":"Dragons are legendary creatures.","example:1280:exzh4":"There is a dragon in this game.","example:1280:exzh5":"I read a book about dragons."},"1281":{"example:1281:exzh":"He gave a direct opinion.","example:1281:exzh2":"If you take this route, you can go straight to your destination.","example:1281:exzh3":"We need to solve the problem directly.","example:1281:exzh4":"I want to meet him directly.","example:1281:exzh5":"She is always direct."},"1282":{"example:1282:exzh":"There's a lot of news about terrorism today.","example:1282:exzh2":"Counterterrorism measures are very important.","example:1282:exzh3":"We support the victims of terrorism.","example:1282:exzh4":"The danger of terrorism is growing.","example:1282:exzh5":"We must be prepared for terrorist incidents."},"1283":{"example:1283:exzh":"We will carry out the plan.","example:1283:exzh2":"Putting it into practice is difficult.","example:1283:exzh3":"His plan is scheduled to be carried out.","example:1283:exzh4":"Please check before carrying it out.","example:1283:exzh5":"Some implementation is required."},"1284":{"example:1284:exzh":"He joined the army.","example:1284:exzh2":"The military plays the role of protecting the country.","example:1284:exzh3":"The military needs training.","example:1284:exzh4":"She is doing research on the military.","example:1284:exzh5":"Many countries have a military."},"1285":{"example:1285:exzh":"I read the newspaper every day.","example:1285:exzh2":"The newspaper has the latest news.","example:1285:exzh3":"She is a newspaper reporter.","example:1285:exzh4":"The newspaper delivery is late.","example:1285:exzh5":"I get information through the newspaper.","grammar:1285:ex:trans":"I read the newspaper every day.","grammar:1285:ex:structure":"〜を読みます","grammar:1285:ex:explain":"This is the transitive pattern 「〜を読む」, with the object marked by 「を」; 「読みます」 is the polite form and expresses a habit. The adverb 「毎日」 means every day. 「は」 marks the topic 「私」. The grammar is simple; the point is a vocabulary trap: Japanese 「新聞（しんぶん）」 means newspaper, not news as in Chinese, and news in Japanese is 「ニュース」. This is a classic example of same-form, different-meaning words, easy to misunderstand.","grammar:1285:ex:words:0:zh":"I","grammar:1285:ex:words:0:note":"わたし","grammar:1285:ex:words:0:pos":"pronoun","grammar:1285:ex:words:1:zh":"(topic)","grammar:1285:ex:words:1:pos":"particle","grammar:1285:ex:words:2:zh":"every day","grammar:1285:ex:words:2:note":"まいにち","grammar:1285:ex:words:2:pos":"adverb","grammar:1285:ex:words:3:zh":"newspaper","grammar:1285:ex:words:3:note":"しんぶん","grammar:1285:ex:words:3:pos":"noun","grammar:1285:ex:words:4:zh":"(object marker)","grammar:1285:ex:words:4:pos":"particle","grammar:1285:ex:words:5:zh":"look","grammar:1285:ex:words:5:note":"よみます","grammar:1285:ex:words:5:pos":"verb","grammar:1285:ex:points:0":"❗新聞（しんぶん）: newspaper (note: it does not mean news — that is ニュース).","grammar:1285:ex:points:1":"新聞を読む: to read the newspaper.","grammar:1285:ex2:trans":"The newspaper carries the latest news.","grammar:1285:ex2:structure":"〜には〜が載っています","grammar:1285:ex2:words:0:zh":"newspaper","grammar:1285:ex2:words:0:note":"しんぶん","grammar:1285:ex2:words:0:pos":"noun","grammar:1285:ex2:words:1:zh":"(location of existence)","grammar:1285:ex2:words:1:pos":"particle","grammar:1285:ex2:words:2:zh":"(contrast)","grammar:1285:ex2:words:2:pos":"particle","grammar:1285:ex2:words:3:zh":"latest","grammar:1285:ex2:words:3:note":"さいしん","grammar:1285:ex2:words:3:pos":"noun","grammar:1285:ex2:words:4:zh":"'s","grammar:1285:ex2:words:4:pos":"particle","grammar:1285:ex2:words:5:zh":"news","grammar:1285:ex2:words:5:note":"loanword","grammar:1285:ex2:words:5:pos":"noun","grammar:1285:ex2:words:6:zh":"(nominative)","grammar:1285:ex2:words:6:pos":"particle","grammar:1285:ex2:words:7:zh":"is printed","grammar:1285:ex2:words:7:note":"のっています","grammar:1285:ex2:words:7:pos":"verb","grammar:1285:ex2:points:0":"❗載る: to be printed, to be carried (intransitive verb); ニュース = news.","grammar:1285:ex2:points:1":"ニュースが載る: the news is printed.","grammar:1285:ex3:trans":"She is a newspaper reporter.","grammar:1285:ex3:structure":"〜は新聞記者です","grammar:1285:ex3:words:0:zh":"she","grammar:1285:ex3:words:0:note":"かのじょ","grammar:1285:ex3:words:0:pos":"pronoun","grammar:1285:ex3:words:1:zh":"(topic)","grammar:1285:ex3:words:1:pos":"particle","grammar:1285:ex3:words:2:zh":"reporter","grammar:1285:ex3:words:2:note":"しんぶんきしゃ","grammar:1285:ex3:words:2:pos":"noun","grammar:1285:ex3:words:3:zh":"is","grammar:1285:ex3:words:3:pos":"copula","grammar:1285:ex3:points:0":"❗新聞記者: newspaper reporter (新聞 + 記者).","grammar:1285:ex3:points:1":"記者: reporter.","grammar:1285:ex4:trans":"The newspaper delivery is late.","grammar:1285:ex4:structure":"〜の配達が遅れています","grammar:1285:ex4:words:0:zh":"newspaper","grammar:1285:ex4:words:0:note":"しんぶん","grammar:1285:ex4:words:0:pos":"noun","grammar:1285:ex4:words:1:zh":"'s","grammar:1285:ex4:words:1:pos":"particle","grammar:1285:ex4:words:2:zh":"delivery","grammar:1285:ex4:words:2:note":"はいたつ","grammar:1285:ex4:words:2:pos":"noun","grammar:1285:ex4:words:3:zh":"(nominative)","grammar:1285:ex4:words:3:pos":"particle","grammar:1285:ex4:words:4:zh":"is delayed","grammar:1285:ex4:words:4:note":"おくれています","grammar:1285:ex4:words:4:pos":"verb","grammar:1285:ex4:points:0":"❗配達: delivery; 遅れる = to be late (intransitive verb).","grammar:1285:ex4:points:1":"配達が遅れる: the delivery is late.","grammar:1285:ex5:trans":"Get information through the newspaper.","grammar:1285:ex5:structure":"〜を通じて〜を得ます","grammar:1285:ex5:words:0:zh":"newspaper","grammar:1285:ex5:words:0:note":"しんぶん","grammar:1285:ex5:words:0:pos":"noun","grammar:1285:ex5:words:1:zh":"(by way of)","grammar:1285:ex5:words:1:pos":"particle","grammar:1285:ex5:words:2:zh":"through","grammar:1285:ex5:words:2:note":"つうじて","grammar:1285:ex5:words:2:pos":"set phrase","grammar:1285:ex5:words:3:zh":"information","grammar:1285:ex5:words:3:note":"じょうほう","grammar:1285:ex5:words:3:pos":"noun","grammar:1285:ex5:words:4:zh":"(object marker)","grammar:1285:ex5:words:4:pos":"particle","grammar:1285:ex5:words:5:zh":"to obtain","grammar:1285:ex5:words:5:note":"えます","grammar:1285:ex5:words:5:pos":"verb","grammar:1285:ex5:points:0":"❗〜を通じて: through…; 情報を得る = to obtain information.","grammar:1285:ex5:points:1":"得る: to obtain.","exam:1285:zh":"Every morning I open the newspaper delivered to my home and read yesterday's news.","exam:1285:why":"What's delivered to your home every day and carries the latest news is 「新聞」. A 「日記」 may also record yesterday's events, but it isn't a news publication delivered daily.","exam_official:1285:zh":"My mother reads the newspaper every morning.","exam_official:1285:why":"「新聞」 is read 「しんぶん」. 「しんぷん」 wrongly changes 「ぶ」 to the semi-voiced 「ぷ」."},"1286":{"example:1286:exzh":"You feel lonely when you're alone.","example:1286:exzh2":"I'm feeling lonely.","example:1286:exzh3":"She is lonely on her own.","example:1286:exzh4":"I expressed my feelings of loneliness.","example:1286:exzh5":"The lonely nights go on.","grammar:1286:ex:trans":"When you are alone, you feel lonely.","grammar:1286:ex:structure":"〜といると寂しいです","grammar:1286:ex:explain":"The key point is the conjunctive particle 「〜と」, which expresses a natural, inevitable result: whenever A, then B. 「一人でいると寂しい」 means when you are alone, you feel lonely. 「と」 follows the dictionary form of a verb (いる) and introduces a constant cause and effect. In 「一人でいる」, 「で」 expresses a state. 「寂しい」 is an i-adjective. The whole sentence describes a general situation. Remember that when 「〜と」 marks a condition, it emphasizes the rule that every time A happens, B inevitably follows.","grammar:1286:ex:words:0:zh":"one person","grammar:1286:ex:words:0:note":"ひとり","grammar:1286:ex:words:0:pos":"noun","grammar:1286:ex:words:1:zh":"(a state)","grammar:1286:ex:words:1:pos":"particle","grammar:1286:ex:words:2:zh":"exist","grammar:1286:ex:words:2:pos":"verb","grammar:1286:ex:words:3:zh":"(as soon as…)","grammar:1286:ex:words:3:pos":"particle","grammar:1286:ex:words:4:zh":"lonely","grammar:1286:ex:words:4:note":"さびしい","grammar:1286:ex:words:4:pos":"adjective","grammar:1286:ex:words:5:zh":"(polite form)","grammar:1286:ex:words:5:pos":"copula","grammar:1286:ex:points:0":"❗寂しい（さびしい）: lonely (i-adjective); 〜と = whenever…, then…","grammar:1286:ex:points:1":"一人でいる: to be alone.","grammar:1286:ex2:trans":"I feel lonely.","grammar:1286:ex2:structure":"寂しい思いをしています","grammar:1286:ex2:words:0:zh":"lonely","grammar:1286:ex2:words:0:note":"さびしい","grammar:1286:ex2:words:0:pos":"adjective","grammar:1286:ex2:words:1:zh":"feelings","grammar:1286:ex2:words:1:note":"おもい","grammar:1286:ex2:words:1:pos":"noun","grammar:1286:ex2:words:2:zh":"(object marker)","grammar:1286:ex2:words:2:pos":"particle","grammar:1286:ex2:words:3:zh":"is doing","grammar:1286:ex2:words:3:pos":"verb","grammar:1286:ex2:points:0":"❗寂しい思いをする: to feel lonely (set phrase; 思いをする = to have a … feeling).","grammar:1286:ex2:points:1":"思いをする: to have a feeling.","grammar:1286:ex3:trans":"She is lonely on her own.","grammar:1286:ex3:structure":"〜は〜で寂しがっています","grammar:1286:ex3:words:0:zh":"she","grammar:1286:ex3:words:0:note":"かのじょ","grammar:1286:ex3:words:0:pos":"pronoun","grammar:1286:ex3:words:1:zh":"(topic)","grammar:1286:ex3:words:1:pos":"particle","grammar:1286:ex3:words:2:zh":"one person","grammar:1286:ex3:words:2:note":"ひとり","grammar:1286:ex3:words:2:pos":"noun","grammar:1286:ex3:words:3:zh":"(a state)","grammar:1286:ex3:words:3:pos":"particle","grammar:1286:ex3:words:4:zh":"seems lonely","grammar:1286:ex3:words:4:note":"さびしがっています","grammar:1286:ex3:words:4:pos":"verb","grammar:1286:ex3:points:0":"❗寂しがる: to seem lonely, to feel lonely (adjective + がる = to show signs of…).","grammar:1286:ex3:points:1":"寂しがる: to show that one is lonely.","grammar:1286:ex4:trans":"I expressed my lonely feelings.","grammar:1286:ex4:structure":"〜気持ちを伝えました","grammar:1286:ex4:words:0:zh":"lonely","grammar:1286:ex4:words:0:note":"さびしい","grammar:1286:ex4:words:0:pos":"adjective","grammar:1286:ex4:words:1:zh":"feeling","grammar:1286:ex4:words:1:note":"きもち","grammar:1286:ex4:words:1:pos":"noun","grammar:1286:ex4:words:2:zh":"(object marker)","grammar:1286:ex4:words:2:pos":"particle","grammar:1286:ex4:words:3:zh":"conveyed","grammar:1286:ex4:words:3:note":"つたえました","grammar:1286:ex4:words:3:pos":"verb","grammar:1286:ex4:points:0":"❗気持ちを伝える: to express one's feelings; 伝える = to convey.","grammar:1286:ex4:points:1":"寂しい気持ち: lonely feelings.","grammar:1286:ex5:trans":"Lonely nights go on and on.","grammar:1286:ex5:structure":"寂しい〜が続きます","grammar:1286:ex5:words:0:zh":"lonely","grammar:1286:ex5:words:0:note":"さびしい","grammar:1286:ex5:words:0:pos":"adjective","grammar:1286:ex5:words:1:zh":"night","grammar:1286:ex5:words:1:note":"よる","grammar:1286:ex5:words:1:pos":"noun","grammar:1286:ex5:words:2:zh":"(nominative)","grammar:1286:ex5:words:2:pos":"particle","grammar:1286:ex5:words:3:zh":"continues","grammar:1286:ex5:words:3:note":"つづきます","grammar:1286:ex5:words:3:pos":"verb","grammar:1286:ex5:points:0":"❗続く: to continue, to last (intransitive verb).","grammar:1286:ex5:points:1":"寂しい夜が続く: lonely nights continue."},"1287":{"example:1287:exzh":"I'm dating him.","example:1287:exzh2":"Time spent with friends is important.","example:1287:exzh3":"I'm thinking about dating someone new.","example:1287:exzh4":"She keeps company with her playmates.","example:1287:exzh5":"Dating is fun."},"1288":{"example:1288:exzh":"You must not tear it.","example:1288:exzh2":"I accidentally tore the paper.","example:1288:exzh3":"I intend to break that record.","example:1288:exzh4":"This wall cannot be destroyed.","example:1288:exzh5":"He broke his promise."},"1289":{"example:1289:exzh":"The person living next door is very kind.","example:1289:exzh2":"The elderly woman next door helped me.","example:1289:exzh3":"A nice smell is coming from the house next door.","example:1289:exzh4":"He's a friend sitting next to me.","example:1289:exzh5":"The room next door is quiet.","grammar:1289:ex:trans":"The person living next door is very kind.","grammar:1289:ex:structure":"〜に住んでいる人は〜です","grammar:1289:ex:explain":"Here is the core: the modifying clause 「〜に住んでいる人」 uses a whole verb clause to modify a noun. 「隣に住んでいる人」 means the person who lives next door; the verb phrase goes directly before 「人」 as a modifier, and 「に」 in 「隣に」 marks the place of residence. The predicate 「親切」 is a na-adjective plus 「です」. 「は」 marks the topic. The sentence shows how Japanese uses a verb clause plus a noun to express …的人, a typical example of a noun-modifying clause.","grammar:1289:ex:words:0:zh":"next door","grammar:1289:ex:words:0:note":"となり","grammar:1289:ex:words:0:pos":"noun","grammar:1289:ex:words:1:zh":"(place of residence)","grammar:1289:ex:words:1:pos":"particle","grammar:1289:ex:words:2:zh":"live (there)","grammar:1289:ex:words:2:note":"すんでいる","grammar:1289:ex:words:2:pos":"verb","grammar:1289:ex:words:3:zh":"person","grammar:1289:ex:words:3:note":"ひと","grammar:1289:ex:words:3:pos":"noun","grammar:1289:ex:words:4:zh":"(topic)","grammar:1289:ex:words:4:pos":"particle","grammar:1289:ex:words:5:zh":"extremely","grammar:1289:ex:words:5:pos":"adverb","grammar:1289:ex:words:6:zh":"kind","grammar:1289:ex:words:6:note":"しんせつ","grammar:1289:ex:words:6:pos":"na-adjective","grammar:1289:ex:words:7:zh":"(polite form)","grammar:1289:ex:words:7:pos":"copula","grammar:1289:ex:points:0":"❗隣（となり）: next door, neighbor; 隣に住む = to live next door.","grammar:1289:ex:points:1":"隣に住んでいる人: the person living next door.","grammar:1289:ex2:trans":"The elderly lady next door helped me out.","grammar:1289:ex2:structure":"〜が手伝ってくれました","grammar:1289:ex2:words:0:zh":"next door","grammar:1289:ex2:words:0:note":"となり","grammar:1289:ex2:words:0:pos":"noun","grammar:1289:ex2:words:1:zh":"'s","grammar:1289:ex2:words:1:pos":"particle","grammar:1289:ex2:words:2:zh":"elderly lady","grammar:1289:ex2:words:2:pos":"noun","grammar:1289:ex2:words:3:zh":"(nominative)","grammar:1289:ex2:words:3:pos":"particle","grammar:1289:ex2:words:4:zh":"help","grammar:1289:ex2:words:4:note":"てつだって","grammar:1289:ex2:words:4:pos":"verb","grammar:1289:ex2:words:5:zh":"did (for me)","grammar:1289:ex2:words:5:pos":"auxiliary verb","grammar:1289:ex2:points:0":"❗〜てくれる: to do… (for me); おばあさん = elderly lady, grandma.","grammar:1289:ex2:points:1":"隣のおばあさん: the elderly lady next door.","grammar:1289:ex3:trans":"A nice smell is coming from the house next door.","grammar:1289:ex3:structure":"〜から〜匂いがします","grammar:1289:ex3:words:0:zh":"next door","grammar:1289:ex3:words:0:note":"となり","grammar:1289:ex3:words:0:pos":"noun","grammar:1289:ex3:words:1:zh":"'s","grammar:1289:ex3:words:1:pos":"particle","grammar:1289:ex3:words:2:zh":"house","grammar:1289:ex3:words:2:note":"いえ","grammar:1289:ex3:words:2:pos":"noun","grammar:1289:ex3:words:3:zh":"from","grammar:1289:ex3:words:3:pos":"particle","grammar:1289:ex3:words:4:zh":"good","grammar:1289:ex3:words:4:note":"いい","grammar:1289:ex3:words:4:pos":"adjective","grammar:1289:ex3:words:5:zh":"smell","grammar:1289:ex3:words:5:note":"におい","grammar:1289:ex3:words:5:pos":"noun","grammar:1289:ex3:words:6:zh":"(nominative)","grammar:1289:ex3:words:6:pos":"particle","grammar:1289:ex3:words:7:zh":"to give off","grammar:1289:ex3:words:7:pos":"verb","grammar:1289:ex3:points:0":"❗匂いがする: to smell of something, to give off a scent (set phrase); 〜から = from…","grammar:1289:ex3:points:1":"良い匂い: a nice smell.","grammar:1289:ex4:trans":"He is the friend sitting next to me.","grammar:1289:ex4:structure":"〜に座っている〜です","grammar:1289:ex4:words:0:zh":"he","grammar:1289:ex4:words:0:note":"かれ","grammar:1289:ex4:words:0:pos":"pronoun","grammar:1289:ex4:words:1:zh":"(topic)","grammar:1289:ex4:words:1:pos":"particle","grammar:1289:ex4:words:2:zh":"beside, next to","grammar:1289:ex4:words:2:note":"となり","grammar:1289:ex4:words:2:pos":"noun","grammar:1289:ex4:words:3:zh":"(location of existence)","grammar:1289:ex4:words:3:pos":"particle","grammar:1289:ex4:words:4:zh":"is sitting","grammar:1289:ex4:words:4:note":"すわっている","grammar:1289:ex4:words:4:pos":"verb","grammar:1289:ex4:words:5:zh":"friend","grammar:1289:ex4:words:5:note":"ゆうじん","grammar:1289:ex4:words:5:pos":"noun","grammar:1289:ex4:words:6:zh":"is","grammar:1289:ex4:words:6:pos":"copula","grammar:1289:ex4:points:0":"❗隣に座る: to sit next to someone; 友人 = friend (written style).","grammar:1289:ex4:points:1":"隣に座っている: sitting next to someone.","grammar:1289:ex5:trans":"The room next door is quiet.","grammar:1289:ex5:structure":"〜の部屋は静かです","grammar:1289:ex5:words:0:zh":"next door","grammar:1289:ex5:words:0:note":"となり","grammar:1289:ex5:words:0:pos":"noun","grammar:1289:ex5:words:1:zh":"'s","grammar:1289:ex5:words:1:pos":"particle","grammar:1289:ex5:words:2:zh":"room","grammar:1289:ex5:words:2:note":"へや","grammar:1289:ex5:words:2:pos":"noun","grammar:1289:ex5:words:3:zh":"(topic)","grammar:1289:ex5:words:3:pos":"particle","grammar:1289:ex5:words:4:zh":"quiet","grammar:1289:ex5:words:4:note":"しずか","grammar:1289:ex5:words:4:pos":"na-adjective","grammar:1289:ex5:words:5:zh":"(polite form)","grammar:1289:ex5:words:5:pos":"copula","grammar:1289:ex5:points:0":"隣の部屋: the room next door.","grammar:1289:ex5:points:1":"静か: quiet."},"1290":{"example:1290:exzh":"I moved into a new apartment.","example:1290:exzh2":"This apartment is close to the station.","example:1290:exzh3":"The rent for the apartment is getting higher.","example:1290:exzh4":"She lives alone in an apartment.","example:1290:exzh5":"I talked with the apartment building manager.","grammar:1290:ex:trans":"I moved into a new apartment.","grammar:1290:ex:structure":"〜に引っ越しました","grammar:1290:ex:explain":"「アパート」 comes from English apartment, but in Japan it usually refers to a cheaper rental building of two or three stories; a reinforced-concrete upscale building is usually called 「マンション」. This sentence uses 「〜に引っ越す」 to mean moving into a place, with 「に」 marking the destination. Learners often mistake 「マンション」 for a luxury mansion, but it is really just a multi-unit residential building sturdier than an アパート.","grammar:1290:ex:words:0:zh":"new","grammar:1290:ex:words:0:note":"あたらしい","grammar:1290:ex:words:0:pos":"adjective","grammar:1290:ex:words:1:zh":"apartment","grammar:1290:ex:words:1:pos":"noun","grammar:1290:ex:words:2:zh":"to (destination of movement)","grammar:1290:ex:words:2:pos":"particle","grammar:1290:ex:words:3:zh":"moved","grammar:1290:ex:words:3:note":"ひっこしました; the masu-form past of 引っ越す","grammar:1290:ex:words:3:pos":"verb","grammar:1290:ex:points:0":"「アパートに引っ越しました」: 「アパート」 means a wooden or light-steel rental apartment, and moving in takes 「〜に引っ越す」.","grammar:1290:ex:points:1":"「に」 marks the destination of the move; 「引っ越しました」 is the masu-form past.","grammar:1290:ex:points:2":"The i-adjective 「新しい」 goes directly before a noun to modify it.","grammar:1290:ex2:trans":"This apartment is close to the station.","grammar:1290:ex2:structure":"noun＋は＋place＋から近いです","grammar:1290:ex2:words:0:zh":"this","grammar:1290:ex2:words:0:pos":"pre-noun adjectival","grammar:1290:ex2:words:1:zh":"apartment","grammar:1290:ex2:words:1:pos":"noun","grammar:1290:ex2:words:2:zh":"(topic)","grammar:1290:ex2:words:2:pos":"particle","grammar:1290:ex2:words:3:zh":"station","grammar:1290:ex2:words:3:note":"えき","grammar:1290:ex2:words:3:pos":"noun","grammar:1290:ex2:words:4:zh":"from, away from","grammar:1290:ex2:words:4:pos":"particle","grammar:1290:ex2:words:5:zh":"close","grammar:1290:ex2:words:5:note":"ちかい","grammar:1290:ex2:words:5:pos":"adjective","grammar:1290:ex2:words:6:zh":"(polite form)","grammar:1290:ex2:words:6:pos":"copula","grammar:1290:ex2:points:0":"「このアパート」: アパート is a rental apartment in Japan, two or three stories, built of wood or light steel.","grammar:1290:ex2:points:1":"「駅から近い」: から marks the starting point of distance, meaning close to…","grammar:1290:ex2:points:2":"i-adjective + です is the polite form.","grammar:1290:ex3:trans":"The rent for the apartment is getting more expensive.","grammar:1290:ex3:structure":"noun＋が＋i-adjective with い replaced by く＋なっています","grammar:1290:ex3:words:0:zh":"apartment","grammar:1290:ex3:words:0:pos":"noun","grammar:1290:ex3:words:1:zh":"(of)","grammar:1290:ex3:words:1:pos":"particle","grammar:1290:ex3:words:2:zh":"rent","grammar:1290:ex3:words:2:note":"やちん","grammar:1290:ex3:words:2:pos":"noun","grammar:1290:ex3:words:3:zh":"(subject)","grammar:1290:ex3:words:3:pos":"particle","grammar:1290:ex3:words:4:zh":"expensive","grammar:1290:ex3:words:4:note":"たかく; continuative form","grammar:1290:ex3:words:4:pos":"adjective","grammar:1290:ex3:words:5:zh":"become","grammar:1290:ex3:words:5:note":"なって; te-form","grammar:1290:ex3:words:5:pos":"verb","grammar:1290:ex3:words:6:zh":"(ongoing state)","grammar:1290:ex3:words:6:pos":"auxiliary verb","grammar:1290:ex3:points:0":"「アパートの家賃」: the money you pay every month for a rented アパート is called 「家賃（やちん）」.","grammar:1290:ex3:points:1":"「高くなって」: with an i-adjective, change the final 「い」 to 「く」 and add なる to mean become…","grammar:1290:ex3:points:2":"「〜ています」: shows that a change is still going on.","grammar:1290:ex4:trans":"She lives alone in an apartment.","grammar:1290:ex4:structure":"place＋で＋noun＋をしています","grammar:1290:ex4:words:0:zh":"she","grammar:1290:ex4:words:0:note":"かのじょ","grammar:1290:ex4:words:0:pos":"pronoun","grammar:1290:ex4:words:1:zh":"(topic)","grammar:1290:ex4:words:1:pos":"particle","grammar:1290:ex4:words:2:zh":"apartment","grammar:1290:ex4:words:2:pos":"noun","grammar:1290:ex4:words:3:zh":"(place of the action)","grammar:1290:ex4:words:3:pos":"particle","grammar:1290:ex4:words:4:zh":"lives alone","grammar:1290:ex4:words:4:note":"ひとりぐらし","grammar:1290:ex4:words:4:pos":"noun","grammar:1290:ex4:words:5:zh":"(object)","grammar:1290:ex4:words:5:pos":"particle","grammar:1290:ex4:words:6:zh":"do","grammar:1290:ex4:words:6:note":"して; te-form","grammar:1290:ex4:words:6:pos":"verb","grammar:1290:ex4:words:7:zh":"(ongoing state)","grammar:1290:ex4:words:7:pos":"auxiliary verb","grammar:1290:ex4:points:0":"「アパートで一人暮らし」: renting an アパート and living there alone—a common lifestyle for Japanese students and office workers.","grammar:1290:ex4:points:1":"「一人暮らしをしています」: noun＋をする turns it into an action, and 〜ている shows the current state of your life.","grammar:1290:ex4:points:2":"「アパートで」: で marks the place where you live and go about your life.","grammar:1290:ex5:trans":"I talked with the apartment manager.","grammar:1290:ex5:structure":"noun＋と＋話しました","grammar:1290:ex5:words:0:zh":"apartment","grammar:1290:ex5:words:0:pos":"noun","grammar:1290:ex5:words:1:zh":"(of)","grammar:1290:ex5:words:1:pos":"particle","grammar:1290:ex5:words:2:zh":"building manager","grammar:1290:ex5:words:2:note":"かんりにん","grammar:1290:ex5:words:2:pos":"noun","grammar:1290:ex5:words:3:zh":"(with…)","grammar:1290:ex5:words:3:pos":"particle","grammar:1290:ex5:words:4:zh":"to talk, to speak","grammar:1290:ex5:words:4:note":"はなしました; past masu-form","grammar:1290:ex5:words:4:pos":"verb","grammar:1290:ex5:points:0":"「アパートの管理人」: the person in charge of everything around an アパート is called 「管理人」.","grammar:1290:ex5:points:1":"「〜と話す」: と marks the person you talk with.","grammar:1290:ex5:points:2":"話す→話しました: in a godan (u-) verb, す changes to し before ました."},"1291":{"example:1291:exzh":"They won the match.","example:1291:exzh2":"I savored the moment of victory.","example:1291:exzh3":"This victory is special.","example:1291:exzh4":"We'll hold a party to celebrate the victory.","example:1291:exzh5":"The team charged ahead toward victory."},"1292":{"example:1292:exzh":"I like the color white best.","example:1292:exzh2":"White flowers are blooming.","example:1292:exzh3":"He's wearing a white shirt.","example:1292:exzh4":"There was a lot of white snow this winter.","example:1292:exzh5":"A white dog is playing in the park.","grammar:1292:ex:trans":"I like white the best.","grammar:1292:ex:structure":"〜は〜が一番好きです","grammar:1292:ex:explain":"「私は」 presents the topic of what is being talked about. 「白い」 modifies 「色」 directly to form the thing you like, white, which is then marked with 「が」. 「一番」 modifies 「好き」 and means the most. 「白い色」 is also often said simply as the noun 「白」.","grammar:1292:ex:words:0:zh":"I","grammar:1292:ex:words:0:note":"わたし","grammar:1292:ex:words:0:pos":"pronoun","grammar:1292:ex:words:1:zh":"(topic)","grammar:1292:ex:words:1:pos":"particle","grammar:1292:ex:words:2:zh":"white","grammar:1292:ex:words:2:note":"しろい","grammar:1292:ex:words:2:pos":"i-adjective","grammar:1292:ex:words:3:zh":"color","grammar:1292:ex:words:3:note":"いろ","grammar:1292:ex:words:3:pos":"noun","grammar:1292:ex:words:4:zh":"(the thing liked)","grammar:1292:ex:words:4:pos":"particle","grammar:1292:ex:words:5:zh":"the most","grammar:1292:ex:words:5:note":"いちばん","grammar:1292:ex:words:5:pos":"adverb","grammar:1292:ex:words:6:zh":"to like","grammar:1292:ex:words:6:note":"すき","grammar:1292:ex:words:6:pos":"na-adjective","grammar:1292:ex:words:7:zh":"(polite affirmative judgment)","grammar:1292:ex:words:7:pos":"auxiliary verb","grammar:1292:ex:points:0":"「好き」 is a na-adjective, and the thing you like is usually marked with 「が」.","grammar:1292:ex:points:1":"「一番＋形容詞」 shows the highest degree within a range of comparison.","grammar:1292:ex2:trans":"White flowers are blooming.","grammar:1292:ex2:structure":"〜が咲いています","grammar:1292:ex2:words:0:zh":"white","grammar:1292:ex2:words:0:note":"しろい","grammar:1292:ex2:words:0:pos":"adjective","grammar:1292:ex2:words:1:zh":"flowers","grammar:1292:ex2:words:1:note":"はな","grammar:1292:ex2:words:1:pos":"noun","grammar:1292:ex2:words:2:zh":"(nominative)","grammar:1292:ex2:words:2:pos":"particle","grammar:1292:ex2:words:3:zh":"are blooming","grammar:1292:ex2:words:3:note":"さいています","grammar:1292:ex2:words:3:pos":"verb","grammar:1292:ex2:points:0":"白い花: white flower.","grammar:1292:ex2:points:1":"咲く: to bloom (intransitive verb; takes が).","grammar:1292:ex3:trans":"He is wearing a white shirt.","grammar:1292:ex3:structure":"〜を着ています","grammar:1292:ex3:words:0:zh":"he","grammar:1292:ex3:words:0:note":"かれ","grammar:1292:ex3:words:0:pos":"pronoun","grammar:1292:ex3:words:1:zh":"(topic)","grammar:1292:ex3:words:1:pos":"particle","grammar:1292:ex3:words:2:zh":"white","grammar:1292:ex3:words:2:note":"しろい","grammar:1292:ex3:words:2:pos":"adjective","grammar:1292:ex3:words:3:zh":"shirt","grammar:1292:ex3:words:3:note":"loanword","grammar:1292:ex3:words:3:pos":"noun","grammar:1292:ex3:words:4:zh":"(object marker)","grammar:1292:ex3:words:4:pos":"particle","grammar:1292:ex3:words:5:zh":"Wearing","grammar:1292:ex3:words:5:note":"きています","grammar:1292:ex3:words:5:pos":"verb","grammar:1292:ex3:points:0":"白いシャツ: a white shirt.","grammar:1292:ex3:points:1":"〜を着ている: to be wearing …","grammar:1292:ex4:trans":"There was a lot of white snow this winter.","grammar:1292:ex4:structure":"〜が多かった","grammar:1292:ex4:words:0:zh":"this","grammar:1292:ex4:words:0:pos":"pre-noun adjectival","grammar:1292:ex4:words:1:zh":"winter","grammar:1292:ex4:words:1:note":"ふゆ","grammar:1292:ex4:words:1:pos":"noun","grammar:1292:ex4:words:2:zh":"(topic)","grammar:1292:ex4:words:2:pos":"particle","grammar:1292:ex4:words:3:zh":"white","grammar:1292:ex4:words:3:note":"しろい","grammar:1292:ex4:words:3:pos":"adjective","grammar:1292:ex4:words:4:zh":"snow","grammar:1292:ex4:words:4:note":"ゆき","grammar:1292:ex4:words:4:pos":"noun","grammar:1292:ex4:words:5:zh":"(nominative)","grammar:1292:ex4:words:5:pos":"particle","grammar:1292:ex4:words:6:zh":"(past) a lot","grammar:1292:ex4:words:6:note":"おおかった","grammar:1292:ex4:words:6:pos":"adjective","grammar:1292:ex4:points:0":"白い雪: white snow.","grammar:1292:ex4:points:1":"多かった: (past) was a lot.","grammar:1292:ex5:trans":"A white dog is playing in the park.","grammar:1292:ex5:structure":"〜が〜で遊んでいる","grammar:1292:ex5:words:0:zh":"white","grammar:1292:ex5:words:0:note":"しろい","grammar:1292:ex5:words:0:pos":"adjective","grammar:1292:ex5:words:1:zh":"dog","grammar:1292:ex5:words:1:note":"いぬ","grammar:1292:ex5:words:1:pos":"noun","grammar:1292:ex5:words:2:zh":"(nominative)","grammar:1292:ex5:words:2:pos":"particle","grammar:1292:ex5:words:3:zh":"park","grammar:1292:ex5:words:3:note":"こうえん","grammar:1292:ex5:words:3:pos":"noun","grammar:1292:ex5:words:4:zh":"(place)","grammar:1292:ex5:words:4:pos":"particle","grammar:1292:ex5:words:5:zh":"are playing","grammar:1292:ex5:words:5:note":"あそんでいる","grammar:1292:ex5:words:5:pos":"verb","grammar:1292:ex5:points:0":"白い犬: a white dog.","grammar:1292:ex5:points:1":"〜で遊ぶ: to play in/at …","exam:1292:zh":"This shirt is the same color as milk—a white shirt with nothing written on it.","exam:1292:why":"Milk is white, so 「白い」 is the answer. 「青い」 means blue or green, which doesn't match the color of milk.","exam_official:1292:zh":"I'm wearing a white shirt today.","exam_official:1292:why":"「しろい」 is written 「白い」. 「百」 looks similar to 「白」 but has one extra horizontal stroke, and it doesn't mean white."},"1293":{"example:1293:exzh":"I'd like to hear everyone's opinion.","example:1293:exzh2":"This project is moving forward with the whole team.","example:1293:exzh3":"We reported the overall progress at the meeting.","example:1293:exzh4":"It's important that everyone works together.","example:1293:exzh5":"Looking at the whole picture, it's a good result."},"1294":{"example:1294:exzh":"He's giving it his all.","example:1294:exzh2":"This team will do everything it can to succeed.","example:1294:exzh3":"We always make a point of giving our all.","example:1294:exzh4":"She says it's important to give your all for the customers.","example:1294:exzh5":"Everyone worked together and gave it their all."},"1295":{"example:1295:exzh":"He's my business partner.","example:1295:exzh2":"I'll travel with a partner.","example:1295:exzh3":"I need a partner I can trust.","example:1295:exzh4":"He's working with other partners.","example:1295:exzh5":"She's my partner."},"1296":{"example:1296:exzh":"Oni are scary.","example:1296:exzh2":"Japanese oni are legendary creatures.","example:1296:exzh3":"An oni appears in this movie.","example:1296:exzh4":"We throw beans at oni.","example:1296:exzh5":"There was a person wearing an oni mask."},"1297":{"example:1297:exzh":"He is my partner.","example:1297:exzh2":"The teacher became the students' ally.","example:1297:exzh3":"It's reassuring to have a friend on your side.","example:1297:exzh4":"For her, her family is her greatest ally.","example:1297:exzh5":"Let's work together as allies."},"1298":{"example:1298:exzh":"He's the owner of that land.","example:1298:exzh2":"I'll show you my belongings.","example:1298:exzh3":"I studied the law on ownership.","example:1298:exzh4":"This car is his property.","example:1298:exzh5":"Managing property is difficult."},"1299":{"example:1299:exzh":"My older brother is a really reliable guy.","example:1299:exzh2":"I'm going out to have fun with my older brother.","example:1299:exzh3":"He's like an older brother to me.","example:1299:exzh4":"My older brother kindly taught me.","example:1299:exzh5":"I'm waiting for my older brother to come home."}};